// =====================================================================
// W44 d1：为什么要预算 + finance_budget 的表设计。
//
// 这一天在解决什么问题：
//   ① 「这个月花超了」在没有预算的库里到底能不能判定？——同一份三个月
//      流水跑三条「看起来都合理」的替代判据，让它们对同月给出相反结论。
//   ② 一条预算必须同时回答四个问题：对谁设限、按什么周期归零、额度多少、
//      什么时候算超 —— 落成 finance_budget 的四个字段。
//   ③ 为什么 used_cents 不在 finance_budget 上（tech-plan §5.4 把「按周期
//      归零」的语义放在 finance_budget_period 那一行上）。
//
// 本机没有 PostgreSQL：第 4 节 DDL 由 GORM AutoMigrate DryRun 真实生成，
// 第 5 节是手写生产迁移（AutoMigrate 不进生产）。审计列在迁移里给全。
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d01
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

var fixedNow = time.Date(2026, 4, 1, 9, 0, 0, 0, time.UTC)

func hdr(s string) { fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s))) }

func yuan(c int64) string {
	if c < 0 {
		return fmt.Sprintf("-%d.%02d", -c/100, -c%100)
	}
	return fmt.Sprintf("%d.%02d", c/100, c%100)
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{DryRun: true, DisableAutomaticPing: true,
		NowFunc: func() time.Time { return fixedNow },
		Logger:  logger.Default.LogMode(logger.Silent)})
	if err != nil {
		panic(err)
	}
	return db
}

// Budget 只存「规则是什么」：作用域 scope+scope_ref、周期 period、额度、阈值。
// 随周期变化的量（used_cents / alerted_at）一个都不在这张表上。
type Budget struct {
	ID              string  `gorm:"column:id;primaryKey;type:uuid"`
	FamilyID        string  `gorm:"column:family_id;type:uuid;not null"`
	Scope           string  `gorm:"column:scope;type:varchar(16);not null"`      // family / category / member
	ScopeRef        *string `gorm:"column:scope_ref;type:uuid"`                  // =category→分类id，=member→成员id，=family→NULL
	Period          string  `gorm:"column:period;type:varchar(8);not null"`      // month / quarter / year
	AmountCents     int64   `gorm:"column:amount_cents;type:bigint;not null"`    // 每周期额度，整数分（铁律 1）
	AlertThreshold  int     `gorm:"column:alert_threshold;not null;default:100"` // 80 预警 / 100 超支
	CarryOver       bool    `gorm:"column:carry_over;not null;default:false"`
	IsActive        bool    `gorm:"column:is_active;not null;default:true"`
	ClientRequestID string  `gorm:"column:client_request_id;type:uuid;not null"` // 幂等键（铁律 3）
	Version         int     `gorm:"column:version;not null;default:1"`
	DeletedAt       gorm.DeletedAt
}

func (Budget) TableName() string { return "finance_budget" }

// BudgetPeriod 是「按周期归零」的载体：一个预算 × 一个周期 = 一行，旧行永不改写。
type BudgetPeriod struct {
	ID             string     `gorm:"column:id;primaryKey;type:uuid"`
	BudgetID       string     `gorm:"column:budget_id;type:uuid;not null"`
	Period         string     `gorm:"column:period;type:varchar(10);not null"` // 2026-03 / 2026-Q1 / 2026
	AmountCents    int64      `gorm:"column:amount_cents;type:bigint;not null"`
	UsedCents      int64      `gorm:"column:used_cents;type:bigint;not null;default:0"`
	CarriedInCents int64      `gorm:"column:carried_in_cents;type:bigint;not null;default:0"`
	AlertedAt      *time.Time `gorm:"column:alerted_at;type:timestamptz"` // 本周期已外发超支事件（d4）
	Version        int        `gorm:"column:version;not null;default:1"`
	DeletedAt      gorm.DeletedAt
}

func (BudgetPeriod) TableName() string { return "finance_budget_period" }

func main() {
	hdr("1. 「这个月花超了」：没有预算时，这句话有三种互斥的判法")
	exp := map[string]int64{"2025-02": 460000, "2025-03": 540000,
		"2026-01": 512345, "2026-02": 498120, "2026-03": 531680}
	months := []string{"2026-01", "2026-02", "2026-03"}
	var sum int64
	for _, m := range months {
		sum += exp[m]
	}
	avg := sum / int64(len(months))
	fmt.Println("  实际支出（单位：分 → 元）：")
	for _, m := range months {
		fmt.Printf("    %s  %10d 分  = %10s 元\n", m, exp[m], yuan(exp[m]))
	}
	fmt.Printf("  参照：去年同月 2025-02=%s 元、2025-03=%s 元；今年三月均值=%s 元\n",
		yuan(exp["2025-02"]), yuan(exp["2025-03"]), yuan(avg))
	// 三条替代判据各自的参照值（都从 exp 里算出来，不是写死的）
	rules := []struct {
		Name  string
		Ref02 int64
		Ref03 int64
	}{
		{"A：环比上一自然月", exp["2026-01"], exp["2026-02"]},
		{"B：比三个月均值", avg, avg},
		{"C：比去年同月", exp["2025-02"], exp["2025-03"]},
	}
	v := func(b bool) string {
		if b {
			return "花超了"
		}
		return "没超"
	}
	fmt.Printf("\n  %-20s %-12s %-12s %s\n", "替代判据", "2026-02", "2026-03", "两条依据（本月支出 vs 参照值）")
	fmt.Println("  " + strings.Repeat("-", 104))
	for _, r := range rules {
		fmt.Printf("  %-20s %-12s %-12s %s vs %s ｜ %s vs %s\n", r.Name,
			v(exp["2026-02"] > r.Ref02), v(exp["2026-03"] > r.Ref03),
			yuan(exp["2026-02"]), yuan(r.Ref02), yuan(exp["2026-03"]), yuan(r.Ref03))
	}
	fmt.Println("\n★ 三条判据在同一份数据上都「算得出来」，结论却互相矛盾：2026-03 按 A/B 超、按 C 不")
	fmt.Println("  超；2026-02 按 A/B 不超、按 C 超。所以「这个月花超了」在没有预算的库里不是**事实**，")
	fmt.Println("  是**口径之争**。预算的全部意义：这条线由用户显式设定（amount_cents + 阈值），判定")
	fmt.Println("  退化成一次整数比较（d3）——可复现、可解释、可被 PRD 18.3#4 机器验收。")

	hdr("2. 一条预算必须同时回答的四个问题 → 四个字段")
	cols := []struct{ Q, Field, Values, IfMissing string }{
		{"对谁设限？", "scope + scope_ref", "family / category / member", "只有家庭总额就说不出「餐饮花超」；只有分类就说不出「总支出超标」"},
		{"按什么周期归零？", "period", "month / quarter / year", "没有 period 答不了「3 月没用完能否带进 4 月」，也建不起 d6 的未设周期口径"},
		{"额度是多少？", "amount_cents（分）", "BIGINT 整数分，禁浮点", "用 float64 元：累加偏差 + 阈值边界判定翻转（d3 真跑出偏差值）"},
		{"什么时候算超？", "alert_threshold", "80 预警 / 100 超支", "硬编码 100% 就否掉了 PRD 18.3#4 的「可设 80% 预警」"},
	}
	fmt.Printf("  %-16s %-20s %-24s %s\n", "问题", "字段", "取值", "缺了会答不上什么")
	fmt.Println("  " + strings.Repeat("-", 108))
	for _, c := range cols {
		fmt.Printf("  %-16s %-20s %-24s %s\n", c.Q, c.Field, c.Values, c.IfMissing)
	}
	fmt.Println("  scope='family' 时 scope_ref 必须 NULL、scope='category' 时必须非 NULL ——")
	fmt.Println("  这条不变量交给数据库的 CHECK 守（第 5 节），不靠应用层自觉。")

	hdr("3. 为什么 used_cents 不在 finance_budget 上：单表方案的死法")
	amount, used := int64(560000), exp["2026-03"]
	left := amount - used
	fmt.Printf("  方案 A（used 直接挂预算行）：3 月周期结束时的这一行\n")
	fmt.Printf("    budget=bud-01 amount=%s used=%s → 判定：%s（used>amount 才算超）\n",
		yuan(amount), yuan(used), map[bool]string{true: "已超", false: "未超"}[used > amount])
	fmt.Printf("    本期剩余 = %s − %s = %s 元（这是结转的唯一依据）\n", yuan(amount), yuan(used), yuan(left))
	fmt.Println("    4 月 1 日 00:00 归零：UPDATE finance_budget SET used_cents = 0 WHERE id='bud-01';")
	fmt.Printf("    归零后这一行 used=%s —— 上一期的数字被就地覆盖\n", yuan(0))
	fmt.Println("  4 月 1 日之后仍然要能回答、但已经答不出的三个问题：")
	for _, q := range []string{
		"「3 月的月报里预算用了多少？」→ 库里查不到了",
		"「3 月到底超没超、超多少？」→ 无法复现，那条 UPDATE 不可逆",
		fmt.Sprintf("「3 月剩下的 %s 元要不要结转进 4 月？」→ 结转要先读上期 used，而它已经没了", yuan(left))} {
		fmt.Println("     ✗ " + q)
	}
	fmt.Println("  方案 B（tech-plan §5.4）：定义行不动，每个周期插一行存 used。")
	rows := []BudgetPeriod{
		{BudgetID: "bud-01", Period: "2026-03", AmountCents: amount, UsedCents: used},
		{BudgetID: "bud-01", Period: "2026-04", AmountCents: amount, CarriedInCents: left},
	}
	for _, r := range rows {
		fmt.Printf("    %-8s %s amount=%10s used=%10s carried_in=%10s\n",
			r.BudgetID, r.Period, yuan(r.AmountCents), yuan(r.UsedCents), yuan(r.CarriedInCents))
	}
	fmt.Println("  归零对 3 月那一行的影响：0 次写。历史可重算，结转有依据。")
	fmt.Println("  ★ 分工一句话：budget 回答「规则是什么」，budget_period 回答「这一期用了多少」。")

	hdr("4. GORM AutoMigrate DryRun 真实生成的 DDL（不是手写的）")
	fmt.Println("  --- DryRun 打印出来的语句，用来对照字段名与类型 ---")
	dryDB().AutoMigrate(&Budget{}, &BudgetPeriod{})

	hdr("5. 生产迁移的最终形态（migrations/finance/，AutoMigrate 不进生产）")
	ddl := `CREATE TABLE finance.finance_budget (
  id UUID PRIMARY KEY, family_id UUID NOT NULL,
  scope VARCHAR(16) NOT NULL, scope_ref UUID,
  period VARCHAR(8) NOT NULL, amount_cents BIGINT NOT NULL,
  alert_threshold SMALLINT NOT NULL DEFAULT 100,
  carry_over BOOLEAN NOT NULL DEFAULT FALSE, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  client_request_id UUID NOT NULL, version INTEGER NOT NULL DEFAULT 1,
  deleted_at TIMESTAMPTZ, deleted_by UUID,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT ck_budget_scope CHECK (scope IN ('family','category','member')),
  CONSTRAINT ck_budget_scope_ref CHECK (                  -- 不变量交给数据库，不靠自觉
    (scope = 'family' AND scope_ref IS NULL) OR (scope <> 'family' AND scope_ref IS NOT NULL)),
  CONSTRAINT ck_budget_period CHECK (period IN ('month','quarter','year')),
  CONSTRAINT ck_budget_amount CHECK (amount_cents > 0),
  CONSTRAINT ck_budget_threshold CHECK (alert_threshold BETWEEN 50 AND 100));
-- 幂等：同一 client_request_id 重放不产生第二条预算（软删行不占用，S10 d26 口径）
CREATE UNIQUE INDEX uq_budget_crid ON finance.finance_budget (family_id, client_request_id)
  WHERE deleted_at IS NULL;
-- 同一作用域 + 同一周期只允许一条活跃预算，否则「哪条说了算」无解
CREATE UNIQUE INDEX uq_budget_scope ON finance.finance_budget
  (family_id, scope, COALESCE(scope_ref::text,'-'), period) WHERE deleted_at IS NULL AND is_active;
CREATE TABLE finance.finance_budget_period (
  id UUID PRIMARY KEY, budget_id UUID NOT NULL REFERENCES finance.finance_budget(id),
  family_id UUID NOT NULL, period VARCHAR(10) NOT NULL,  -- 2026-03 / 2026-Q1 / 2026
  amount_cents BIGINT NOT NULL, used_cents BIGINT NOT NULL DEFAULT 0,
  carried_in_cents BIGINT NOT NULL DEFAULT 0, alerted_at TIMESTAMPTZ,
  version INTEGER NOT NULL DEFAULT 1, deleted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- 周期编码与「时间窗五档」同源：三种形态，各一条正则，没有第四种
  CONSTRAINT ck_bp_period_fmt CHECK (
    period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$' OR period ~ '^[0-9]{4}-Q[1-4]$' OR period ~ '^[0-9]{4}$'),
  CONSTRAINT ck_bp_used_nonneg CHECK (used_cents >= 0),
  CONSTRAINT uq_bp_budget_period UNIQUE (budget_id, period)  -- 归零=插新行，旧行永不重复
);
CREATE INDEX idx_bp_family_period ON finance.finance_budget_period (family_id, period);`
	fmt.Println(ddl)

	hdr("6. period 编码是「时间窗」词表的一部分（W46 直接复用这两列）")
	windows := []struct{ Win, Enc, PeriodCol, Hit string }{
		{"day", "2026-03-14", "—（预算没有日档）", "无周期行可命中 → d6 的未设该周期预算"},
		{"week", "2026-W11", "—（预算没有周档）", "无周期行可命中 → d6 的未设该周期预算"},
		{"month", "2026-03", "month", "budget_period.period='2026-03'"},
		{"quarter", "2026-Q1", "quarter", "budget_period.period='2026-Q1'"},
		{"year", "2026", "year", "budget_period.period='2026'"},
	}
	fmt.Printf("  %-8s %-12s %-22s %s\n", "时间窗档", "编码", "预算周期取值", "聚合侧能不能命中周期行")
	fmt.Println("  " + strings.Repeat("-", 96))
	for _, w := range windows {
		fmt.Printf("  %-8s %-12s %-22s %s\n", w.Win, w.Enc, w.PeriodCol, w.Hit)
	}
	fmt.Println("  ★ 这张对照表今天钉死，因为 W46 的报表聚合只做一件事：按窗口编码算出 used，再 LEFT")
	fmt.Println("    JOIN finance_budget_period ON period。词表同源一次，W46 就不必再造第二套 period")
	fmt.Println("    字符串，也就不会出现 2026/3、202603、2026-3（PRD 4.5.3 ⑬：只允许一种编码）。")

	hdr("7. 今天的判据（程序逐条自查）")
	checks := []struct {
		OK  bool
		Msg string
	}{
		{exp["2026-03"] > avg && exp["2026-03"] < exp["2025-03"], "同一份流水上三条替代判据对同月结论相反（第 1 节已跑出）"},
		{len(cols) == 4 && cols[1].Values == "month / quarter / year", "预算四要素齐：作用域 / 周期 / 额度（分）/ 阈值"},
		{left > 0 && rows[0].UsedCents == exp["2026-03"], "周期归零不写旧行：3 月的 used 与剩余永远可重算"},
		{strings.Contains(ddl, "UNIQUE (budget_id, period)") && strings.Contains(ddl, "client_request_id"), "UNIQUE(budget_id,period) 与幂等键都落库（铁律 3）"},
		{windows[2].Enc == "2026-03" && windows[3].Enc == "2026-Q1" && windows[0].Hit != "", "period 编码与时间窗五档同源，day/week 没有预算档"},
	}
	all := true
	for _, c := range checks {
		mark := "✅"
		if !c.OK {
			mark, all = "❌", false
		}
		fmt.Printf("  %s %s\n", mark, c.Msg)
	}
	if all {
		fmt.Println("\nW44 d1 通过。明天解决归属：一笔流水落进哪个周期桶、算进哪条预算。")
	}
}

// =====================================================================
// W44 d2：预算的周期与归属 —— 一笔流水落进哪个桶、算进哪条预算。
//
// 这一天在解决什么问题：
//   ① 「月度桶」不是 UTC 的月份字符串：家庭时区、occurred_at vs
//      created_at 两处都会把同一笔钱放进不同的桶（程序真跑出差额）。
//   ② used 的分子口径：转账、收入、退款（负数支出）、软删行、私密行，
//      五种判法各自进不进 used，进错了差多少钱。
//   ③ 家庭级总额预算与分类级预算并存：同一条流水被两个预算计入是
//      **设计**而不是 bug；「家庭 used = Σ分类 used」才是 bug。
//   ④ 跨期改期要重算哪几个桶、跨期退款冲抵哪一期（增量维护的口径）。
//
// 本机没有 PostgreSQL：内存 slice 模拟 finance_transaction 与两张预算表。
// 每段给出的 SQL 是起真库后要原样复跑的同一组断言。
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d02
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

var famTZ = time.FixedZone("CST", 8*3600) // 真实项目：time.LoadLocation(family.Timezone)，查不到必须报错
var utc = time.UTC

func hdr(s string) { fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s))) }

func yuan(c int64) string {
	if c < 0 {
		return fmt.Sprintf("-%d.%02d", -c/100, -c%100)
	}
	return fmt.Sprintf("%d.%02d", c/100, c%100)
}

func tbl(ws []int, header []string, rows [][]string) {
	fmt.Print("  ")
	for i, h := range header {
		fmt.Printf("%-*s  ", ws[i%len(ws)], h)
	}
	fmt.Println()
	fmt.Println("  " + strings.Repeat("-", 94))
	for _, r := range rows {
		fmt.Print("  ")
		for i, c := range r {
			fmt.Printf("%-*s  ", ws[i%len(ws)], c)
		}
		fmt.Println()
	}
}

type Txn struct {
	ID, Type, CategoryID  string
	AmountCents           int64 // expense 为正、退款为负；income / transfer 恒为正
	OccurredAt, CreatedAt time.Time
	Deleted, Private      bool // Private = 行级可见性，只有作者与管理员可读，但仍是这家人的支出
}

type Bud struct {
	ID, Scope, ScopeRef string
	AmountCents         int64
}

// bucket 按「周期口径 + 时区」把绝对时刻放进桶，编码与时间窗五档同源。
func bucket(t time.Time, loc *time.Location, period string) string {
	lt := t.In(loc)
	switch period {
	case "month":
		return lt.Format("2006-01")
	case "quarter":
		return fmt.Sprintf("%d-Q%d", lt.Year(), (int(lt.Month())-1)/3+1)
	case "year":
		return lt.Format("2006")
	}
	return "?"
}

func correct(t Txn) bool { return !t.Deleted && t.Type == "expense" } // used 的分子口径

func sumOf(list []Txn, f func(Txn) bool) int64 {
	var s int64
	for _, t := range list {
		if f(t) {
			s += t.AmountCents
		}
	}
	return s
}

// bucketsOf 模拟 SELECT date_trunc('month', occurred_at AT TIME ZONE $tz), SUM(...) GROUP BY 1。
func bucketsOf(list []Txn, when func(Txn) time.Time) map[string]int64 {
	m := map[string]int64{}
	for _, t := range list {
		if correct(t) {
			m[bucket(when(t), famTZ, "month")] += t.AmountCents
		}
	}
	return m
}

func main() {
	D := func(y, mo, d, h, mi int) time.Time { return time.Date(y, time.Month(mo), d, h, mi, 0, 0, famTZ) }
	txns := []Txn{
		{"t1", "expense", "cat-food", 48000, D(2026, 3, 2, 12, 0), D(2026, 3, 2, 12, 0), false, false},
		{"t2", "expense", "cat-food", 120000, D(2026, 3, 18, 19, 30), D(2026, 3, 18, 19, 30), false, false},
		{"t3", "expense", "cat-traffic", 26000, D(2026, 3, 21, 8, 10), D(2026, 3, 21, 8, 10), false, false},
		{"t4", "expense", "cat-shopping", 88000, D(2026, 3, 28, 20, 0), D(2026, 4, 2, 9, 15), false, false}, // 4 月补记的 3 月支出
		{"t5", "income", "cat-salary", 800000, D(2026, 3, 5, 10, 0), D(2026, 3, 5, 10, 0), false, false},
		{"t6", "transfer", "cat-saving", 100000, D(2026, 3, 9, 11, 0), D(2026, 3, 9, 11, 0), false, false},
		{"t7", "expense", "cat-food", -18000, D(2026, 3, 25, 14, 0), D(2026, 3, 25, 14, 0), false, false},                                           // 退款
		{"t8", "expense", "cat-medical", 30000, time.Date(2026, 3, 31, 16, 30, 0, 0, utc), time.Date(2026, 3, 31, 16, 30, 0, 0, utc), false, false}, // UTC 还在 3 月
		{"t9", "expense", "cat-food", 20000, D(2026, 3, 11, 12, 0), D(2026, 3, 11, 12, 0), true, false},                                             // 已软删
		{"t10", "expense", "cat-traffic", 15000, D(2026, 3, 14, 9, 0), D(2026, 3, 14, 9, 0), false, true},                                           // 私密行
	}
	buds := []Bud{{"bud-family", "family", "-", 600000}, {"bud-food", "category", "cat-food", 120000}, {"bud-traffic", "category", "cat-traffic", 30000}}
	in3 := func(t Txn) bool { return bucket(t.OccurredAt, famTZ, "month") == "2026-03" }

	hdr("1. 月度桶怎么切：同一个绝对时刻，两种时区落进两个桶")
	var rows [][]string
	diff := 0
	for _, t := range txns {
