		d := "—"
		if r.Name != "全量重算（真相）" {
			d = fmt.Sprintf("03 差 %s ｜ 04 差 %s", yuan(r.M["2026-03"]-truth["2026-03"]), yuan(r.M["2026-04"]-truth["2026-04"]))
