	fmt.Println(`  正确写法（同一事务两条 UPDATE，缺一不可）：
    UPDATE finance_budget_period SET used_cents = used_cents - 88000, version = version + 1
     WHERE budget_id = $1 AND period = '2026-03';        -- 旧桶：必须减
    UPDATE finance_budget_period SET used_cents = used_cents + 88000, version = version + 1
     WHERE budget_id = $1 AND period = '2026-04';        -- 新桶：必须加`)
	fmt.Println("  场景 B：4 月退掉 3 月买的 300.00 元（occurred_at 在 4 月的负数支出）——口径二选一定版：")
	fmt.Println("    本项目「按 occurred_at 落桶」= 退款冲抵**退款发生期**，与报表口径同源（W47 环比读同一")
	fmt.Println("    个数）。「冲抵原消费期」会改写 3 月已结算的历史 used，而 d4 的 alerted_at 已落在那一行")
	fmt.Println("    上 → 已发出的超支事件失去依据。选了就不许两个都不选，也不许同一条链上两种混用。")

	hdr("6. 今天的判据（程序逐条自查）")
	checks := []struct {
		OK  bool
		Msg string
	}{
		{diff == 1, "时区边界真的会换桶（t8 一笔）：桶边界 = 家庭时区的自然月"},
		{byOcc["2026-03"] != byCre["2026-03"], "occurred_at 与 created_at 分桶的差额已跑出（补记场景）"},
		{sumOf(txns, func(t Txn) bool { return in3(t) && rules[3].F(t) }) > base, "转账 / 负数退款 / 软删三处口径错误都会让 used 变大（第 3 节各有差值）"},
		{usedOf(buds[1])+usedOf(buds[2]) < fam && fam-catSum > 0, "家庭 used ≠ Σ分类 used，差额 = 未设预算分类的支出"},
		{usedOf(buds[1]) > buds[1].AmountCents && fam < buds[0].AmountCents, "分类预算已超而家庭预算未超：两条独立判定同时成立"},
		{incOK["2026-03"] == truth["2026-03"] && incOK["2026-04"] == truth["2026-04"], "增量两条 UPDATE 都写 = 与全量重算逐桶相等；漏旧桶则两个桶各错一笔"},
	}
	all := true
	for _, c := range checks {
		fmt.Printf("  %s %s\n", map[bool]string{true: "✅", false: "❌"}[c.OK], c.Msg)
		all = all && c.OK
	}
	if all {
		fmt.Println("\nW44 d2 通过。明天算 used：实时 SUM 与增量维护各自的坑，以及比较为什么必须用分。")
	}
}

