package main

import (
	"fmt"
	"regexp"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
)

func hdr(s string) { fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s))) }

func yuan(c int64) string {
	if c < 0 {
		return fmt.Sprintf("-%d.%02d", -c/100, -c%100)
	}
	return fmt.Sprintf("%d.%02d", c/100, c%100)
}

func tbl(ws []int, header []string, rows [][]string) {
	fmt.Print("  ")
	for i, h := range header {
		fmt.Printf("%-*s  ", ws[i%len(ws)], h)
	}
	fmt.Println()
	fmt.Println("  " + strings.Repeat("-", 96))
	for _, r := range rows {
		fmt.Print("  ")
		for i, c := range r {
			fmt.Printf("%-*s  ", ws[i%len(ws)], c)
		}
		fmt.Println()
	}
}

type Op struct {
	Kind, Desc, Period, ID string
	Delta                  int64
}

type Txn struct {
	ID, Type, Period, Crid string
	Amt                    int64
	Deleted                bool
}

// countable 是 used 的分子口径（d2 第 3 节定的那条）。
func countable(t Txn) bool { return !t.Deleted && t.Type == "expense" }

func bucketsOf(list []Txn) map[string]int64 {
	m := map[string]int64{}
	for _, t := range list {
		if countable(t) {
			m[t.Period] += t.Amt
		}
	}
	return m
}

func main() {
	hdr("1. 比较用分还是用浮点元：一次真实的误报")
	cents := []int64{333, 111, 222, 444, 555, 111, 414} // 七笔小额支出，合计 2190 分
	var sumCents int64
	var sumFloat float64
	for _, c := range cents {
		sumCents += c
		sumFloat += float64(c) / 100
	}
	amountCents, amountFloat := int64(2190), 21.90
	fmt.Printf("  七笔支出（分）：%v，数学合计 = %s 元\n", cents, yuan(sumCents))
	fmt.Printf("  float64 逐笔累加 = %.17g ｜ 预算 float64 = %.17g\n", sumFloat, amountFloat)
	fmt.Printf("  整数分判定：used %s > amount %s → %v（等于阈值不算超，PRD 18.3#4 的边界值）\n",
		yuan(sumCents), yuan(amountCents), sumCents > amountCents)
	fmt.Printf("  浮点判定：%v → ★ 误报，多发了 1 条超支事件\n", sumFloat > amountFloat)
	fmt.Println("  ★ 差额只有 " + fmt.Sprintf("%.3e", sumFloat-amountFloat) + " 元，用户看不见，但判定翻了。超支提醒的判据是")
	fmt.Println("    「漏报 0、误报 0」（PRD 18.3#4），一位小数的偏差就是 100% 的误报率。")
	fmt.Println("    铁律 1 在这一天不再是风格问题：*_cents BIGINT + int64，比较发生在分上。")

	hdr("2. 阈值怎么算：三种取整政策给出三种判定")
	type pol struct {
		Name string
		F    func(amount, pct int64) int64
	}
	pols := []pol{
		{"floor（整数除法，向下）", func(a, p int64) int64 { return a * p / 100 }},
		{"round（四舍五入）", func(a, p int64) int64 { return (a*p + 50) / 100 }},
		{"ceil（向上）", func(a, p int64) int64 { return (a*p + 99) / 100 }},
	}
	amount, pct, used := int64(1099), int64(80), int64(880)
	fmt.Printf("  条件：amount_cents=%d（%s 元）、预警阈值 pct=%d%%、used=%d（%s 元）\n", amount, yuan(amount), pct, used, yuan(used))
	var rows [][]string
	vals := map[string]int64{}
	for _, q := range pols {
		thr := q.F(amount, pct)
		vals[q.Name] = thr
		rows = append(rows, []string{q.Name, fmt.Sprintf("%d", thr), yuan(thr), map[bool]string{true: "★ 触发预警", false: "未触发"}[used > thr]})
	}
	tbl([]int{24, 8, 12, 18}, []string{"取整政策", "阈值分", "阈值元", "used=" + yuan(used) + " 时的判定"}, rows)
	fmt.Printf("  同一条预算、同一笔 used，三种实现给出两种结论（floor/round=%d，ceil=%d）。\n", vals["floor（整数除法，向下）"], vals["ceil（向上）"])
	fmt.Println("  ★ 定版：阈值 = amount_cents * alert_threshold / 100（Go 整数除法天然向下取整），判定")
	fmt.Println("    用 used_cents > 阈值（严格大于，等于不触发）。取整规则必须写进注释与测试，因为它")
	fmt.Println("    不是一个数学细节：它决定了 80% 预警到底在几分钱上响。展示层的百分比也从同一个数")
	fmt.Println("    算出来，绝不允许前端用浮点再算一遍（S12 的同源口径）。")

	hdr("3. used 从哪来：实时 SUM vs 增量维护（同一个 8 步序列并排跑）")
	list := []Txn{
		{ID: "t0", Type: "expense", Period: "2026-03", Crid: "c0", Amt: 5000},
		{ID: "t3", Type: "expense", Period: "2026-03", Crid: "c3", Amt: 88000},
	}
	ops := []Op{
		{"insert", "记一笔餐饮 480.00（t1）", "2026-03", "t1", 48000},
		{"insert", "记一笔餐饮 1200.00（t2）", "2026-03", "t2", 120000},
		{"update", "t1 金额改成 520.00（+40.00）", "2026-03", "t1", 4000},
		{"resched", "t1 改期到 2026-04（跨期）", "2026-04", "t1", 52000},
		{"refund", "退款 -180.00（t7，负数支出）", "2026-03", "t7", -18000},
		{"delete", "软删 t3（880.00）", "2026-03", "t3", 88000},
		{"restore", "从回收站恢复 t3", "2026-03", "t3", 88000},
		{"replay", "重放 t1（同 client_request_id=c1）", "2026-03", "t1", 52000},
	}
	incOK, incLeak, incNaive := bucketsOf(list), bucketsOf(list), bucketsOf(list)
	rows = nil
	fmt.Println("  起始两笔已存在（t0=50.00、t3=880.00），三种实现初始值一致：")
	rows = append(rows, []string{"（起始）", yuan(bucketsOf(list)["2026-03"]), yuan(incOK["2026-03"]), yuan(incLeak["2026-03"]), yuan(incNaive["2026-03"]), "—"})
	for _, o := range ops {
		var old string
		switch o.Kind {
		case "insert":
			list = append(list, Txn{ID: o.ID, Type: "expense", Period: o.Period, Crid: "c" + o.ID[1:], Amt: o.Delta})
		case "update":
			for i := range list {
				if list[i].ID == o.ID {
					list[i].Amt += o.Delta
				}
			}
		case "resched":
			for i := range list {
				if list[i].ID == o.ID {
					old, list[i].Period = list[i].Period, o.Period
				}
			}
		case "refund":
			list = append(list, Txn{ID: o.ID, Type: "expense", Period: o.Period, Crid: "c7", Amt: o.Delta})
		case "delete", "restore":
			for i := range list {
				if list[i].ID == o.ID {
					list[i].Deleted = o.Kind == "delete"
				}
			}
		case "replay":
			// 幂等：命中 UNIQUE(family_id, client_request_id)，什么都不写
