// apply 把一次操作映射成对增量计数的维护（正确实现的口径）。
func apply(m map[string]int64, o Op, old string) {
	switch o.Kind {
	case "insert", "refund", "update":
		m[o.Period] += o.Delta
	case "resched":
		m[old] -= o.Delta
		m[o.Period] += o.Delta
	case "delete":
		m[o.Period] -= o.Delta
	case "restore":
		m[o.Period] += o.Delta
	}
}

func driftOf(m, truth map[string]int64) int64 {
	var d int64
	for k, v := range truth {
		d += m[k] - v
	}
	return d
}

