var (
	reSchema = regexp.MustCompile(`(?i)\b(?:finance|homeos|calendar)\.`) // schema 前缀不是别名
	reSource = regexp.MustCompile(`(?i)\b(?:from|join)\s+([a-z_][a-z0-9_]*(?:\.[a-z_][a-z0-9_]*)?)(?:\s+(?:as\s+)?([a-z_][a-z0-9_]*))?`)
	reCte    = regexp.MustCompile(`(?i)\b([a-z_][a-z0-9_]*)\s+as\s+\(`) // WITH 段：CTE 名也能当限定符
	reQual   = regexp.MustCompile(`(?i)\b([a-z_][a-z0-9_]*)\.`)         // 被用到的限定符
	reMonth  = regexp.MustCompile(`^2\d{3}-(0[1-9]|1[0-2])$`)           // period 的月档形态
)

var sqlStop = map[string]bool{"on": true, "where": true, "group": true, "order": true, "left": true,
	"right": true, "inner": true, "join": true, "using": true, "having": true, "limit": true,
	"select": true, "as": true, "and": true, "or": true, "by": true}

// undefinedAliases 返回 SQL 里用到却没在 FROM / JOIN / WITH 里声明过的限定符。
// 原稿的 f.timezone 就属于这一类：家庭表在 homeos schema 里（铁律 8 禁止跨 schema join），
// 根本 join 不进来，程序跑不到它、但这条检查能当场抓住。
func undefinedAliases(sql string) []string {
	declared := map[string]bool{}
	for _, m := range reCte.FindAllStringSubmatch(sql, -1) {
		declared[strings.ToLower(m[1])] = true
	}
	for _, m := range reSource.FindAllStringSubmatch(sql, -1) {
		name := strings.ToLower(m[1])
		if i := strings.LastIndex(name, "."); i >= 0 {
			name = name[i+1:]
		}
		declared[name] = true // 不带别名时，关系名自己也能当限定符（CTE）
		if a := strings.ToLower(m[2]); a != "" && !sqlStop[a] {
			declared[a] = true
		}
	}
	seen, out := map[string]bool{}, []string{}
	for _, m := range reQual.FindAllStringSubmatch(reSchema.ReplaceAllString(sql, ""), -1) {
		a := strings.ToLower(m[1])
		if !declared[a] && !seen[a] {
			seen[a] = true
			out = append(out, a)
		}
	}
	sort.Strings(out)
	return out
}

// coversThreeShapes 查这条 SQL 有没有给 month / quarter / year 三种 period 形态各一个匹配条件。
func coversThreeShapes(sql string) bool {
	for _, s := range []string{"p.period = k.m", "p.period = k.q", "p.period = k.y"} {
		if !strings.Contains(sql, s) {
			return false
		}
	}
	return true
}

// =====================================================================
// W44 d4：判定成立 ≠ 通知送达 —— 把超支事件安全地送出去。
//
// 这一天在解决什么问题：
//   ① 发布时机：为什么必须在**同一个写事务内**落 outbox，而不是 commit 之后
//      再发（丢事件）或发完再 commit（幽灵通知）。三种时序在同一批崩溃点上
//      各跑一遍，让「丢」与「幽灵」真的发生。
//   ② 信封 13 字段的口径：event_id 不作幂等键、business_id 是信封字段且
//      必须带周期、idempotency_key = type + business_id（PRD 10.2 / 10.4）。
//   ③ 发布条件：同一预算同一周期只提醒一次（alerted_at 的 CAS），以及
//      「删流水回退后不重复提醒」（PRD 18.3#4 的三个词逐字判定）。
//
// 本机没有 PostgreSQL、没有 NATS：事务/outbox/JetStream 用内存替身真跑，
// DDL 由 GORM DryRun 生成；第 6 节列出真环境要原样复跑的部分。
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d04
// =====================================================================

package main

import (
	"encoding/json"
	"fmt"
	"reflect"
	"sort"
	"strings"
	"sync"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

func hdr(s string) { fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s))) }
func yuan(c int64) string {
	return fmt.Sprintf("%d.%02d", c/100, c%100)
}

// ---------- 信封（PRD 10.2 的 13 个字段，一个不多一个不少）----------

type Payload struct {
	BudgetID    string `json:"budget_id"`
	Period      string `json:"period"`
	Scope       string `json:"scope"`
	AmountCents int64  `json:"amount_cents"`
	UsedCents   int64  `json:"used_cents"`
	ThresholdC  int64  `json:"threshold_cents"`
	OverByCents int64  `json:"over_by_cents"`
	AlertSource string `json:"alert_source"` // 首页标注超支来源（PRD 2.4 S6）
}

type Envelope struct {
	EventID        string  `json:"event_id"`
	Type           string  `json:"type"`
	Source         string  `json:"source"`
	BusinessID     string  `json:"business_id"`
	FamilyID       string  `json:"family_id"`
	MemberID       string  `json:"member_id"`
	Payload        Payload `json:"payload"`
	Version        string  `json:"version"`
	CreatedAt      string  `json:"created_at"`
	IdempotencyKey string  `json:"idempotency_key"`
	CausationID    *string `json:"causation_id"`
	Attempt        int     `json:"attempt"`
	Delivery       string  `json:"delivery"`
}

// Outbox 是发布方的运行表：与业务写同一个事务，投递器只读它。
type Outbox struct {
	ID         string `gorm:"column:id;primaryKey;type:uuid"`
	FamilyID   string `gorm:"column:family_id;type:uuid;not null"`
	EventType  string `gorm:"column:event_type;type:varchar(64);not null"`
	Subject    string `gorm:"column:subject;type:varchar(64);not null"`
	BusinessID string `gorm:"column:business_id;type:varchar(64);not null"`
	Payload    string `gorm:"column:payload;type:jsonb;not null"`
	Attempt    int    `gorm:"column:attempt;not null;default:0"`
	Status     string `gorm:"column:status;type:varchar(16);not null;default:'pending'"`
	LastError  string `gorm:"column:last_error;type:text"`
}

func (Outbox) TableName() string { return "finance_outbox" }

// ---------- 内存替身：一个能 commit / rollback 的小事务 ----------
// bus 代表已经发到 JetStream 的消息（发出去就收不回）；outbox 代表表里的行，
// 与业务写共享同一次提交 —— 这正是三种时序结局不同的原因。
type store struct {
	rows     map[string]string // 已提交的业务写
	staged   map[string]string // 本事务未提交的写
	boxRows  []Outbox          // 已提交的 finance_outbox 行
	stagedOB []Outbox          // 本事务未提交的 outbox 行
	bus      []string          // 已投递到总线的事件（不可撤回）
}

func newStore() *store {
	return &store{rows: map[string]string{}, staged: map[string]string{}}
}

func (s *store) write(k, v string) { s.staged[k] = v }
func (s *store) emit(o Outbox)     { s.stagedOB = append(s.stagedOB, o) }
func (s *store) commit() {
	for k, v := range s.staged {
		s.rows[k] = v
	}
	s.boxRows = append(s.boxRows, s.stagedOB...)
	s.staged, s.stagedOB = map[string]string{}, nil
}
func (s *store) rollback()        { s.staged, s.stagedOB = map[string]string{}, nil }
func (s *store) publish(o Outbox) { s.bus = append(s.bus, o.ID) } // 直接发总线，绕过 outbox

// budgetRow 上的 alerted_at 决定「本周期有没有发过事件」。mu 代表数据库对这一行的写锁。
type budgetRow struct {
	mu        sync.Mutex
	alertedAt *time.Time
}

func (b *budgetRow) peek(at time.Time) *time.Time { // SELECT alerted_at ...
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.alertedAt
}

func (b *budgetRow) force(at time.Time) { // UPDATE ... SET alerted_at=$now （无条件）
	b.mu.Lock()
	defer b.mu.Unlock()
	b.alertedAt = &at
}

// casAlert 是 UPDATE ... SET alerted_at=$now WHERE id=$1 AND alerted_at IS NULL 的受影响行数。
func (b *budgetRow) casAlert(at time.Time) int {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.alertedAt != nil {
		return 0
	}
	b.alertedAt = &at
	return 1
}

func main() {
	fixed := time.Date(2026, 4, 1, 9, 0, 0, 0, time.UTC)

	hdr("1. 发布时机三条路，各崩一次：谁丢事件、谁造幽灵")
	type scen struct{ Name, When, Outcome, Verdict string }
	var scens []scen
	// A：先 commit 业务写，再发事件 —— 两步之间进程被 kill
	sa := newStore()
	sa.write("period:2026-03", "195000")
	sa.commit()
	// ← kill -9 落在这一行之前：还没 emit
	scens = append(scens, scen{"A 先提交后发", "commit → (kill) → emit",
		fmt.Sprintf("库 %d 行 ｜ outbox %d 行 ｜ 总线 %d 条", len(sa.rows), len(sa.boxRows), len(sa.bus)),
		"★ 丢事件：库里确实超了，但没有任何地方记着「该发一条事件」，用户永远收不到提醒"})
	// B：先直接发总线，再提交 —— 事务随后回滚
	sb := newStore()
	sb.publish(Outbox{ID: "evt-B1"})
	sb.write("period:2026-03", "195000")
	sb.rollback()
	scens = append(scens, scen{"B 先发后提交", "publish → rollback",
		fmt.Sprintf("库 %d 行 ｜ outbox %d 行 ｜ 总线 %d 条", len(sb.rows), len(sb.boxRows), len(sb.bus)),
		"★ 幽灵通知：用户收到「3 月餐饮预算超支」，点开却查不到任何超支记录（消息收不回）"})
	// C：同一事务写业务 + outbox，提交后由投递器读 outbox 发
	sc := newStore()
	sc.write("period:2026-03", "195000")
	sc.emit(Outbox{ID: "ob-3", EventType: "finance.budget.exceeded"})
	sc.commit()
	for _, o := range sc.boxRows { // 投递器：只投已提交的行
		sc.publish(o)
	}
	scens = append(scens, scen{"C 事务内 outbox", "write+emit → commit → relay",
		fmt.Sprintf("库 %d 行 ｜ outbox %d 行 ｜ 总线 %d 条", len(sc.rows), len(sc.boxRows), len(sc.bus)),
		"✅ 两个副作用共享同一次提交：回滚就一起不存在，提交就一定能投出且可重放"})
	_ = sa
	for _, c := range scens {
		fmt.Printf("  %s ｜ 时序 %s\n    崩溃/回滚后的世界：%s\n    结论：%s\n", c.Name, c.When, c.Outcome, c.Verdict)
	}
	fmt.Println(`  ★ 判据不是「哪个更好」而是「崩溃时会剩下什么」：A 剩下一个无法重试的事实，B 剩下一个
    无法解释的通知。只有 C 的两个副作用共享同一次提交 —— 这就是 PRD 3.4.6 与 tech-plan
    7.2「业务面写自己的表 → 同一事务内写 outbox → 提交 → 投递器」那条唯一的写路径。`)

	hdr("2. 事件信封 13 字段：一次真序列化（encoding/json，字段名与 PRD 10.2 逐字对齐）")
	amount, used, thr := int64(180000), int64(195000), int64(180000)
	pl := Payload{BudgetID: "bud-food", Period: "2026-03", Scope: "category", AmountCents: amount,
		UsedCents: used, ThresholdC: thr, OverByCents: used - amount, AlertSource: "finance/budget"}
	bid := pl.BudgetID + ":" + pl.Period
	ev := Envelope{EventID: "7f0c-evt-0001", Type: "finance.budget.exceeded", Source: "finance",
		BusinessID: bid, FamilyID: "fam-01", MemberID: "mem-dad", Payload: pl, Version: "1.0",
		CreatedAt: fixed.Format(time.RFC3339), IdempotencyKey: "finance.budget.exceeded:" + bid,
		CausationID: nil, Attempt: 0, Delivery: "stream"}
	b, err := json.MarshalIndent(ev, "  ", "  ")
	if err != nil {
		panic(err)
	}
	fmt.Println("  " + string(b))
	// tag 要真去数：遍历 reflect.StructField 的 StructTag，分别统计「带任意 tag」与
	// 「带 json:"..."」的字段数，再数一次序列化出来的 JSON 顶层键——三个口径互相印证。
	et := reflect.TypeOf(ev)
	tagged, jsonTagged := 0, 0
	for i := 0; i < et.NumField(); i++ {
		f := et.Field(i)
		if f.Tag != "" {
			tagged++
		}
		if _, ok := f.Tag.Lookup("json"); ok {
			jsonTagged++
		}
	}
	var topKeys map[string]json.RawMessage
	if err := json.Unmarshal(b, &topKeys); err != nil {
		panic(err)
	}
	fmt.Printf("  字段数（reflect 真数）：%d ｜ 带 struct tag 的字段：%d ｜ 带 json:\"...\" 的字段：%d ｜ 序列化出的 JSON 顶层键：%d ｜ 四个数都落在 PRD 10.2 的 13 上\n",
		et.NumField(), tagged, jsonTagged, len(topKeys))
	// 把「忘写 tag」的下场真跑一遍：那个字段会以 Go 字段名出现在 JSON 里。
	var noTag struct {
		EventID  string `json:"event_id"`
		Delivery string // 忘写 tag
	}
	noTag.EventID, noTag.Delivery = ev.EventID, ev.Delivery
	nt, err := json.Marshal(noTag)
	if err != nil {
		panic(err)
	}
	fmt.Printf("  忘写 tag 长什么样：2 个字段里只有 1 个带 tag → %s（Delivery 顶替了 delivery，契约当场破裂）\n", nt)
	fmt.Println(`  三个最容易搞错的字段（tech-plan 7.4 原文点出的那三个）：
    · event_id 每次发布都不同 → 拿它当幂等键等于没有幂等（at-least-once 的重投会再落一条通知）。
    · business_id 是信封字段，由发布方按 10.4 的约定填 = {budget_id}:{period}，不是对象 id。
    · idempotency_key = type + business_id，消费端据此去重；它必须可推导，不得由发布方随机生成。`)

	hdr("3. business_id 少带一个 period：跨月再提醒直接被消费端的幂等表吃掉")
	type consumer struct {
		seen           map[string]int
		notes, dropped int
	}
	run := func(prefix string) *consumer {
		c := &consumer{seen: map[string]int{}}
		for _, p := range []string{"2026-03", "2026-04"} { // 同一预算连续两个月各超支一次
			key := "finance.budget.exceeded:" + prefix + p
			if prefix == "" {
				key = "finance.budget.exceeded:bud-food" // 错：business_id 只有 budget_id，两个月同一个键
			}
			if _, dup := c.seen[key]; dup {
				c.seen[key]++
				c.dropped++
				continue
			}
			c.seen[key] = 1
			c.notes++
		}
		naive := "错：business_id = {budget_id}"
		if prefix != "" {
			naive = "对：business_id = {budget_id}:{period}"
		}
		fmt.Printf("  %s：两次判定 → 落通知 %d 条 ｜ 被当重复丢弃 %d 条 ｜ 幂等键集合 = %s\n", naive, c.notes, c.dropped, keysOf(c.seen))
		return c
	}
	bad := run("")
	good := run("bud-food:")
	same := &consumer{seen: map[string]int{}}
	for i := 0; i < 3; i++ { // 同一条事件重投三次（at-least-once 的正常形态）
		key := "finance.budget.exceeded:bud-food:2026-03"
		if _, dup := same.seen[key]; dup {
			same.seen[key]++
			same.dropped++
			continue
		}
		same.seen[key] = 1
		same.notes++
	}
	fmt.Printf("  同一条事件重投 3 次 → 通知 %d 条、被幂等挡住 %d 次：%s\n",
		same.notes, same.dropped, "这才是幂等表该干的事")
	fmt.Println(`  ★ 两个方向都要对，缺一半就是 PRD 18.3#4 的失败：
    · 跨周期必须**再**提醒：3 月和 4 月是两件不同的事实，错形态把它们当同一件（丢 1 条 = 漏报）。
    · 同周期不许**重复**提醒：重投是 at-least-once 的常态，幂等键必须让第三次投递落不回通知。
    一句提醒的代价是整月没有提醒；用户不会知道系统想过告诉他 —— 这类缺陷只能靠链路用例堵。`)

	hdr("4. 发布条件：同一 (budget, period) 只发一次 —— CAS，不是「读出来再判断」")
	// 错误写法：SELECT alerted_at → 判断为 nil → 插 outbox → UPDATE alerted_at。三步不原子，
	// 用 channel 把交错点固定在「A 读完、还没写回」时 B 也读 —— 两边都读到 nil。
	naiveRow := &budgetRow{}
	aRead, bWrite := make(chan struct{}), make(chan struct{})
	var wg sync.WaitGroup
	var mu sync.Mutex
	naive, cas := 0, 0
	wg.Add(2)
	go func() { // 判定者 A
		defer wg.Done()
		if naiveRow.peek(fixed) == nil {
			close(aRead)
			<-bWrite
			naiveRow.force(fixed)
			mu.Lock()
			naive++
			mu.Unlock()
		}
	}()
	go func() { // 判定者 B：在 A 写回之前完成自己的读
		defer wg.Done()
		<-aRead
		if naiveRow.peek(fixed) == nil {
			close(bWrite)
			naiveRow.force(fixed)
			mu.Lock()
			naive++
			mu.Unlock()
		}
	}()
	wg.Wait()
	fmt.Printf("  读-判断-写：outbox 写入 %d 行 → 同一个 2026-03 用户收到两条重复提醒（无报错、无异常日志）\n", naive)
	casRow := &budgetRow{}
	wg.Add(2)
	for range [2]struct{}{} {
		go func() {
			defer wg.Done()
			if casRow.casAlert(fixed) == 1 { // UPDATE ... SET alerted_at=$now WHERE id=$1 AND alerted_at IS NULL
				mu.Lock()
				cas++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	fmt.Printf("  带条件的 UPDATE（受影响行数 0/1）：outbox 写入 %d 行 → 抢到的那个发，另一个静默退出\n", cas)
	again := casRow.casAlert(fixed.Add(time.Hour)) // 「超 → 删流水回退 → 又超」第三次判定
	fmt.Printf("  本周期已发过之后再超一次：受影响行数 %d → 不发。这就是 PRD 18.3#4 的「同一预算同一周期只提醒一次」\n", again)
	fmt.Println(`  「回退后不重复提醒」的定版：used 掉回阈值以下时**不**把 alerted_at 清空。一个周期内「超 → 退 →
    又超」响两遍，用户看到的是同一件事重复；而跨周期的再提醒由第 3 节 business_id 带 period
    保证 —— 两件事不能塞进同一个字段，否则「跨月要再提醒」与「同月不许重复」必然有一条做不到的。`)

	hdr("5. 投递器（relay）：at-least-once、指数退避最多 3 次、超限进死信")
	backoff := []int{1, 4, 16}
	ob := Outbox{ID: "ob-9", EventType: "finance.budget.exceeded", Subject: "finance.budget.exceeded", BusinessID: bid, Status: "pending"}
	relay := func(fails int) Outbox { // fails = 前多少次投递失败
		o := ob
		for i := 0; i <= 3; i++ {
			o.Attempt = i
			if i >= fails {
				o.Status, o.LastError = "published", ""
				fmt.Printf("  attempt=%d → 消费端 ack ｜ status=published ｜ 这条一共被投过 %d 次（重投对消费端必须无害）\n", i, i+1)
				return o
			}
			o.LastError = "nats: connection closed"
			if i == 3 {
				break
			}
			fmt.Printf("  attempt=%d → 消费端失败（%s）｜ 指数退避 %ds 后重试 ｜ status=pending\n", i, o.LastError, backoff[i])
		}
		o.Status = "dead"
		fmt.Printf("  attempt=%d → 三次重试（%ds/%ds/%ds）全部耗尽 ｜ status=dead → 落 finance_dead_letter，人工可重放，不自动第四次\n",
			o.Attempt, backoff[0], backoff[1], backoff[2])
		return o
	}
	live := relay(1)
	dead := relay(4)
	fmt.Println(`  ★ 三条口径写在这里，S13 的并发与 S14 的链路验收都会回来读：
    · at-least-once：published 之后 ack 丢了会重投 —— 所以第 3 节的幂等是消费端的义务，不是可选项。
    · 不承诺全局有序，只承诺同一 (source, id) 分区内有序；消费端不得依赖跨对象事件的先后。
    · 业务面不得自建推送链路：finance 只写 finance_outbox，通知是 homeos 消费之后的产物（d5）。`)

	hdr("6. finance_outbox 的 DDL（GORM DryRun 真实生成，不是手写）")
	db, err := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable"}),
		&gorm.Config{DryRun: true, DisableAutomaticPing: true, Logger: logger.Default.LogMode(logger.Silent)})
	if err != nil {
		panic(err)
	}
	fmt.Println("  --- AutoMigrate 语句 ---")
	db.AutoMigrate(&Outbox{})
	fmt.Println("  --- 一行 outbox 的 INSERT（DryRun 生成，列名以此为准）---")
	fmt.Println(db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Create(&Outbox{ID: "ob-11", FamilyID: "fam-01", EventType: ev.Type,
			Subject: ev.Type, BusinessID: bid, Payload: string(b), Status: "pending"})
	}))

	hdr("7. 真环境要原样复跑的四件事（本机没有 PostgreSQL 与 NATS）")
	fmt.Println(`  ① 崩溃点复跑：BEGIN → 写 finance_budget_period → 插 finance_outbox → kill -9 进程；重启后
     断言「库里没有这一行且 outbox 也没有」；再跑一次走到 COMMIT，断言 outbox 恰好 1 行。
  ② 投递复跑：真 NATS JetStream 上建流 finance（subject = finance.budget.exceeded），
     消费组 svc-homeos；把消费者停掉再恢复，核对 attempt 序列 1s/4s/16s 与死信表。
  ③ 幂等复跑：同一 idempotency_key 手工重投 3 次，断言 homeos_notification 只有 1 行（d5 判）。
  ④ 跨月复跑：3 月与 4 月各造一次超支，断言两条通知都在，且同月重投仍只 1 条 —— 这条就是
     PRD 18.3#4 的 30 组场景里「跨月」那一组，判据是漏报 0、误报 0、回退后不重复提醒。`)

	hdr("8. 今天的判据（程序逐条自查）")
	checks := []struct {
		OK  bool
		Msg string
	}{
		{len(sc.rows) == 1 && len(sc.boxRows) == 1 && len(sc.bus) == 1, "C 路径：业务写与 outbox 同一事务，投递器只投已提交的行（第 1 节）"},
		{len(sa.bus) == 0 && len(sb.rows) == 0 && len(sb.bus) == 1, "A 剩下「已超但无事件」、B 剩下「有事件但库里没超支」（第 1 节）"},
		{et.NumField() == 13 && tagged == 13 && jsonTagged == 13 && len(topKeys) == 13, "信封 13 字段、13 个 struct tag、13 个 json tag、序列化出 13 个顶层键——四个口径都是真数的（第 2 节）"},
		{ev.IdempotencyKey == ev.Type+":"+ev.BusinessID, "idempotency_key = type + business_id，可推导不随机（第 2 节）"},
		{bad.notes == 1 && good.notes == 2, "business_id 少带 period → 跨月再提醒被幂等表吃掉（第 3 节）"},
		{naive == 2 && cas == 1, "读-判断-写并发发 2 条（重复提醒），带条件的 UPDATE 只发 1 条（第 4 节）"},
		{again == 0 && casRow.alertedAt != nil, "本周期已发过 → 再超不重复提醒，回退也不清空 alerted_at（第 4 节）"},
		{live.Status == "published" && dead.Status == "dead" && dead.Attempt == 3, "退避 1s/4s/16s 三次后进死信，不自动第四次（第 5 节）"},
	}
	fails := 0
	for _, c := range checks {
		if !c.OK {
			fails++
		}
		fmt.Printf("  %s %s\n", map[bool]string{true: "✅", false: "❌"}[c.OK], c.Msg)
	}
	fmt.Printf("\n自查 %d 条：%d ✅ / %d ❌ → %s\n", len(checks), len(checks)-fails, fails,
		map[bool]string{true: "W44 d4 通过。明天换到消费端：svc-homeos 收到事件 → homeos_notification → 未读数怎么变。",
			false: "不判通过：先把 ❌ 那几条对应的程序改掉，别改卡片文案绕过它。"}[fails == 0])
}

func keysOf(m map[string]int) string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return strings.Join(ks, " / ")
}

// =====================================================================
// W44 d5：消费端 —— svc-homeos 收到 finance.budget.exceeded 之后发生的事。
//
// 这一天在解决什么问题：
//   ① 消费端幂等：homeos_event_dedupe 用什么键挡重复（d4 说了发布方必须带
//      period，这里验证消费方那半边真的落库、且 LWW 不覆盖已读态）。
//   ② 通知的三件职责：分型（budget_alert/system/reminder 固定三类）、深链、
//      唯一一份未读——PRD 17.7 第 1 条禁止业务面自建通知与红点。
//   ③ 跨面边界：通知写失败时财务流水该不该回滚（不存在跨服务分布式事务）、
//      homeos 不可达时首页那一格返什么、L3 文案为什么不能进 content。
//
// 本机没有 PostgreSQL 与 NATS：两张表（notification / event_dedupe）与投递
// 都是内存替身真跑，DDL 由 GORM DryRun 生成。真环境的复跑清单在第 6 节。
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d05
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"sync"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

func hdr(s string) { fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s))) }

// ---------- homeos 侧的两张表（tech-plan 5.2 协作与通知 + 运行表族）----------

type Notification struct {
	ID        string     `gorm:"column:id;primaryKey;type:uuid"`
	MemberID  string     `gorm:"column:member_id;type:uuid;not null"`
	Type      string     `gorm:"column:type;type:varchar(16);not null"`     // budget_alert / system / reminder，固定三类
	Title     string     `gorm:"column:title;type:varchar(64);not null"`    // 按分型渲染的词
	Content   string     `gorm:"column:content;type:varchar(255);not null"` // L3 内容不得进这一列（20.2）
	DeepLink  string     `gorm:"column:deep_link;type:varchar(128)"`        // 点击直达的三段式路由
	Source    string     `gorm:"column:source;type:varchar(32);not null"`   // 来源面：首页标注超支来源用
	DedupeKey string     `gorm:"column:dedupe_key;type:varchar(128);not null"`
	ReadAt    *time.Time `gorm:"column:read_at;type:timestamptz"` // 未读 = read_at IS NULL（唯一口径源 3.4.2）
}

func (Notification) TableName() string { return "homeos_notification" }

type Dedupe struct {
	ID           string    `gorm:"column:id;primaryKey;type:uuid"`
	IdempotencyK string    `gorm:"column:idempotency_key;type:varchar(160);not null;uniqueIndex"`
	Consumer     string    `gorm:"column:consumer;type:varchar(32);not null"` // 组名 = 目标服务名
	EventID      string    `gorm:"column:event_id;type:uuid;not null"`        // 只做追溯，不作幂等键
	HandledAt    time.Time `gorm:"column:handled_at;type:timestamptz;not null"`
}

func (Dedupe) TableName() string { return "homeos_event_dedupe" }

// ---------- 内存消费端：一个订阅器 + 两张表 ----------

type homeos struct {
	mu       sync.Mutex
	notes    []*Notification
	seen     map[string]*Notification // idempotency_key → 已处理的那一行
	delivery int                      // 收到的投递次数（含写库失败的那几次）
	failed   int                      // 其中写库报错、什么都没落的次数
}

func newHomeos() *homeos { return &homeos{seen: map[string]*Notification{}} }

// failDelivery 是「订阅器写库报错」那次投递：投递计数照常加一（消息确实来过），
// 但通知与 dedupe 一行都不落（同一个事务整体回滚），所以不 ack、由 JetStream 重投。
func (h *homeos) failDelivery(key, eventID string) string {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.delivery++
	h.failed++
	return "订阅器写库报错 → 三步整体回滚，不 ack，JetStream 重投"
}

// handle 是 svc-homeos 的订阅器主体：幂等检查 → 落通知 → 记 dedupe，三步同事务。
// 返回「新建 / 重复跳过」。
func (h *homeos) handle(key, eventID string, template func() *Notification) string {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.delivery++
	if prev, dup := h.seen[key]; dup {
		if prev.ReadAt == nil { // LWW：同 key 的新版本只刷新未读行，不新增行
			prev.Title, prev.Content, prev.DeepLink = template().Title, template().Content, template().DeepLink
		}
		return "重复跳过（LWW 刷新未读行）"
	}
	n := template()
	n.DedupeKey = key
	h.notes = append(h.notes, n)
	h.seen[key] = n
	return "新建通知"
}

// unread 只有一条口径：read_at IS NULL 且 member_id = 我，按 member 聚合（3.4.2）。
func (h *homeos) unread(mid string) int {
	n := 0
	for _, x := range h.notes {
		if x.MemberID == mid && x.ReadAt == nil {
			n++
		}
	}
	return n
}

func badge(n int) string {
	if n > 99 {
		return "99+"
	}
	return fmt.Sprintf("%d", n)
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_homeos:dev@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, Logger: logger.Default.LogMode(logger.Silent)})
	if err != nil {
		panic(err)
	}
	return db
}

func main() {
	fixed := time.Date(2026, 4, 1, 9, 0, 0, 0, time.UTC)
	key3 := "finance.budget.exceeded:bud-food:2026-03"
	tpl := func() *Notification {
		return &Notification{MemberID: "mem-dad", Type: "budget_alert", Title: "预算预警",
