	d1, n1 := h.delivery, len(h.notes)
	fmt.Printf("  投递 %d 次 → homeos_notification %d 行 ｜ 未读 %d ｜ homeos_event_dedupe %d 行\n",
		h.delivery, len(h.notes), h.unread("mem-dad"), len(h.seen))
	fmt.Println(`  ★ event_id 每次都不同（7.4 点名的第一个坑），拿它当键 = 没有幂等。键是 idempotency_key，
    它由 type + business_id 拼出来，重投时不变。这一张表是「消费端的义务」（d4 第 5 节），
    不做的话 at-least-once 会直接把未读数吹大，用户看到的是「我有 3 条没看过的超支提醒」。`)

	hdr("2. 跨月再来一次：两条都该在（business_id 带 period 的消费端视角）")
	key4 := "finance.budget.exceeded:bud-food:2026-04"
	fmt.Printf("  2026-04 超支事件 → %s ｜ 通知现有 %d 行 ｜ 未读 %d\n",
		h.handle(key4, "evt-201", func() *Notification {
			n := tpl()
			n.ID, n.DeepLink, n.Content = "ntf-04", strings.Replace(n.DeepLink, "2026-03", "2026-04", 1), "「4 月餐饮」分类预算已超出，点开看当期预算详情"
			return n
		}), len(h.notes), h.unread("mem-dad"))
	d2, n2 := h.delivery, len(h.notes) // delivery 是跨节累计计数，不是本节的投递次数（第 8 节的谓词就栽在这上面）
	fmt.Printf("  h.delivery 是累计计数：到这里 = %d（第 1 节的 3 次 + 这一节的 1 次）｜ 通知行 %d —— 自查谓词必须取它对的那一侧\n", d2, n2)
	fmt.Println("  两个周期是两件不同的事实：都保留。发布方少写了 :period 的话，这一条根本到不了这里（d4 第 3 节）。")

	hdr("3. 点进详情才算已读：read_at 落库，未读数随之变化")
	for _, n := range h.notes {
		if n.DedupeKey == key3 {
			at := fixed.Add(4 * time.Minute)
			n.ReadAt = &at // UPDATE homeos_notification SET read_at=$now WHERE id=$1 AND member_id=$2
			fmt.Printf("  点开 ntf-03（深链 %s）→ read_at=%s\n", n.DeepLink, at.Format("15:04"))
		}
	}
	fmt.Printf("  未读：mem-dad %d 条 ｜ mem-mom %d 条（她一条也没有，家庭级数字不参与）\n", h.unread("mem-dad"), h.unread("mem-mom"))
	u3 := h.unread("mem-dad") // 已读落库后的未读数，第 8 节读这个快照
	fmt.Println(`  ★ 链路三段到这里跑通了：判定（d3）→ finance_outbox → JetStream → 订阅器落 homeos_notification
    → read_at IS NULL 计数变化 → 顶栏红点与消息 Tab 的数字读同一份（shell 持有，17.7）。`)

	hdr("4. 未读只有一个口径：聚合键是 member_id，不是家庭")
	fmt.Println("  三处呈现（17.1 / 3.4.2）：")
