	fmt.Println("    顶栏消息入口 = 同一份数据的红点，只显点不显数")
	fmt.Println("    进入列表即读、「全部已读」批量置 read_at —— 熄灭时机一致，两处不许各存一份")
	// 上界场景要程序自己灌、自己数：给 mem-dad 塞一批三种分型的未读通知，条数由下面分组相加得来。
	mbox := newHomeos()
	mix := []struct {
		Type, Title string
		N           int
	}{
		{"reminder", "到期提醒", 120},
		{"system", "系统消息", 15},
		{"budget_alert", "预算预警", 2},
