		mix[0].N, mix[1].N, mix[2].N, boxSeeded, boxUnread)
	fmt.Printf("  同一份 unread 的两种呈现：顶栏红点 / 消息 Tab 角标 %s（只有角标在 >99 时截断）｜ 列表页 %d 条（真数，不截断）\n", badge(boxUnread), boxUnread)
	fmt.Println("  ★ 截断发生在展示层的角标上，SQL 返真数（第 7 节）：列表页显 99+ 用户就不知道自己「全部已读」要清掉几条。")
	fmt.Println("  ★ 家庭级聚合是错的：「全家共 3 条未读」会让每个成员的红点互相踩。member_id 是唯一聚合键。")

	hdr("5. 三个跨面边界（每条都是一个会被写错的接口）")
	// 5a 写通知失败不回滚财务
	h2 := newHomeos()
	fmt.Println("  ① 不存在跨服务分布式事务：订阅器落通知失败（写库报错）时，财务侧的流水与 outbox 都已提交，")
	fmt.Println("     不回滚。处置是消息留在流里重投 + 第 1 节的 dedupe 保证重投不翻倍。跑一条失败重投：")
	for i := 1; i <= 2; i++ {
		var res string
		switch i {
		case 1: // 第一次：订阅器写库报错 → 计数加一，但通知与 dedupe 一行都不落
			res = h2.failDelivery(key3, "evt-301")
		case 2: // 重投：event_id 换了、idempotency_key 没换 → 落 1 行
			res = h2.handle(key3, "evt-302", tpl)
		}
		fmt.Printf("     第 %d 次投递 → %s ｜ 通知表 %d 行 ｜ dedupe %d 行\n", i, res, len(h2.notes), len(h2.seen))
	}
	// 5b homeos 不可达时的降级词
	fmt.Println("  ② homeos 不可达：首页那一格返「暂不可用」+ 保留入口，未读不猜数（7.7）。四个降级词不许混用：")
	for _, w := range []struct{ Word, When, InBudget string }{
		{"未启用", "本家庭没挂这个面（homeos_family_module 无行）", "与预算无关，走 d6 的「未设该周期预算」"},
		{"即将上线", "面还没出生（服务不存在）", "当前三个服务都在运，本词暂无样本"},
		{"暂不可用", "面已启用但本次不可达 / 分包校验失败", "本条：通知读不到时首页财务格用它"},
		{"依赖未就绪", "本面可用但依赖的另一面没出生", "当前无样本"},
	} {
		fmt.Printf("     %-6s ｜ %s ｜ %s\n", w.Word, w.When, w.InBudget)
	}
	// 5c 文案分级
	fmt.Println("  ③ 分型词固定三类，content 不得含 L3 内容（20.2：推送只说「有一条新记录」）：")
	for _, t := range []struct{ Type, Title, Note string }{
		{"budget_alert", "预算预警", "金额属 L2②（可存可 SUM）→ 写进 content 合规"},
		{"system", "系统消息", "家庭/成员/面配置类变化"},
		{"reminder", "到期提醒", "由 calendar.reminder.fired 落库（触发归 calendar、下发归 homeos）"},
	} {
		fmt.Printf("     %-13s → 标题词「%s」 ｜ %s\n", t.Type, t.Title, t.Note)
	}
	fmt.Println("     L3 的深链进入需设备解锁 + 会话内二次确认，红点本身不对 L3 分级（3.4.2、17.1 第 6 条）。")

	hdr("6. 真环境要复跑的四件事（本机没有 PostgreSQL 与 NATS，以上均为内存替身）")
	fmt.Println(`  ① UNIQUE 约束必须真撞一次：同一 idempotency_key 并发投两条，断言第二条 23505 且通知表仍 1 行
     （内存 map 与真库唯一索引在并发下的行为不等价，第 1 节只证明逻辑正确）。
  ② 消费组重放：svc-homeos 下线 10 分钟再上线，核对未读增量与 d4 的死信表，断言不补发风暴。
  ③ 跨家庭隔离：给 fam-02 也发一条同 budget_id 的事件，断言 fam-01 的 unread 不变（member 维度聚合）。
  ④ 首屏请求数：抓包断言首页 unread 由 /api/homeos/home/summary 一个请求带出，红点不另发请求（17.2）。`)

	hdr("7. 两张表的 DDL（GORM DryRun 真实生成，列名以此为准）")
	fmt.Println("  --- homeos_notification：Notification 实体（tech-plan 5.2 协作与通知）---")
	dryDB().AutoMigrate(&Notification{})
	fmt.Println("  --- homeos_event_dedupe：运行表族，与通知写同一个事务 ---")
	db := dryDB()
	db.AutoMigrate(&Dedupe{})
	fmt.Println("  --- 未读计数语句（服务端唯一实现，客户端不得复算）---")
	fmt.Println(`    SELECT count(*) FROM homeos.homeos_notification
      WHERE member_id = $1 AND read_at IS NULL;          -- 上限 99+ 在展示层截断，SQL 返真数`)
	fmt.Println(`    SELECT count(*) FROM homeos.homeos_notification
      WHERE family_id = $1 AND read_at IS NULL;          -- ✗ 家庭级聚合：错口径，会互相踩红点`)

	hdr("8. 今天的判据（程序逐条自查）")
	third := newHomeos()
	for i := 0; i < 3; i++ {
		third.handle(key3, fmt.Sprintf("evt-x%d", i), tpl)
	}
	checks := []struct {
		OK  bool
		Msg string
	}{
		{d1 == 3 && n1 == 1, "第 1 节：同一条事件投 3 次只落 1 行通知（用第 1 节末的快照，不是后面的累计值）"},
		{d2 == 4 && n2 == 2 && u3 == 1 && h.unread("mem-mom") == 0, "第 2、3 节：跨月那条另起一行（累计投递 4、通知 2 行），点读后 mem-dad 未读减到 1，mem-mom 始终 0（未读按 member_id 聚合）"},
		{third.seen[key3] != nil && len(third.notes) == 1, "同一 idempotency_key 重投 3 次只 1 行通知（第 1 节）"},
		{boxUnread == boxSeeded && boxUnread > 99 && badge(boxUnread) == "99+", fmt.Sprintf("第 4 节：未读 %d 条 = 灌入的 %d 条，全部由程序算出；角标 %s 只在 >99 时截断，列表页显真数 %d（第 7 节那条 SQL 返的就是这个数）", boxUnread, boxSeeded, badge(boxUnread), boxUnread)},
		{len(h2.notes) == 1 && h2.delivery == 2 && h2.failed == 1, "第 5① 节：两次投递里第一次写库报错（计数 +1 但零行落库），重投才落库且不翻倍"},
		{badge(3) == "3" && badge(0) == "0" && badge(99) == "99", "badge 就是 read_at IS NULL 的计数，只有角标层做截断，99 这条边界不截（第 4 节）"},
	}
	fails := 0
	for _, c := range checks {
		if !c.OK {
			fails++
		}
		fmt.Printf("  %s %s\n", map[bool]string{true: "✅", false: "❌"}[c.OK], c.Msg)
	}
	fmt.Printf("\n自查 %d 条：%d ✅ / %d ❌ → %s\n", len(checks), len(checks)-fails, fails,
		map[bool]string{true: "W44 d5 通过。明天收口 W44：未设该周期预算的口径（不许乘 3）+ 改预算的幂等与乐观锁。",
			false: "不判通过：结论由上面的谓词算出来，有一条 ❌ 就不许写「通过」。"}[fails == 0])
}

// =====================================================================
// W44 d6：「未设该周期预算」口径 + W44 判据自测（收口日）。
//
// 这一天在解决什么问题：
//   ① 月度预算切到季度视图：错误直觉「月度 ×3 = 季度」是在造一条库里不存在
//      的定义行。正确口径：显式「未设该周期预算」，不折算、不判定、不发事件。
//   ② 预算写路径最后一块：创建幂等（client_request_id）与编辑乐观锁
//      （version）。d3 防 used_cents 丢更新，这一层防定义行被丢覆盖。
//   ③ 收口：W44 五条判据（超支判定、事件三段链路、*_cents 比较、幂等与乐观
//      锁、未设口径）逐条机器判定，证据由程序当场算出，不靠记忆。
//
// 本机没有 PostgreSQL：预算行与事件投递用内存替身真跑，INSERT/UPDATE 由
// GORM DryRun 真实生成。学员侧跑法：cd homecube/server && go run ./lab/s11/d06
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

func hdr(s string)           { fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s))) }
func ptr(s string) *string   { return &s }
func verdict(ok bool) string { return map[bool]string{true: "✅ 通过", false: "❌ 未通过"}[ok] }

func yuan(c int64) string {
	neg, a := map[bool]string{true: "-", false: ""}[c < 0], max(c, -c)
	return fmt.Sprintf("%s%d.%02d", neg, a/100, a%100)
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return time.Date(2026, 4, 1, 9, 0, 0, 0, time.UTC) }, Logger: logger.Default.LogMode(logger.Silent)})
	if err != nil {
		panic(err)
	}
	return db
}

// 定义行（d1 四要素）：未设该周期 = 这张表里查不出那一行，仅此而已。
type Bud struct {
	ID              string  `gorm:"column:id;primaryKey;type:uuid"`
	FamilyID        string  `gorm:"column:family_id;type:uuid;not null"`
	Scope           string  `gorm:"column:scope;type:varchar(16);not null"`
	ScopeRef        *string `gorm:"column:scope_ref;type:uuid"`
	Period          string  `gorm:"column:period;type:varchar(8);not null"` // month / quarter / year
	AmountCents     int64   `gorm:"column:amount_cents;type:bigint;not null"`
	AlertThreshold  int     `gorm:"column:alert_threshold;not null;default:100"`
	ClientRequestID string  `gorm:"column:client_request_id;type:uuid;not null"`
	Version         int     `gorm:"column:version;not null;default:1"`
	DeletedAt       gorm.DeletedAt
}

func (Bud) TableName() string { return "finance_budget" }

type leg struct {
	id, month string
	cents     int64
	note      string
}

func main() {
	tx := []leg{ // d2 口径：未软删 expense，退款以负数进 used（冲抵退款发生期）
		{"f11", "2026-01", 52000, "外卖"}, {"f12", "2026-01", 61500, "聚餐"}, {"f13", "2026-01", -10000, "退款"}, {"f14", "2026-01", -3000, "红包退回"},
		{"f21", "2026-02", 120000, "年夜饭外食"}, {"f22", "2026-02", -16000, "退款"}, {"f23", "2026-02", -2500, "会员日退款"}, {"f24", "2026-02", 3000, "便利店"},
		{"t1", "2026-03", 48000, "外卖（d2）"}, {"t2", "2026-03", 120000, "火锅（d2）"}, {"t7", "2026-03", -18000, "退款（d2）"}, {"t9", "2026-03", -1200, "运费退回"},
	}
	months, used := []string{"2026-01", "2026-02", "2026-03"}, map[string]int64{}
	buds := map[string]int64{"2026-01": 100000, "2026-02": 120000, "2026-03": 120000} // 三个月的月度预算并不相等
	for _, t := range tx {
		used[t.month] += t.cents
	}
	q1 := used["2026-01"] + used["2026-02"] + used["2026-03"]
	hdr("1. 事实：月度预算三个月都设了，2026-Q1 只有流水、没有任何「季度预算」")
	fmt.Printf("  cat-food 流水明细（%d 笔，负数 = 退款冲抵当期，d2 第 3 节口径）：\n", len(tx))
	for _, t := range tx {
		fmt.Printf("    %-4s %s %10s 元  %s\n", t.id, t.month, yuan(t.cents), t.note)
	}
	for _, m := range months {
		fmt.Printf("  %s 预算 %9s 元 ｜ used %9s 元 ｜ 剩余 %9s 元 ｜ 月度判定：%s\n", m, yuan(buds[m]), yuan(used[m]), yuan(buds[m]-used[m]), map[bool]string{true: "已超", false: "未超"}[used[m] > buds[m]])
	}
	fmt.Printf("  Q1 实际支出 = %s + %s + %s = %s 元（三桶相加，d3 第 5 节现算口径，报表侧本来就能算出来）\n", yuan(used["2026-01"]), yuan(used["2026-02"]), yuan(used["2026-03"]), yuan(q1))
	fmt.Println("  但 finance_budget 里 bud-food 只有一条定义行：period='month'。没有 period='quarter' 的行。")
	hdr("2. 错误直觉：拿月度 ×3 造一个「季度预算」——同一件事给出三种结论")
	fake3 := 3 * buds["2026-03"]
	sumQ := buds["2026-01"] + buds["2026-02"] + buds["2026-03"]
	x3After := 3 * int64(111000) // 4 月 10 日 mem-mom 把 4 月的月度预算改成 1110.00（与 Q1 毫无关系）
	fmt.Printf("  %-20s %-12s %-26s %s\n", "假季度预算", "数值（分）", "对 used="+yuan(q1)+" 元（Q1 真数）的判定", "错在哪")
	fmt.Println("  " + strings.Repeat("-", 100))
	names := []string{"当前月 ×3", "三月预算相加", "改 4 月预算后再 ×3"}
	fakes := []int64{fake3, sumQ, x3After}
	whys := []string{"三个月预算并不相等（1000/1200/1200）", "这个数同样不在库里，判定与事件都没有依据", "Q1 一分钱没动，结论被下一期的编辑翻掉"}
	for i, v := range fakes {
		fmt.Printf("  %-20s %-12d %-26s %s\n", names[i], v, map[bool]string{true: "★ 已超 " + yuan(q1-v) + "，触发提醒", false: "未超（漏报）"}[v < q1], whys[i])
		fmt.Printf("    同一个假数还带着走：80%% 预警线 = %d 分 → 首页格子与 finance.budget.exceeded 的 business_id 全建在它上面\n", v*80/100)
	}
	fmt.Println("  ★ ×3 不是口径，是巧合：只在「三个月预算恰好相等、且编辑离得很远」时才碰对；锚点还落在")
	fmt.Println("    「当前定义行的 amount_cents」上，任何一次编辑都会回溯翻转已结算周期的展示判定。这个数")
	fmt.Println("    也不只活在展示里：预算页进度条、80% 预警、首页格子与事件全建立在它上面——造的假额度")
	fmt.Println("    会照样发假事件（d4 链路全程不知情），用户从界面上无从分辨真假。")
	hdr("3. 正确做法：库里没有那一行，就显式「未设该周期预算」，不折算")
	rows := []*Bud{{ID: "bud-food", FamilyID: "fam-01", Scope: "category", ScopeRef: ptr("cat-food"), Period: "month", AmountCents: 120000, AlertThreshold: 100, ClientRequestID: "crid-01", Version: 1}}
	cnt := map[string]int{}
	for _, b := range rows { // 按 period 逐条数：这一档在库里到底有没有定义行
		cnt[b.Period]++
	}
	nq := cnt["quarter"]
	fmt.Println("  SELECT * FROM finance_budget WHERE family_id='fam-01' AND scope_ref='cat-food' AND deleted_at IS NULL")
	for _, b := range rows {
		fmt.Printf("    → 命中 %s scope=%s ref=%s period=%-6s amount=%8s 元 threshold=%d%% version=%d\n", b.ID, b.Scope, *b.ScopeRef, b.Period, yuan(b.AmountCents), b.AlertThreshold, b.Version)
	}
	fmt.Printf("  其中 period='quarter' 的行数 → %d（day/week 两档在预算词表里根本不存在，d1 第 6 节）\n", nq)
	fmt.Println("  五档视图逐档开一次，输出全由「库里有没有那一行」决定，不由推导决定：")
	for _, p := range []string{"month", "quarter", "year", "day", "week"} {
		fmt.Printf("    %-8s 视图：定义行 %d 条 → %s\n", p, cnt[p], map[bool]string{true: "进度条 + 判定 + 事件", false: "「未设该周期预算」：无进度条、无剩余、无判定、无事件"}[cnt[p] > 0])
	}
	fmt.Printf("  报表页五档都照显支出（Q1 = %s 元）—— used 现算（d3 第 5 节），未设只压制「判定」这一件事\n", yuan(q1))
	fmt.Println("  事件侧：2026-Q1 没有判定对象 → finance_outbox 该周期发出 = 0 条（不是「超了不发」，是压根不判）")
	db := dryDB()
	fmt.Println("  用户真要季度预算 → 显式新建（INSERT 由 GORM DryRun 真实生成），不是从月度推导出来：")
	fmt.Println("  " + db.ToSQL(func(g *gorm.DB) *gorm.DB {
		return g.Create(&Bud{ID: "bud-q1", FamilyID: "fam-01", Scope: "category", ScopeRef: ptr("cat-food"), Period: "quarter", AmountCents: 350000, AlertThreshold: 100, ClientRequestID: "crid-77", Version: 1})
	}))
	qThr := int64(350000)
	fmt.Printf("  对照（这一行存在之后才允许有季度判定）：used %d > 显式额度 %d → 已超 %s 元、事件 1 条；\n", q1, qThr, yuan(q1-qThr))
	fmt.Printf("  判定读的是用户亲手写的 %d，不是 %d/%d 这类推导值——折算与显式的差别就在这 %s 元上。\n", qThr, fake3, sumQ, yuan(fake3-qThr))
	hdr("4. 预算的写路径：创建幂等（client_request_id）+ 编辑乐观锁（version）")
	created, store, cridRows := map[string]string{}, map[string]*Bud{}, map[string]int{}
	create := func(id, crid string, amount int64) string {
		if hit, dup := created[crid]; dup {
			return "幂等命中 UNIQUE(family_id, client_request_id) → 返回原行 " + hit + "，不写第二行"
		}
		created[crid], cridRows[crid] = id, cridRows[crid]+1
		store[id] = &Bud{ID: id, FamilyID: "fam-01", Scope: "category", ScopeRef: ptr("cat-food"), Period: "quarter", AmountCents: amount, ClientRequestID: crid, Version: 1}
		return "新建 " + id + "（周期行同时落 amount 快照）"
	}
	for i := 1; i <= 3; i++ {
		fmt.Printf("  第 %d 次提交「建 2026-Q1 预算 3500.00」crid=crid-77 → %s\n", i, create("bud-q1", "crid-77", 350000))
	}
	fmt.Printf("  对照：换 crid=crid-78 提交「建 2026-Q2 预算 2400.00」→ %s —— 幂等键挡「重放」，不挡「新意图」\n", create("bud-q2", "crid-78", 240000))
	fmt.Println("  软删行不占用 crid（UNIQUE 是部分索引 WHERE deleted_at IS NULL，d1 第 5 节），删除后 crid 可复用（S10 d26 口径）。")
	fmt.Println("  编辑走乐观锁（真库交错任意，程序固定成先后各一，逐条判定）：")
	fmt.Println("  " + db.ToSQL(func(g *gorm.DB) *gorm.DB {
		return g.Model(&Bud{}).Where("id = ? AND version = ?", "bud-q1", 1).Updates(map[string]any{"amount_cents": 360000, "version": gorm.Expr("version + 1")})
	}))
	patch := func(want int, to int64) int { // UPDATE ... WHERE id=$1 AND version=$2 的受影响行数
		if store["bud-q1"].Version != want {
			return 0
		}
		store["bud-q1"].AmountCents, store["bud-q1"].Version = to, want+1
		return 1
	}
	w1, w2 := patch(1, 360000), patch(1, 350000) // 两个端拿着同一份 version=1 先后提交
	fmt.Printf("  mem-dad PATCH(version=1→3600.00) 受影响 %d 行 ｜ mem-mom PATCH(version=1→3500.00) 受影响 %d 行 → 409「预算已被他人修改，请刷新」\n", w1, w2)
	fmt.Printf("  定义行终值：amount=%s 元 version=%d —— 而 budget_period 的周期行是历史，**不因这次编辑改写**：\n", yuan(store["bud-q1"].AmountCents), store["bud-q1"].Version)
	perUsed := map[string]int64{"2026-01": used["2026-01"], "2026-02": used["2026-02"], "2026-03": used["2026-03"], "2026-Q1": q1}
	perSnap := map[string]int64{"2026-01": buds["2026-01"], "2026-02": buds["2026-02"], "2026-03": buds["2026-03"], "2026-Q1": qThr}
	for _, p := range []string{"2026-01", "2026-02", "2026-03", "2026-Q1"} {
		fmt.Printf("    finance_budget_period %s：amount 快照 %8s 元 ｜ used %9s 元 ｜ 判定：%s\n", p, yuan(perSnap[p]), yuan(perUsed[p]), map[bool]string{true: "已超（事件已按 period 发过）", false: "未超"}[perUsed[p] > perSnap[p]])
	}
	hdr("5. W44 判据自测：五条，每条「判据 / 证据 / 通过与否」当场算")
	key3, key4 := "finance.budget.exceeded:bud-food:2026-03", "finance.budget.exceeded:bud-food:2026-04"
	seen := map[string]int{key3: 3, key4: 1} // key3 被 JetStream 重投三次（d4 at-least-once）；key4 = 跨月再提醒，business_id 带 period，新键落得下
	marchNotes := min(seen[key3], 1)
	thr := buds["2026-03"] * 80 / 100
	sumC, sumF := int64(0), 0.0
	for _, c := range []int64{333, 111, 222, 444, 555, 111, 414} { // d3 第 1 节那七笔
		sumC, sumF = sumC+c, sumF+float64(c)/100
	}
	n77 := cridRows["crid-77"]
	cNames := []string{"超支判定：used_cents > amount_cents*alert_threshold/100，严格大于、整数分", "事件三段链路：判定 → finance_outbox → event_dedupe → homeos_notification", "*_cents 比较：浮点判一次就误报（PRD 18.3#4 要求误报 0）", "幂等与乐观锁：同 crid 重放只有 1 行；同 version 双写只有 1 个赢", "未设该周期预算：不折算、不判定、不发事件"}
	cEvid := []string{
		fmt.Sprintf("3 月阈值 = 120000*80/100 = %d 分；used %d > %d → 已超 %s 元；边界 %d > 2190 = %v（等于不触发，d3 取整定版）", thr, used["2026-03"], thr, yuan(used["2026-03"]-thr), sumC, sumC > 2190),
		fmt.Sprintf("同键重投 3 次 → 通知 %d 条（dedupe 幂等挡回 %d 次）；跨月新键 → 共 %d 条；键可由 type+business_id 推导：%s", marchNotes, seen[key3]-marchNotes, len(seen), key3),
		fmt.Sprintf("整数分 %d == 2190 → 判定 %v；float64 累加 %.17g > 21.90 → %v（★ 误报 1 次，d3 复现）", sumC, sumC > 2190, sumF, sumF > 21.90),
		fmt.Sprintf("crid-77 重放 3 次 → 表内 %d 行（crid-78 新意图另起 1 行，共 %d 行）；PATCH affected=%d/%d；version 终值 %d", n77, len(store), w1, w2, store["bud-q1"].Version),
		fmt.Sprintf("quarter 定义行 %d 条 → Q1 事件 %d 条；三种折算值 %d/%d/%d 互相矛盾且没有一个在库里", nq, nq, fake3, sumQ, x3After),
	}
	cOk := []bool{thr == 96000 && used["2026-03"] > thr && sumC == 2190 && !(sumC > 2190), marchNotes == 1 && len(seen) == 2 && seen[key3] == 3, sumC == 2190 && sumF > 21.90, n77 == 1 && len(store) == 2 && w1 == 1 && w2 == 0 && store["bud-q1"].Version == 2, nq == 0 && fake3 != sumQ && x3After != fake3}
	allPass, nPass := true, 0
	for _, ok := range cOk {
		allPass, nPass = allPass && ok, nPass+map[bool]int{true: 1, false: 0}[ok]
	}
	for i := range cNames {
		fmt.Printf("  判据 %d：%s\n    证据：%s\n    判定：%s\n", i+1, cNames[i], cEvid[i], verdict(cOk[i]))
	}
	fmt.Printf("  %s W44 五条判据当场复算（通过 %d/5），结论由数据算出，不由文案背书。\n", verdict(allPass), nPass)
	hdr("6. 真环境要原样复跑的四件事（本机没有 PostgreSQL，第 3/4 节为 DryRun 与内存替身）")
	for i, s := range []string{
		"同一 crid 并发提交 3 次：断言 UNIQUE(family_id, client_request_id) 让第 2、3 次 23505（内存 map 与真库唯一索引并发下不等价）", "两端拿同一 version 并发 PATCH：断言受影响行数恰为 1/0、定义行无丢失更新、version 终值 = 成功编辑次数 + 1",
		"未设周期：删光 period='quarter' 定义行后开季度视图，断言响应 =「未设该周期预算」、无进度条、outbox 零增量", "day/week 视图：断言同一句「未设该周期预算」（词表里没有这两档，d1 第 6 节），且「回落月度」这类写法查不出来",
	} {
		fmt.Printf("  %c %s\n", []rune("①②③④")[i], s)
	}
	hdr("7. 收口：W44 六天流水账")
	for i, s := range []string{
		"预算四要素与两张表（定义行 vs 周期行）｜挡：把「规则」与「本期用量」混写进一行", "归属与 used 分子口径（时区桶、退款负数、软删剔除）｜挡：报表每次刷新都不一样",
		"判定三段：整数分比较、取整政策定版、判定前现算｜挡：误报、增量漂移、并发丢更新", "事件外发：事务内 outbox、business_id 带 period、alerted_at CAS｜挡：丢事件、幽灵通知、跨月漏提醒",
		"消费端：event_dedupe、member 维度未读、四枚降级词｜挡：红点翻倍、全家互踩、猜数", "（今天）未设周期口径 + 定义行写锁｜挡：折算出来的假额度、编辑丢覆盖",
	} {
		fmt.Printf("  d%d ｜ %s\n", i+1, s)
	}
	fmt.Println("  明天进 W45：周期记账规则（d07）——房租和工资会「自己到点出现」，先给它们立规矩。")
}

// W45 d07：周期记账规则——为什么要有它，以及规则表怎么设计。
//
// 这一天在解决什么问题：
//
//	房租每月 5 号 3200.00、工资每月 10 号入账。若「每月手动记一笔」，账本迟早三种病：
//	漏记、双记、金额手滑。程序先跑 12 个月手动记账把病打出来，再把「在 finance 里自建
//	定时器」这个错误直觉用双实例真跑出重复入账。最后把规则落成 finance_recurring_rule：
//	GORM DryRun 生成真实 Postgres DDL，金额全部 *_cents，表里只有 next_at 没有 timer。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d07
package main

import (
	"fmt"
	"math"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

var fixedNow = time.Date(2026, 3, 1, 8, 0, 0, 0, time.UTC)

// RecurringRule 与 finance_recurring_rule 的列一一对应；没有任何 cron/timer 字段。
type RecurringRule struct {
	ID              string     `gorm:"column:id;primaryKey;size:36"`
	FamilyID        string     `gorm:"column:family_id;size:36;not null;index:idx_rr_family"`
	LedgerID        string     `gorm:"column:ledger_id;size:36;not null"`
	Type            string     `gorm:"column:type;size:16;not null"`
	CategoryID      string     `gorm:"column:category_id;size:36;not null"`
	AccountID       string     `gorm:"column:account_id;size:36;not null"`
	AmountCents     int64      `gorm:"column:amount_cents;not null"`
	Frequency       string     `gorm:"column:frequency;size:16;not null"`
	AnchorDay       int        `gorm:"column:anchor_day;not null;default:0"`
	IntervalValue   int        `gorm:"column:interval_value;not null;default:1"`
	NextAt          *time.Time `gorm:"column:next_at"`
	LastPostedDate  string     `gorm:"column:last_posted_date;size:10"`
	IsActive        bool       `gorm:"column:is_active;not null;default:true"`
	Version         int64      `gorm:"column:version;not null;default:1"`
	ClientRequestID string     `gorm:"column:client_request_id;size:64;not null;uniqueIndex:uq_rr_crid"`
	CreatedAt       time.Time
	UpdatedAt       time.Time
	DeletedAt       *time.Time `gorm:"column:deleted_at"`
	DeletedBy       string     `gorm:"column:deleted_by;size:36"`
}

func (RecurringRule) TableName() string { return "finance_recurring_rule" }
func H(n int, s string)                 { fmt.Printf("\n===== %d. %s =====\n", n, s) }
func L(s string)                        { fmt.Println("  " + s) }
func yuan(c int64) string               { return fmt.Sprintf("%d.%02d", c/100, c%100) }
func flat(s string) string              { return strings.Join(strings.Fields(s), " ") }
func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN:                  "host=127.0.0.1 user=svc_finance dbname=homecube sslmode=disable",
		PreferSimpleProtocol: true,
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		NowFunc: func() time.Time { return fixedNow },
		Logger:  logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err) // DryRun+DisableAutomaticPing 下 Open 不会失败
	}
	return db
}

