// W45 d08：下一个触发日——每月 31 号在短月怎么办。
//
//	「每月 31 号」在 2 月不存在。两种口径：顺延（clamped，落到当月最后一天）和跳过
//	（skip，整期不触发）不是同一个功能的两种叫法，是两套业务：一年 12 次 vs 7 次。
//	程序先把「上次日期+1 个月」的链式加法真跑出丢锚点，再实现从锚点计算的两种口径，
//	把次数、年总额、最长间隔打出来对比，最后分清「跳过某一次」与「跳过语义」。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d08
package main

import (
	"fmt"
	"strings"
	"time"
)

var utc = time.UTC

func H(n int, s string) { fmt.Printf("\n===== %d. %s =====\n", n, s) }
func L(s string)        { fmt.Println("  " + s) }

func daysInMonth(y, m int) int {
	// 下个月第 0 天 = 本月最后一天，Go 日期归一化白送的算法
	return time.Date(y, time.Month(m)+1, 0, 0, 0, 0, 0, utc).Day()
}

// monthOcc：从锚点（anchor=几号）算某月触发日。ok=false 表示该月不存在（skip 语义）。
func monthOcc(y, m, anchor int, skip bool) (time.Time, bool) {
	d := anchor
	if d > daysInMonth(y, m) {
		if skip {
			return time.Time{}, false
		}
		d = daysInMonth(y, m) // 顺延：落到当月最后一天
	}
	return time.Date(y, time.Month(m), d, 0, 0, 0, 0, utc), true
}

// nextOccurrence：严格晚于 after 的下一次触发（从锚点算，绝不从上次日期加月份）。
func nextOccurrence(after time.Time, anchor int, skip bool) time.Time {
	y, m := after.Year(), int(after.Month())
	for i := 0; i < 48; i++ { // 最多往后找 4 年（skip 语义下 2 月 30 号等也能收敛）
		if t, ok := monthOcc(y, m, anchor, skip); ok && t.After(after) {
			return t
		}
		m++
		if m == 13 {
			m, y = 1, y+1
		}
	}
	panic("找不到下一次触发")
}

func gapDays(a, b time.Time) int { return int(b.Sub(a).Hours() / 24) }
func main() {
	H(1, "错误直觉：拿上次日期链式加一个月——锚点会整个丢掉")
	anchor := 31
	L("直觉写法：next_at = 上一次 next_at.AddDate(0, 1, 0)。从 2026-01-31 跑 12 步：")
	t := time.Date(2026, 1, anchor, 0, 0, 0, 0, utc)
	lost := 0
	for i := 1; i <= 12; i++ {
		t = t.AddDate(0, 1, 0) // Go 归一化：2026-02-31 → 2026-03-03
		mark := "✓"
		if t.Day() != anchor {
			lost++
			mark = fmt.Sprintf("✗ 已经不是 %d 号了", anchor)
		}
		fmt.Printf("  第 %2d 步 → %s  %s\n", i, t.Format("2006-01-02"), mark)
	}
	fmt.Printf("  结果：12 次里 %d 次丢锚点，31 号从此永久变成 %d 号——规则本身被一次短月「带偏」\n",
		lost, t.Day())
	t2 := time.Date(2026, 1, 30, 0, 0, 0, 0, time.UTC).AddDate(0, 2, 0)
	fmt.Printf("  连 30 号也中招：1-30 链式 +2 月 → %s，锚点 30 号被 2 月归一化弄丢\n", t2.Format("2006-01-02"))
	L("教训：触发日必须永远从「锚点（anchor_day）+ 目标月份」重算，不能从上次结果加。")
	L("为什么锚点会丢？因为 Go 的日期归一化是「进位」不是「夹紧」：")
	for _, d := range [][3]int{{2026, 2, 31}, {2028, 2, 31}, {2026, 4, 31}} {
		n := time.Date(d[0], time.Month(d[1]), d[2], 0, 0, 0, 0, utc)
		fmt.Printf("  %04d-%02d-%02d 归一化成 %s（Go 进位，不报错、不夹紧）\n", d[0], d[1], d[2], n.Format("2006-01-02"))
	}
	H(2, "口径 A：顺延（clamped）——短月落到当月最后一天")
	sum := 0
	for m := 1; m <= 12; m++ {
		d, _ := monthOcc(2026, m, anchor, false)
		clamp := ""
		if d.Day() != anchor {
			clamp = fmt.Sprintf("← %d 月只有 %d 天，顺延", m, daysInMonth(2026, m))
			sum++
		}
		fmt.Printf("  2026-%02d → %s %s\n", m, d.Format("2006-01-02"), clamp)
	}
	fmt.Printf("  一年 %d 次触发，其中 %d 次被顺延；下一年 2 月对照：", 12, sum)
	dl, _ := monthOcc(2028, 2, anchor, false)
	fmt.Println(dl.Format("2006-01-02") + "（闰年 2 月 29 天，顺延跟着走）")
	H(3, "口径 B：跳过（skip）——没有 31 号的月份整期不触发")
	var sk []time.Time
	for m := 1; m <= 12; m++ {
		if d, ok := monthOcc(2026, m, anchor, true); ok {
			sk = append(sk, d)
			gap := "-"
			if len(sk) > 1 {
				gap = fmt.Sprintf("距上期 %d 天", gapDays(sk[len(sk)-2], d))
			}
			fmt.Printf("  2026-%02d → %s（%s）\n", m, d.Format("2006-01-02"), gap)
		} else {
			fmt.Printf("  2026-%02d → 无 31 号，本月跳过\n", m)
		}
	}
	maxSkip := 0
	for i := 1; i < len(sk); i++ {
		if g := gapDays(sk[i-1], sk[i]); g > maxSkip {
			maxSkip = g
		}
	}
	fmt.Printf("  一年只触发 %d 次，最长间隔 %d 天\n", len(sk), maxSkip)
	H(4, "先把地基摆出来：每月天数（上面两种口径的差别全部来自这张表）")
	fmt.Print("  月份   ")
	for m := 1; m <= 12; m++ {
		fmt.Printf("%4d ", m)
	}
	fmt.Println()
	for _, y := range []int{2026, 2028} {
		fmt.Printf("  %d 年 ", y)
		var has []string
		for m := 1; m <= 12; m++ {
			fmt.Printf("%4d ", daysInMonth(y, m))
			if daysInMonth(y, m) >= anchor {
				has = append(has, fmt.Sprintf("%d月", m))
			}
		}
		fmt.Printf(" ← 2 月 %d 天；有 %d 号的月份：%s\n", daysInMonth(y, 2), anchor, strings.Join(has, " "))
	}
	H(5, "两种口径对比：数字自己算，别拍脑袋")
	var cl []time.Time
	for m := 1; m <= 12; m++ {
		d, _ := monthOcc(2026, m, anchor, false)
		cl = append(cl, d)
	}
	maxClamp := 0
	for i := 1; i < len(cl); i++ {
		if g := gapDays(cl[i-1], cl[i]); g > maxClamp {
			maxClamp = g
		}
	}
	const rentCents = int64(320000)
	fmt.Printf("  %-14s %-8s %-10s %-12s\n", "口径", "年次数", "年入账(分)", "最长间隔(天)")
	fmt.Printf("  %-14s %-8d %-10d %-12d\n", "顺延 clamped", len(cl), rentCents*int64(len(cl)), maxClamp)
	fmt.Printf("  %-14s %-8d %-10d %-12d\n", "跳过 skip", len(sk), rentCents*int64(len(sk)), maxSkip)
	fmt.Printf("  年入账差额：%d 分 = %d 元——房租按 skip 记，一年少付 %d 个月\n",
		rentCents*(int64(len(cl))-int64(len(sk))), rentCents*(int64(len(cl))-int64(len(sk)))/100,
		len(cl)-len(sk))
	L("结论：语义必须由产品定死并写进契约/测试，不能留给实现者「顺手」选一个。")
	L("本项目选顺延：房租/房贷不可能「因为没有 31 号就不该付」；订阅类才可考虑 skip。")
	H(6, "顺延之后锚点要能回来——链式实现的第二种死法")
	a := time.Date(2026, 4, 30, 0, 0, 0, 0, utc) // 4 月被顺延到 30 号
	wrong := a.AddDate(0, 1, 0)
	right := nextOccurrence(a, anchor, false)
	fmt.Printf("  上期落在 2026-04-30（顺延结果）。链式 +1 月 → %s（错，5 月明明有 31 号）\n", wrong.Format("2006-01-02"))
	fmt.Printf("  从锚点重算        → %s（对，锚点自动恢复）\n", right.Format("2006-01-02"))
	H(7, "「跳过某一次」≠「跳过语义」：这是两件事")
	next := time.Date(2026, 3, 31, 0, 0, 0, 0, utc)
	fmt.Printf("  规则（顺延语义，anchor=31）当前 next_at = %s\n", next.Format("2006-01-02"))
	nn := nextOccurrence(next, anchor, false)
	fmt.Printf("  用户「这个月出差，跳过这一次」= 把 next_at 前移一期 → %s\n", nn.Format("2006-01-02"))
	fmt.Printf("  再下一次（什么都没改）→ %s，31 号锚点还在，规则 frequency/anchor_day 一字未动\n",
		nextOccurrence(nn, anchor, false).Format("2006-01-02"))
	L("跳过某一次是改一行数据（next_at），跳过语义是改规则模型（少 5 次/年、年总额不同）。")
	L("把「跳过一次」实现成「把规则改成 skip 语义」，等于用户请了一天假被改成了辞职。")
	H(8, "性质自检：nextOccurrence 的两条不变量")
	mono, okDay := true, true
	leap := "-"
	probe := time.Date(2026, 1, 31, 0, 0, 0, 0, utc)
	for i := 0; i < 36; i++ { // 连续推进 36 期，跨 2026/2027/2028（含闰年 2 月）
		nxt := nextOccurrence(probe, anchor, false)
		if !nxt.After(probe) {
			mono = false
		}
		if nxt.Day() > daysInMonth(nxt.Year(), int(nxt.Month())) {
			okDay = false
		}
		if nxt.Year() == 2028 && int(nxt.Month()) == 2 {
			leap = nxt.Format("2006-01-02")
		}
		probe = nxt
	}
	recoverOK := true
	prev2 := time.Date(2026, 1, 1, 0, 0, 0, 0, utc)
	for i := 0; i < 24; i++ {
		o := nextOccurrence(prev2, anchor, false)
		if o.Day() != anchor && o.Day() != daysInMonth(o.Year(), int(o.Month())) {
			recoverOK = false // 既不是锚点又不是月末 = 夹紧算错了
		}
		prev2 = o
	}
	fmt.Printf("  36 期连续推进：严格递增 = %v；每次都是当月真实存在的日期 = %v\n", mono, okDay)
	fmt.Printf("  24 期锚点检查：每次触发要么正好 %d 号、要么恰好是当月最后一天 = %v\n", anchor, recoverOK)
	fmt.Printf("  序列首尾：%s → %s（3 年，跨 2028 闰年）\n",
		time.Date(2026, 1, 31, 0, 0, 0, 0, utc).Format("2006-01-02"), probe.Format("2006-01-02"))
	fmt.Printf("  跨过闰年 2028-02 的那一期：%s（顺延到 29 号而不是跳过 4 年——clamped 语义）\n", leap)
	L("真环境里这两条就是 finance_recurring_rule 触发计算的单测断言（-count=1 跑）。")
	L("注意不变量的主语是「下一次触发日」，不是「这次是否入账」——入账另有幂等键（d11）。")
	L("顺延语义下任何一期都不会落在不存在的日期上，这是 next_at 能进到期中心的前提（d10）。")
	H(9, "顺延序列滚动实录：nextOccurrence 连打 12 期（d11 回写 next_at 走的就是这条轨迹）")
	p := time.Date(2026, 1, 1, 0, 0, 0, 0, utc)
	for i := 1; i <= 12; i++ {
		p = nextOccurrence(p, anchor, false)
		fmt.Printf("  第 %2d 期 → %s（%d 月共 %d 天）\n", i, p.Format("2006-01-02"), int(p.Month()), daysInMonth(p.Year(), int(p.Month())))
	}
	L("明天（d09）：每周（指定星期几）、每年 2/29、自定义间隔 every_n_*，外加同样的边界。")
}

// W45 d09：每周（指定星期几）、每年 2/29、自定义间隔 every_n_* 的触发日计算。
//
//	d08 把「每月」的短月边界钉死了。今天补其余频率：每周的锚点是「星期几」，用户
//	改期后再拿旧 next_at 加 7 天，星期会永久漂移（真跑给你看）；每年的锚点可能是
//	2/29——「只在闰年」与「平年顺延 2/28」差到 1461 天间隔；every_n_days 是纯天数
//	运算没有非法日期，every_n_months 则有 d08 的全部问题再加跨 k 步的锚点恢复。
//	最后用一个分发器把五种频率收敛成 nextOccurrence(freq, after) 跑同一组不变量。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d09
package main

import (
	"fmt"
	"time"
)

var utc = time.UTC

func H(n int, s string)          { fmt.Printf("\n===== %d. %s =====\n", n, s) }
func L(s string)                 { fmt.Println("  " + s) }
func ds(t time.Time) string      { return t.Format("2006-01-02") }
func gapDays(a, b time.Time) int { return int(b.Sub(a).Hours() / 24) }

func daysInMonth(y, m int) int {
	return time.Date(y, time.Month(m)+1, 0, 0, 0, 0, 0, utc).Day()
}
func monthOcc(y, m, anchor int, skip bool) (time.Time, bool) {
	d := anchor
	if d > daysInMonth(y, m) {
		if skip {
			return time.Time{}, false
		}
		d = daysInMonth(y, m)
	}
	return time.Date(y, time.Month(m), d, 0, 0, 0, 0, utc), true
}

// nextWeekday：严格晚于 after 的第一个 wd——永远从星期锚点算，不从上次日期加 7。
func nextWeekday(after time.Time, wd time.Weekday) time.Time {
	for i := 1; i <= 7; i++ {
		if t := after.AddDate(0, 0, i); t.Weekday() == wd {
			return t
		}
	}
	panic("一周只有 7 天")
}

// nextNDays：every_n_days——锚定首期后纯天数，没有非法日期问题。
func nextNDays(first time.Time, n int, after time.Time) time.Time {
	k := int(after.Sub(first).Hours()/24)/n + 1
	return first.AddDate(0, 0, k*n)
}

// nextMonthStep：月步进频率的统一内核。anchor 决定「几号」与起始月；n=1 是每月、
// n=12 是每年、n=2 是每两月。从「绝对月序」步进，短月按 skip 夹紧或跳过。
func nextMonthStep(anchor time.Time, n int, skip bool, after time.Time) time.Time {
	ai := anchor.Year()*12 + int(anchor.Month()) - 1 // 绝对月序：0 起，避免 12 月回绕错位
	for k := 0; k < 480; k++ {
		idx := ai + k*n
		if t, ok := monthOcc(idx/12, idx%12+1, anchor.Day(), skip); ok && t.After(after) {
			return t
		}
	}
	panic("月步进未收敛")
}

func main() {
	H(1, "每周（指定星期几）：改期之后链式 +7 天，星期会永久漂移")
	wed := time.Date(2026, 1, 7, 0, 0, 0, 0, utc) // 星期三
	edited := time.Date(2026, 2, 10, 0, 0, 0, 0, utc)
	fmt.Printf("  规则「每周三 会员费 4500 分」。首期 %s（%s）。用户改期到 %s（%s），实现继续 +7 天：\n",
		ds(wed), wed.Weekday(), ds(edited), edited.Weekday())
	t, wrongWD := edited, 0
	for i := 1; i <= 12; i++ {
		t = t.AddDate(0, 0, 7)
		if t.Weekday() != time.Wednesday {
			wrongWD++
		}
		fmt.Printf("  第 %2d 期 → %s %s\n", i, ds(t), t.Weekday())
	}
	fmt.Printf("  12 期里 %d 期不是星期三——用户改了一次日期，规则从此变成「每周二」\n", wrongWD)
	L("对照正确实现（永远从「星期三」这个星期锚点重算，改期只是换了起算点）：")
	p := edited
	for i := 1; i <= 6; i++ {
		p = nextWeekday(p, time.Wednesday)
		fmt.Printf("  第 %d 期 → %s %s\n", i, ds(p), p.Weekday())
	}
	L("每周的链式 +7 天在「没改期」时碰巧没错——改期、补跑、时区跳变之后锚点失守。")
	L("教训与 d08 同构：触发日永远从锚点（星期几/几号）重算，next_at 只是缓存。")
	H(2, "每周不变量：连续 20 期间隔恒 7 天、星期恒为锚点（逐期打出来）")
	q := edited
	all7, allWed := true, true
	for i := 1; i <= 20; i++ {
		old := q
		nq := nextWeekday(q, time.Wednesday)
		if i > 1 && gapDays(old, nq) != 7 { // 首期距「改期日」只差 1 天，不计入周期不变量
			all7 = false
		}
		if nq.Weekday() != time.Wednesday {
			allWed = false
		}
		q = nq
		fmt.Printf("  第 %2d 期 %s %s（距上期 %d 天）\n", i, ds(q), q.Weekday(), gapDays(old, q))
	}
	fmt.Printf("  汇总：第 2 期起间隔全为 7 天 = %v；20 期星期全为 Wednesday = %v\n", all7, allWed)
	H(3, "每年 2/29：「只在闰年」与「平年顺延 2/28」是两套口径")
	L("口径 A（skip，生日语义：没有 2/29 就不庆祝）：")
	a := time.Date(2020, 2, 29, 0, 0, 0, 0, utc)
	for i := 1; i <= 3; i++ {
		var na time.Time
		for y := a.Year() + 1; y < a.Year()+9; y++ {
			if d, ok := monthOcc(y, 2, 29, true); ok {
				na = d
				break
			}
		}
		fmt.Printf("  %s → %s（间隔 %d 天）\n", ds(a), ds(na), gapDays(a, na))
		a = na
	}
	L("口径 B（clamped，会费语义：平年顺延到 2/28，闰年回到 2/29）：")
	leapAnchor := time.Date(2020, 2, 29, 0, 0, 0, 0, utc)
	b := time.Date(2025, 1, 1, 0, 0, 0, 0, utc)
	for i := 1; i <= 4; i++ {
		b = nextMonthStep(leapAnchor, 12, false, b)
		note := "平年顺延"
		if b.Day() == 29 {
			note = "闰日本尊"
		}
		fmt.Printf("  第 %d 年 → %s（%s）\n", i, ds(b), note)
	}
	ca := 0
	for y := 2021; y <= 2028; y++ {
		if _, ok := monthOcc(y, 2, 29, true); ok {
			ca++
		}
	}
	fmt.Printf("  8 年（2021—2028）内次数：A=%d 次，B=8 次——总额差 %d 期，选哪套又是业务决定\n", ca, 8-ca)
	H(4, "every_n_days=10：从 2026-01-25 起 8 期，跨月都不存在非法日期")
	first := time.Date(2026, 1, 25, 0, 0, 0, 0, utc)
	x, okGap, crossCnt := first, true, 0
	fmt.Printf("  第 1 期 → %s（首期即锚点，之后全靠 +10 天）\n", ds(first))
	for i := 2; i <= 8; i++ {
		nx := nextNDays(first, 10, x)
		if gapDays(x, nx) != 10 {
			okGap = false
		}
		cross := ""
		if int(x.Month()) != int(nx.Month()) {
			cross, crossCnt = "  ← 跨月", crossCnt+1
		}
		fmt.Printf("  第 %d 期 → %s（距上期 %d 天）%s\n", i, ds(nx), gapDays(x, nx), cross)
		x = nx
	}
	fmt.Printf("  间隔全部 = 10 天：%v；跨月 %d 次——2 月只有 28 天也不影响，天数运算没有非法日期\n", okGap, crossCnt)
	H(5, "every_n_months=2，锚点 31 号：d08 的问题 ×2 步进 + 锚点恢复")
	anchorDate := time.Date(2026, 1, 31, 0, 0, 0, 0, utc)
	m, recovered := time.Date(2026, 1, 1, 0, 0, 0, 0, utc), false
	for i := 1; i <= 8; i++ {
		nm := nextMonthStep(anchorDate, 2, false, m)
		if m.Day() != 31 && nm.Day() == 31 {
			recovered = true
		}
		clamp := ""
		if nm.Day() != 31 {
			clamp = "（短月顺延）"
		}
		fmt.Printf("  第 %d 期 → %s %d 天%s\n", i, ds(nm), gapDays(m, nm), clamp)
		m = nm
	}
	fmt.Printf("  被顺延的期之后能否回到 31 号：%v（关键：步长走「绝对月序」，不走上次日期）\n", recovered)
	H(6, "分发器：五种频率一套不变量——严格递增 + 日期真实存在 + 间隔有界")
	type rr struct {
		name string
		next func(after time.Time) time.Time
	}
	start := time.Date(2026, 1, 31, 0, 0, 0, 0, utc)
	freqs := []rr{
		{"weekly#3", func(t time.Time) time.Time { return nextWeekday(t, time.Wednesday) }},
		{"monthly#31", func(t time.Time) time.Time { return nextMonthStep(start, 1, false, t) }},
		{"yearly#2-29clamped", func(t time.Time) time.Time { return nextMonthStep(leapAnchor, 12, false, t) }},
		{"every_10_days", func(t time.Time) time.Time { return nextNDays(start, 10, t) }},
		{"every_2_months#31", func(t time.Time) time.Time { return nextMonthStep(start, 2, false, t) }},
	}
	for _, f := range freqs {
		prev, mono, real, maxGap := start, true, true, 0
		for i := 1; i <= 15; i++ {
			nx := f.next(prev)
			if !nx.After(prev) {
				mono = false
			}
			if nx.Day() > daysInMonth(nx.Year(), int(nx.Month())) {
				real = false
			}
			if g := gapDays(prev, nx); g > maxGap {
				maxGap = g
			}
			prev = nx
			if i <= 3 {
				fmt.Printf("    %-20s 第 %d 期 %s\n", f.name, i, ds(prev))
			}
		}
		fmt.Printf("    %-20s 15 期：递增=%v 日期真实=%v 最长间隔=%d 天\n", f.name, mono, real, maxGap)
	}
	L("最长间隔这一列就是口径的指纹：clamped 语义下所有频率间隔都有界（≈2 个周期）；")
	L("换成 skip 语义，monthly#31 会到 62 天、yearly#2-29 会到 1461 天——一眼能看出少记了期。")
	L("这五条 PASS 就是 W45 判据「下一个触发日要算对」的最小复现集：真环境原样搬进 go test。")
	L("明天（d10）：next_at 怎么注册进 calendar 到期中心——S9 契约在规则上的真实应用。")
}

// W45 d10：把规则的 next_at 注册进 calendar 到期中心——S9 契约的真实应用。
//
//	d08/d09 把「下一次触发日」算对了，今天回答「到点谁来响」。错误直觉有两个：
//	① 注册时把未来 12 期一次性全登记（calendar 变成规则的回声）；② 不登记、让
//	finance 自己扫 next_at 列（=d07 的自建定时器换了个名字）。正确做法是 S9 的
//	注册契约：规则只把「唯一一个未来日期 next_at」登记为 calendar 的到期项，
//	幂等键 (source_system, source_id, kind) 保证改期重注册是 upsert 不是追加。
//	注意周期语义不进 calendar——repeat 传 "none"，第二期的真相只在 finance。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d10
package main

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"
)

func H(n int, s string)     { fmt.Printf("\n===== %d. %s =====\n", n, s) }
func L(s string)            { fmt.Println("  " + s) }
func ds(t time.Time) string { return t.Format("2006-01-02") }

// RegPayload = {code}.due.registered 的 payload（S9 d2 的十字段契约，一字不加）。
type RegPayload struct {
	SourceSystem   string   `json:"source_system"`
	SourceID       string   `json:"source_id"`
	SourceFamilyID string   `json:"family_id"`
	Title          string   `json:"title"`
	DueAt          string   `json:"due_at"`
	Participants   []string `json:"participants"`
	Repeat         string   `json:"repeat"`
	Priority       string   `json:"priority"`
	DoneReturnsTo  string   `json:"done_returns_to"`
	Visibility     string   `json:"visibility"`
	Kind           string   `json:"kind"`
}

type Envelope struct {
	Type, BusID, Idem string
	Payload           RegPayload
	Status            string
}

// Calendar：到期中心。只认幂等三元组 (source_system, source_id, kind)，upsert。
type Calendar struct {
	items map[string]*RegPayload
	log   []string
	reads map[string]int // 各表被读了多少次——用来证明没有跨 schema 读
}

func (c *Calendar) Consume(e Envelope) string {
	key := e.Payload.SourceSystem + "|" + e.Payload.SourceID + "|" + e.Payload.Kind
	if e.Payload.SourceFamilyID == "" || e.Payload.DueAt == "" || len(e.Payload.Participants) == 0 {
		return "REJECT(缺字段)"
	}
	if old, ok := c.items[key]; ok {
		*old = e.Payload // upsert：同一幂等三元组永远只有一个到期项
		c.log = append(c.log, "UPSERT "+key+" due="+e.Payload.DueAt)
		return "DEDUP(upsert 到 " + e.Payload.DueAt + ")"
	}
	c.items[key] = &e.Payload
	c.log = append(c.log, "INSERT "+key+" due="+e.Payload.DueAt)
	return "ACCEPT"
}

// Finance：规则只写自己的表；对外只发注册意图，不自建定时器。
type Rule struct {
	ID, FamilyID, Title string
	AmountCents         int64
	Freq                string
	NextAt              time.Time
	IsActive            bool
}

func buildReg(r *Rule) RegPayload {
	return RegPayload{
		SourceSystem: "finance", SourceID: r.ID, SourceFamilyID: r.FamilyID,
		Title: r.Title + "（周期记账 " + ds(r.NextAt) + " 应自动入账）",
		DueAt: ds(r.NextAt), Participants: []string{"mem-001", "mem-002"},
		Repeat:   "none", // 关键：周期的真相只在 finance；calendar 只登记「这一次」
		Priority: "high", DoneReturnsTo: "finance:" + r.ID + ":auto_post",
		Visibility: "family", Kind: "reminder",
	}
}

func newEnvelope(r *Rule) Envelope {
	p := buildReg(r)
	return Envelope{
		Type:    "finance.due.registered",
		BusID:   p.SourceID + ":" + p.DueAt, // tech-plan §7.5：business_id = {source_id}:{due_at}
		Idem:    p.SourceSystem + "|" + p.SourceID + "|" + p.Kind,
		Payload: p, Status: "pending",
	}
}

func main() {
	H(1, "错误直觉 ①：把未来 12 期一次性全部注册——到期中心变成规则的回声")
	cal := &Calendar{items: map[string]*RegPayload{}, reads: map[string]int{}}
	r := &Rule{ID: "rr-001", FamilyID: "fam-7f3a", Title: "房租", AmountCents: 320000,
		Freq: "monthly", NextAt: time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC), IsActive: true}
	base := r.NextAt
	for i := 0; i < 12; i++ {
		p := buildReg(r)
		p.SourceID = fmt.Sprintf("%s#%d", r.ID, i+1) // 想出来的「每期一条」source_id
		p.DueAt = ds(base.AddDate(0, i, 0))
		fmt.Printf("  登记 %s due=%s → %s\n", p.SourceID, p.DueAt, cal.Consume(Envelope{Type: "finance.due.registered", Payload: p}))
	}
	fmt.Printf("  注册后 calendar 条目数 = %d（一条规则回声成 12 条）\n", len(cal.items))
	L("后果：改期/改额/停用要撤销的是 11 条而不是 1 条；撤销漏掉任何一条 = 幽灵提醒；")
	L("更糟的是第 2 期之后每期的金额都冻在注册那一刻——规则改了金额，回声不会改。")
	L("本项目禁止这种写法：规则永远只注册「唯一 next_at」这一条（下一节）。")

	H(2, "错误直觉 ②：不注册，finance 自己扫 next_at 列")
	L("这就是 d07 第 2 节的自建定时器：多副本各扫各的、改期两处同步、到期中心看不到")
	L("这一行（首页到期聚合里房租凭空缺席）。注册与不注册的选择，本质是「到期这件事")
	L("存在哪」：答案只能是 calendar_reminder 一张表，不能是它 + finance 的扫描游标。")
	L("判据 6「周期记账规则到点后自动在到期中心触发」的主语是到期中心——不注册就无从触发。")
	L("首页/到期中心/通知三条链共用这一份真相；finance 的游标是第四份真相，必发散。")

	H(3, "正确做法：建规则 = 写自己的表 + 发一条 due.registered（只登记 next_at）")
	cal = &Calendar{items: map[string]*RegPayload{}, reads: map[string]int{}}
	var outbox []Envelope
	rules := []*Rule{r,
		{ID: "rr-002", FamilyID: "fam-7f3a", Title: "房贷", AmountCents: 860050,
			Freq: "monthly", NextAt: time.Date(2026, 4, 1, 0, 0, 0, 0, time.UTC), IsActive: true},
		{ID: "rr-003", FamilyID: "fam-7f3a", Title: "健身会员", AmountCents: 4500,
			Freq: "weekly", NextAt: time.Date(2026, 3, 4, 0, 0, 0, 0, time.UTC), IsActive: true},
	}
	for _, rl := range rules {
		env := newEnvelope(rl)
		outbox = append(outbox, env)
		fmt.Printf("  %s：INSERT finance_recurring_rule → 发 %s (business_id=%s)\n",
			rl.ID, env.Type, env.BusID)
	}
	L("信封 payload 全文（rr-001，落到事件表里就是这个 JSON——注意 participants 不是 null）：")
	j, _ := json.MarshalIndent(outbox[0].Payload, "  ", "  ")
	fmt.Printf("  %s\n", string(j))
	bad := outbox[0].Payload
	bad.Participants = nil
	j2, _ := json.Marshal(bad)
	i := strings.Index(string(j2), "participants")
	fmt.Printf("  反例：participants 传 nil slice → JSON 该字段变 %s（其余字段省略）\n", string(j2)[i-1:i+18])
	L("S9 d2 的老坑在规则场景原样复现：前端 JSON.parse 后 participants.map 直接炸。")

	H(4, "投递：calendar 消费 due.registered → 每条规则恰有一个到期项")
	for _, e := range outbox {
		fmt.Printf("  %s idem=[%s] → %s\n", e.BusID, e.Idem, cal.Consume(e))
	}
