// W45 d11：到点自动入账全链路——fired 事件回来 → 写流水 → 回写 next_at → 重注册。
//
//	d10 把 next_at 登记进了到期中心。今天走完整条链：calendar 到点发
//	calendar.reminder.fired → finance 消费 → 按规则写一笔流水（金额仍是 *_cents）
//	→ 用 d08/d09 的算法算出下一个 next_at → 乐观锁回写规则 → 再发一条
//	due.registered。自动入账的幂等口径是 (rule_id, due_date) 唯一键：同一规则
//	同一触发日重放多少次都只有一笔流水。它和 client_request_id 分工不同——
//	一个挡系统生成的重复入账，一个挡用户重复提交，程序里两层都真跑。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d11
package main

import (
	"fmt"
	"time"
)

var utc = time.UTC

func H(n int, s string)     { fmt.Printf("\n===== %d. %s =====\n", n, s) }
func L(s string)            { fmt.Println("  " + s) }
func ds(t time.Time) string { return t.Format("2006-01-02") }
func yuan(c int64) string   { return fmt.Sprintf("%d.%02d", c/100, c%100) }

func monthOcc(y, m, anchor int) time.Time { // 顺延口径（d08 定）：短月夹到当月最后一天
	last := time.Date(y, time.Month(m)+1, 0, 0, 0, 0, 0, utc).Day()
	if anchor > last {
		anchor = last
	}
	return time.Date(y, time.Month(m), anchor, 0, 0, 0, 0, utc)
}
func nextMonthly(anchor time.Time, after time.Time) time.Time {
	ai := anchor.Year()*12 + int(anchor.Month()) - 1
	for k := 0; k < 26; k++ {
		idx := ai + k
		if t := monthOcc(idx/12, idx%12+1, anchor.Day()); t.After(after) {
			return t
		}
	}
	panic("monthly 未收敛")
}

type Rule struct {
	ID, Title, Freq string
	AmountCents     int64
	Anchor          time.Time // 锚点日期：几号/星期几都从它取
	NextAt          time.Time
	IsActive        bool
	Version         int64
}
type Txn struct {
	ID, RuleID, DueDate string
	AmountCents         int64
	ClientRequestID     string
}
type Calendar struct{ items map[string]string } // key: finance|rule|reminder → due_at

var txns []Txn
var posted = map[string]bool{} // 模拟唯一索引 uq_txn_rule_due (rule_id, due_date)
var crids = map[string]bool{}  // 模拟 client_request_id 唯一键
var notifs, dupHits, postedCnt int
var cal = Calendar{items: map[string]string{}}

func registerDue(r *Rule, quiet bool) {
	key := "finance|" + r.ID + "|reminder"
	delete(cal.items, key) // 上一期已消耗（fired 之后该项完成使命）
	cal.items[key] = ds(r.NextAt)
	if !quiet {
		fmt.Printf("      ↳ 重注册 due.registered: %s due=%s（幂等键同一条，upsert）\n", key, ds(r.NextAt))
	}
}

// onFired：finance 消费 calendar.reminder.fired 的完整处理，返回判定。
func onFired(r *Rule, firedDate string) string {
	notifs++ // homeos 已下发提醒——它不知道也不该知道 finance 后面成没成
	key := r.ID + "|" + firedDate
	if !r.IsActive {
		return "SKIP_INACTIVE（提醒已发出 1 条、入账 0 笔——这就是幽灵，撤销链路见 d12）"
	}
	if posted[key] {
		dupHits++
		return "DUP：(rule_id, due_date)=" + key + " 命中唯一索引，拒绝第二次入账"
	}
	// 写流水 + 幂等键 + 回写 next_at + 重注册，四步在同一个事务里（模拟原子性）
	crid := "recurring:" + r.ID + ":" + firedDate // 自动入账没有 HTTP，crid 用推导值
	posted[key] = true
	postedCnt++
	txns = append(txns, Txn{ID: fmt.Sprintf("tx-%03d", postedCnt), RuleID: r.ID,
		DueDate: firedDate, AmountCents: r.AmountCents, ClientRequestID: crid})
	nxt := nextMonthly(r.Anchor, r.NextAt) // weekly 的算法在 d09 已验证；本链只跑 monthly
	r.NextAt = nxt
	r.Version++
	fmt.Printf("    INSERT txn %s rule=%s due=%s amount_cents=%d crid=%s\n",
		txns[len(txns)-1].ID, r.ID, firedDate, r.AmountCents, crid)
	fmt.Printf("    UPDATE rule %s SET next_at=%s, version=%d WHERE version=%d（乐观锁）\n",
		r.ID, ds(nxt), r.Version, r.Version-1)
	registerDue(r, false)
	return "POSTED"
}

