func countPair(rule, due string) int {
	n := 0
	for _, t := range txns {
		if t.RuleID == rule && t.DueDate == due {
			n++
		}
	}
	return n
}
func findTxn(rule, due string) *Txn {
	for i := range txns {
		if txns[i].RuleID == rule && txns[i].DueDate == due {
			return &txns[i]
		}
	}
	return nil
}

