//
//	d11 留了个尾巴：规则停了、入账挡住了，但提醒照发——幽灵。今天补上 {code}.due.revoked
//	反向链路（paused / source_deleted / completed_early 三种 reason 各跑一遍并打印真实事件
//	JSON），再验级联边界：删规则只撤「未来到期项」、历史流水一行不动、停用窗口不补记、并发
//	改规则撞乐观锁；最后逐期推进到 2026 年底，用真跑出来的计数把 W45 判据逐条打勾。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d12
package main

import (
	"encoding/json"
	"fmt"
	"time"
)

func H(n int, s string)       { fmt.Printf("\n===== %d. %s =====\n", n, s) }
func L(s string)              { fmt.Println("  " + s) }
func ds(t time.Time) string   { return t.Format("2006-01-02") }
func yuan(c int64) string     { return fmt.Sprintf("%d.%02d", c/100, c%100) }
func key(id string) string    { return "finance|" + id + "|reminder" }
func D(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, time.UTC) }

// 规则行：周期真相全在 finance，到期中心只持有「这一条 next_at」。
type Rule struct {
	ID, Title string
	Amount    int64 // amount_cents：整数分（铁律 #1）；规则只存口径，不存历史值
	Anchor    time.Time
	NextAt    time.Time // 唯一的「下一次」真相，注册进到期中心的就是它
	IsActive  bool      // FALSE = 已停用或已软删（deleted_at/deleted_by 另两列），到期注册必须已撤销
	Version   int64
}
type Txn struct {
	RuleID, DueDate string
	Amount          int64
}

var (
	rules = []*Rule{
		{ID: "rr-001", Title: "房租", Amount: 320000, Anchor: D(2026, 1, 5), NextAt: D(2026, 4, 5), IsActive: true, Version: 4},
		{ID: "rr-005", Title: "车位月租", Amount: 60000, Anchor: D(2026, 1, 10), NextAt: D(2026, 4, 10), IsActive: true, Version: 2},
		{ID: "rr-009", Title: "网盘会员", Amount: 2990, Anchor: D(2026, 1, 31), NextAt: D(2026, 5, 31), IsActive: true, Version: 1},
	}
	txns                                                         = []Txn{{"rr-001", "2026-01-05", 320000}, {"rr-001", "2026-02-05", 320000}, {"rr-001", "2026-03-05", 320000}, {"rr-005", "2026-02-10", 60000}, {"rr-005", "2026-03-10", 60000}, {"rr-009", "2026-01-31", 2990}, {"rr-009", "2026-02-28", 2990}, {"rr-009", "2026-03-31", 2990}, {"rr-009", "2026-04-30", 2990}}
	cal                                                          = map[string]string{} // 到期中心：finance|rule|reminder → due_at
	pair                                                         = map[string]int{}    // (rule_id, due_date) 唯一索引的内存形态
	perRule                                                      = map[string]int{}    // 规则 → 已入账期数
	amounts                                                      = map[int64]int{}     // 金额 → 笔数（改额不回改历史的证据）
	manual                                                       = map[string]bool{}   // 手动缴过的期（走 client_request_id 通道）
	pass                                                         = map[bool]string{true: "PASS", false: "FAIL"}
	notifs, firedCnt, ghostCnt, dupCnt, posted, active, deletedN int
	clk                                                          = D(2026, 3, 31) // 固定时钟：两次运行输出逐字一致
