func stamp() string                { clk = clk.Add(7 * time.Minute); return clk.Format("2006-01-02T15:04:05Z07:00") }
func book(t Txn)                   { pair[t.RuleID+"|"+t.DueDate]++; perRule[t.RuleID]++; amounts[t.Amount]++ }
func insert(r *Rule, due string)   { t := Txn{r.ID, due, r.Amount}; txns = append(txns, t); book(t) }
func ck(name, got string, ok bool) { fmt.Printf("  %s  %s\n      └─ %s\n", pass[ok], name, got) }

// crid：自动入账的 client_request_id 由 (rule_id, due_date) 推导，挡系统重复入账；
// 手动缴的 crid 由前端生成，挡用户重复提交——分工不同，不能互相替代。
func crid(id, due string) string { return "recurring:" + id + ":" + due }

// register：同三元组 (finance, rule_id, reminder) 走 upsert，绝不追加第二条条目。
func register(r *Rule) {
	cal[key(r.ID)] = ds(r.NextAt)
	fmt.Printf("    finance.due.registered business_id=%s:%s due_at=%s（三元组 upsert，非追加）\n", r.ID, ds(r.NextAt), ds(r.NextAt))
}

// revoke：calendar 消费 revoked 后删自己名下条目。天然幂等——重放只报「无事发生」。
func revoke(id, reason string) {
	if _, ok := cal[key(id)]; !ok {
		fmt.Printf("    finance.due.revoked(%s) 重放：条目 %s 已不存在 → 幂等吞掉，0 row，不报错\n", reason, key(id))
		return
	}
	b, _ := json.MarshalIndent(map[string]string{"event": "finance.due.revoked", "source_system": "finance", "source_id": id, "family_id": "fam-001", "kind": "reminder", "reason": reason, "revoke_at": stamp()}, "    ", "  ")
	fmt.Println("    " + string(b))
