	fmt.Printf("    calendar 消费 revoked：DELETE calendar_item WHERE (source_system,source_id,kind)=('finance','%s','reminder') → 1 row\n", id)
}

// post：finance 消费一条 calendar.reminder.fired（总线重放就直接再调一次）。
func post(r *Rule, due string) {
	if !r.IsActive {
		ghostCnt++
		fmt.Printf("    入账拒绝（is_active=FALSE / deleted_at IS NOT NULL）+ 提醒已下发 = 幽灵 %d 号\n", ghostCnt)
		return
	}
	if pair[r.ID+"|"+due] > 0 {
		dupCnt++
		fmt.Printf("    DUP：(rule_id,due_date)=(%s,%s) 命中唯一索引（第 %d 次重放）→ 0 笔新增\n", r.ID, due, dupCnt)
		return
	}
	insert(r, due)
	posted++
	v := r.Version
	r.NextAt, r.Version = nextMonthly(r.Anchor, r.NextAt), v+1
	fmt.Printf("    POSTED：INSERT finance_txn(%s,%s,amount_cents=%d,client_request_id=%s)｜UPDATE next_at='%s' WHERE version=%d → 1 row\n", r.ID, due, r.Amount, crid(r.ID, due), ds(r.NextAt), v)
	register(r)
}

// tick：到期中心到点。只遍历自己的表——绝不 SELECT finance_recurring_rule。
func tick(due string) {
	for _, r := range rules {
		if cal[key(r.ID)] == due {
			firedCnt++
			notifs++
			fmt.Printf("  %s 命中 %s → calendar.reminder.fired（event_id=%s｜homeos 只下发、不反查）\n", due, key(r.ID), stamp())
			post(r, due)
		}
	}
}

// nextMonthly：从锚点按绝对月序重算（d08 教训：链式 +1 月会丢锚点），短月顺延。
func nextMonthly(anchor, after time.Time) time.Time {
	ai := anchor.Year()*12 + int(anchor.Month()) - 1
	for k := 0; k < 26; k++ {
		y, m := (ai+k)/12, (ai+k)%12+1
		if t := D(y, m, min(anchor.Day(), D(y, m+1, 0).Day())); t.After(after) {
			return t
		}
	}
	panic("未收敛")
}

