// =====================================================================
// W46 d13：时间窗五档的桶定义与桶键编码 —— 先有「档」，才有报表。
//
// 报表页看起来只要「看哪一段时间」，最省事的写法是让前端传 from/to。
// 第 1 节真跑这个写法：同一批 5 笔流水，三种合理的拼法给出三种合计，
// 9-30 那天的钱一次被整日漏掉、一次被相邻两窗各算一遍。边界语义的
// 裁决权一旦交给调用方，就不存在「唯一正确的一段窗口」了。
//
// 今天把五档的桶键编码、桶起点、排他终点写死成服务端唯一的三个函数，
// 并把 prev/next 立成 W47 能直接复用的契约（环比=相邻桶、累计=前缀和）。
//
// 跑法：cd homecube/server && go run ./lab/s11/d13
// =====================================================================

package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"
	_ "time/tzdata" // 打包时区库：家庭时区（PRD 3.4.8）可以是任意 IANA 名
)

type Kind string

const (
	KDay     Kind = "day"
	KWeek    Kind = "week"
	KMonth   Kind = "month"
	KQuarter Kind = "quarter"
	KYear    Kind = "year"
)

var allKinds = []Kind{KDay, KWeek, KMonth, KQuarter, KYear}

func mustLoad(name string) *time.Location {
	l, err := time.LoadLocation(name)
	if err != nil {
		panic(err)
	}
	return l
}

var famLoc = mustLoad("Asia/Shanghai") // 时间窗一律按家庭时区算（PRD 4.5.3）

func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }

// ---- 契约三函数：桶起点 / 排他桶终点 / 桶键。全项目只有这一处定义 ----

func bucketStart(k Kind, t time.Time) time.Time {
	l := t.In(famLoc)
	switch k { // 周一起点与 Postgres date_trunc('week') 同口径；季度是自然季（1/4/7/10 月），不是滚动 90 天
	case KDay:
		return day0(l.Year(), int(l.Month()), l.Day())
	case KWeek:
		d := day0(l.Year(), int(l.Month()), l.Day())
		return d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7))
	case KMonth:
		return day0(l.Year(), int(l.Month()), 1)
	case KQuarter:
		return day0(l.Year(), ((int(l.Month())-1)/3)*3+1, 1)
	}
	return day0(l.Year(), 1, 1)
}

func bucketEnd(k Kind, t time.Time) time.Time { // 排他：查询条件永远是 occurred_at < end
	s := bucketStart(k, t)
	if k == KDay {
		return s.AddDate(0, 0, 1)
	}
	if k == KWeek {
		return s.AddDate(0, 0, 7)
	}
	if k == KMonth {
		return s.AddDate(0, 1, 0)
	}
	if k == KQuarter {
		return s.AddDate(0, 3, 0)
	}
	return s.AddDate(1, 0, 0)
}

func bucketKey(k Kind, t time.Time) string {
	l := t.In(famLoc)
	switch k { // 五档五种编码，全项目只在这里产出
	case KDay:
		return fmt.Sprintf("%04d-%02d-%02d", l.Year(), int(l.Month()), l.Day())
	case KWeek: // ISO-8601：周一起点、含 1 月 4 日的那周是 W01，年号可跨年
		y, w := l.ISOWeek()
		return fmt.Sprintf("%04d-W%02d", y, w)
	case KMonth:
		return fmt.Sprintf("%04d-%02d", l.Year(), int(l.Month()))
	case KQuarter:
		return fmt.Sprintf("%04d-Q%d", l.Year(), (int(l.Month())-1)/3+1)
	}
	return fmt.Sprintf("%04d", l.Year())
}

func isoWeekStart(y, w int) time.Time {
	jan4 := day0(y, 1, 4) // ISO 规则：1 月 4 日永远落在第 1 周
	return jan4.AddDate(0, 0, -((int(jan4.Weekday())+6)%7)+7*(w-1))
}

func digits(s string) bool {
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return s != ""
}

// parseKey 把对外编码解析成桶起点；解析不出来就是 error，绝不回落默认档。
// 最后那道 canonical 检查（bucketKey(start) 必须逐字等于入参）负责挡掉
// 「形状对但不是真实桶」：2025-W53、2026-09-31、2026-Q0、2026-W54。
func parseKey(k Kind, s string) (time.Time, error) {
	shape := map[Kind]string{KDay: "YYYY-MM-DD", KWeek: "YYYY-Wnn", KMonth: "YYYY-MM",
		KQuarter: "YYYY-Qn（n∈1..4）", KYear: "YYYY"}[k]
	if s == "" || s != strings.TrimSpace(s) {
		return time.Time{}, fmt.Errorf("period 为空或带空白：%s 必须显式传，服务端不猜当前窗", shape)
	}
	var start time.Time
	switch k {
	case KDay, KMonth:
		layout := "2006-01-02"
		if k == KMonth {
			layout = "2006-01"
		}
		t, err := time.ParseInLocation(layout, s, famLoc)
		if err != nil {
			return time.Time{}, fmt.Errorf("%q 不符合 %s", s, shape)
		}
		start = t
	case KWeek:
		if len(s) != 8 || s[4] != '-' || s[5] != 'W' || !digits(s[:4]) || !digits(s[6:]) {
			return time.Time{}, fmt.Errorf("%q 不符合 %s（形如 2026-W09）", s, shape)
		}
		y, _ := strconv.Atoi(s[:4])
		w, _ := strconv.Atoi(s[6:])
		if w < 1 || w > 53 {
			return time.Time{}, fmt.Errorf("%q 的周号 %d 越界（合法 01..53）", s, w)
		}
		start = isoWeekStart(y, w)
	case KQuarter:
		if len(s) != 7 || s[4] != '-' || s[5] != 'Q' || !digits(s[:4]) {
			return time.Time{}, fmt.Errorf("%q 不符合 %s（形如 2026-Q3）", s, shape)
		}
		y, _ := strconv.Atoi(s[:4])
		n := int(s[6] - '0')
		if n < 1 || n > 4 {
			return time.Time{}, fmt.Errorf("%q 的季号 %d 越界（合法 1..4）", s, n)
		}
		start = day0(y, (n-1)*3+1, 1)
	default:
		if len(s) != 4 || !digits(s) {
			return time.Time{}, fmt.Errorf("%q 不符合 %s", s, shape)
		}
		y, _ := strconv.Atoi(s)
		start = day0(y, 1, 1)
	}
	if got := bucketKey(k, start); got != s {
		return time.Time{}, fmt.Errorf("%q 不是规范编码：该桶的真实键是 %q", s, got)
	}
	return start, nil
}

// shiftKey：环比与累计的唯一位移函数（back=true 取上一桶，false 取下一桶）。
func shiftKey(k Kind, s string, back bool) (string, error) {
	start, err := parseKey(k, s)
	if err != nil {
		return "", err
	}
	if back {
		return bucketKey(k, start.Add(-time.Nanosecond)), nil // 上一桶内的最后一个瞬间
	}
	return bucketKey(k, bucketEnd(k, start)), nil
}

// enumerate：一个窗 → 一串桶键（含零值桶，d17 用它当期望桶数）。
// 步进走 bucketEnd，绝不用 Add(24h)：有夏令时的时区里那天不足 24 小时（d16）。
func enumerate(k Kind, from, to time.Time) []string {
	var out []string
	for cur := bucketStart(k, from); cur.Before(to); cur = bucketEnd(k, cur) {
		out = append(out, bucketKey(k, cur))
	}
	return out
}

func contiguous(k Kind, bs []string) bool { // W47 的相邻桶断言：next(i)==i+1 且 prev(i+1)==i
	for i := 0; i+1 < len(bs); i++ {
		n, e1 := shiftKey(k, bs[i], false)
		p, e2 := shiftKey(k, bs[i+1], true)
		if e1 != nil || e2 != nil || n != bs[i+1] || p != bs[i] {
			return false
		}
	}
	return true
}

func money(c int64) string { // 分 → 元.角分，纯整数格式化：聚合链路上不出现浮点
	neg := ""
	if c < 0 {
		neg, c = "-", -c
	}
	return fmt.Sprintf("%s%d.%02d", neg, c/100, c%100)
}

func signed(c int64) string {
	if c >= 0 {
		return "+" + money(c)
	}
	return money(c)
}

func hdr(t string) { fmt.Printf("\n===== %s =====\n", t) }

type txn struct {
	at    time.Time
	cents int64
}

func sumIn(rows []txn, from, to time.Time, closed bool) (int64, int) {
	var s int64
	var n int
	for _, r := range rows {
		if r.at.Before(from) {
			continue
		}
		if (closed && !r.at.After(to)) || (!closed && r.at.Before(to)) {
			s, n = s+r.cents, n+1
		}
	}
	return s, n
}

func main() {
	rows := []txn{
		{day0(2026, 9, 1), 10000},
		{day0(2026, 9, 15).Add(9*time.Hour + 30*time.Minute), 25000},
		{day0(2026, 9, 30).Add(14*time.Hour + 20*time.Minute), 8800},
		{day0(2026, 9, 30).AddDate(0, 0, 1).Add(-time.Millisecond), 1200},
		{day0(2026, 10, 1), 33000},
	}
	var all int64
	for _, r := range rows {
		all += r.cents
	}

	hdr("1. 为什么要「档」：前端传 from/to，同一批流水跑出三种合计")
	fmt.Printf("  %d 笔流水，真实总额 %s 元。以下三种都是调用方能合理写出来的区间：\n", len(rows), money(all))
	a := day0(2026, 9, 1)
	lastOct := day0(2026, 10, 31).Add(23*time.Hour + 59*time.Minute + 59*time.Second + 999*time.Millisecond)
	cases := []struct {
		name   string
		f, t   time.Time
