type Kind string

const (
	KDay     Kind = "day"
	KWeek    Kind = "week"
	KMonth   Kind = "month"
	KQuarter Kind = "quarter"
	KYear    Kind = "year"
)

var allKinds = []Kind{KDay, KWeek, KMonth, KQuarter, KYear}

const famTZ = "Asia/Shanghai" // 家庭时区：来自 homeos 的家庭设置，不是请求参数

var famLoc = mustLoad(famTZ)

func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err)
	}
	return l
}

func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }

func bucketStart(k Kind, t time.Time) time.Time {
	l := t.In(famLoc)
	switch k {
	case KDay:
		return day0(l.Year(), int(l.Month()), l.Day())
	case KWeek:
		d := day0(l.Year(), int(l.Month()), l.Day())
		return d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7))
	case KMonth:
		return day0(l.Year(), int(l.Month()), 1)
	case KQuarter:
		return day0(l.Year(), ((int(l.Month())-1)/3)*3+1, 1)
	}
	return day0(l.Year(), 1, 1)
}

func bucketEnd(k Kind, t time.Time) time.Time {
	s := bucketStart(k, t)
	if k == KDay {
		return s.AddDate(0, 0, 1)
	}
	if k == KWeek {
		return s.AddDate(0, 0, 7)
	}
	if k == KMonth {
		return s.AddDate(0, 1, 0)
	}
	if k == KQuarter {
		return s.AddDate(0, 3, 0)
	}
	return s.AddDate(1, 0, 0)
}

func bucketKey(k Kind, t time.Time) string {
	l := t.In(famLoc)
	switch k {
	case KDay:
		return fmt.Sprintf("%04d-%02d-%02d", l.Year(), int(l.Month()), l.Day())
	case KWeek:
		y, w := l.ISOWeek()
		return fmt.Sprintf("%04d-W%02d", y, w)
	case KMonth:
		return fmt.Sprintf("%04d-%02d", l.Year(), int(l.Month()))
	case KQuarter:
		return fmt.Sprintf("%04d-Q%d", l.Year(), (int(l.Month())-1)/3+1)
	}
	return fmt.Sprintf("%04d", l.Year())
}

type span struct {
	key      string
	from, to time.Time
}

func spans(k Kind, f, t time.Time) []span {
	var out []span
	for cur := bucketStart(k, f); cur.Before(t); cur = bucketEnd(k, cur) {
		out = append(out, span{bucketKey(k, cur), cur, bucketEnd(k, cur)})
	}
	return out
}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

func money(c int64) string { // 纯整数格式化：聚合链路上不出现浮点
	neg := ""
	if c < 0 {
		neg, c = "-", -c
	}
	return fmt.Sprintf("%s%d.%02d", neg, c/100, c%100)
}

// wrap：rune 安全的按词折行。DryRun 出的 SQL 是一整行，直出会把卡片 expect
// 撑成不可读的一坨；折行只做显示，不改变 SQL 本身。
func wrap(s string, w int) string {
	var b strings.Builder
	for _, line := range strings.Split(strings.TrimRight(s, "\n"), "\n") {
		rs := []rune(line)
		lead := len(rs) - len(strings.TrimLeft(string(rs), " "))
		for len(rs) > w {
			cut := w
			for cut > lead && rs[cut] != ' ' {
				cut--
			}
			if cut <= lead {
				cut = w
			}
			b.WriteString(string(rs[:cut]) + "\n" + strings.Repeat(" ", lead+2))
			rs = []rune(strings.TrimLeft(string(rs[cut:]), " "))
		}
		b.WriteString(string(rs) + "\n")
	}
	return strings.TrimRight(b.String(), "\n")
}

