	return gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
}

type Txn struct {
	ID          string
	FamilyID    string
	Type        string
	AmountCents int64
	OccurredAt  time.Time
}

func (Txn) TableName() string { return "finance_transaction" }

// 桶键表达式：occurred_at 先转家庭时区，再 date_trunc / to_char。
func keyExpr(k Kind) string {
	switch k {
	case KDay:
		return "to_char(occurred_at AT TIME ZONE ?, 'YYYY-MM-DD')"
	case KWeek:
		return `to_char(date_trunc('week', occurred_at AT TIME ZONE ?), 'IYYY-"W"IW')`
	case KMonth:
		return "to_char(occurred_at AT TIME ZONE ?, 'YYYY-MM')"
	case KQuarter:
		return `to_char(date_trunc('quarter', occurred_at AT TIME ZONE ?), 'YYYY-"Q"Q')`
	}
	return `to_char(date_trunc('year', occurred_at AT TIME ZONE ?), 'YYYY')`
}

func aggSQL(db *gorm.DB, k Kind, fam string, from, to time.Time) string {
	sel := fmt.Sprintf("%s AS bucket_key, "+
		"COALESCE(SUM(amount_cents) FILTER (WHERE type = 'expense'), 0) AS expense_cents, "+
		"COALESCE(SUM(amount_cents) FILTER (WHERE type = 'income'), 0) AS income_cents, "+
		"COUNT(*) AS txn_count", keyExpr(k))
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).
			Select(sel, famTZ).
			Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?",
				fam, from.Format(time.RFC3339Nano), to.Format(time.RFC3339Nano)).
			Group("bucket_key").
			Order("bucket_key").
			Find(&[]map[string]any{})
	})
}

func aggSQLNoFam(db *gorm.DB, k Kind, from, to time.Time) string {
	sel := fmt.Sprintf("%s AS bucket_key, SUM(amount_cents) AS total_cents", keyExpr(k))
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).
			Select(sel, famTZ).
			Where("deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?",
				from.Format(time.RFC3339Nano), to.Format(time.RFC3339Nano)).
			Group("bucket_key").Find(&[]map[string]any{})
	})
}

// 反面写法：把 period 编码直接当成等值条件（表达式套在列上，索引失效）。
func aggSQLByKeyEq(db *gorm.DB, k Kind, key string) string {
	sel := fmt.Sprintf("SUM(amount_cents) AS total_cents, COUNT(*) AS txn_count, MAX(occurred_at) AS last_at, MIN(occurred_at) AS first_at, %s AS bucket_key", keyExpr(k))
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).
			Select(sel, famTZ).
			Where("family_id = ? AND deleted_at IS NULL AND "+keyExpr(k)+" = ?", "fam-A", famTZ, key).
			Find(&[]map[string]any{})
	})
}

