// =====================================================================
// W46 d15：quarter / year 是月桶的合成 —— 两条路径逐桶差值必须是 0。
//
// S11 判据 1 的前半句：「季/年报表 = 月桶之和」。今天用同一批流水跑两条路：
// A 路径先聚月桶、再按桶键上卷；B 路径直接按季/年聚合。逐桶比对，差值全部
// 为 0 才算这条判据成立。顺手跑掉两个真实错觉：quarter 写成「滚动 90 天」、
// 金额从分换成元用 float64 累加 —— 两者都会让对账不平，且现场极难发现。
//
// 同时把 ParentBucket（唯一的上卷 API）定下来：W47 的环比走同族相邻桶，
// 累计余额走同族前缀和，跨族汇总只能走这里。
//
// 跑法：cd homecube/server && go run ./lab/s11/d15
// =====================================================================

package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"
	_ "time/tzdata"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	gormlogger "gorm.io/gorm/logger"
)

type Kind string

const (
	KDay     Kind = "day"
	KWeek    Kind = "week"
	KMonth   Kind = "month"
	KQuarter Kind = "quarter"
	KYear    Kind = "year"
)

var allKinds = []Kind{KDay, KWeek, KMonth, KQuarter, KYear}

// rank 只允许从低阶往高阶上卷（day=0 … year=4），反向是下钻，不归本 API 管。
var rank = map[Kind]int{KDay: 0, KWeek: 1, KMonth: 2, KQuarter: 3, KYear: 4}

const famTZ = "Asia/Shanghai"

var famLoc = mustLoad(famTZ)

func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err)
	}
	return l
}

func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }

func bucketStart(k Kind, t time.Time) time.Time {
	l := t.In(famLoc)
	switch k {
	case KDay:
		return day0(l.Year(), int(l.Month()), l.Day())
	case KWeek:
		d := day0(l.Year(), int(l.Month()), l.Day())
		return d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7))
	case KMonth:
		return day0(l.Year(), int(l.Month()), 1)
	case KQuarter:
		return day0(l.Year(), ((int(l.Month())-1)/3)*3+1, 1)
	}
	return day0(l.Year(), 1, 1)
}

func bucketEnd(k Kind, t time.Time) time.Time {
	s := bucketStart(k, t)
	switch k {
	case KDay:
		return s.AddDate(0, 0, 1)
	case KWeek:
		return s.AddDate(0, 0, 7)
	case KMonth:
		return s.AddDate(0, 1, 0)
	case KQuarter:
		return s.AddDate(0, 3, 0)
	}
	return s.AddDate(1, 0, 0)
}

func bucketKey(k Kind, t time.Time) string {
	l := t.In(famLoc)
	switch k {
	case KDay:
		return fmt.Sprintf("%04d-%02d-%02d", l.Year(), int(l.Month()), l.Day())
	case KWeek:
		y, w := l.ISOWeek()
		return fmt.Sprintf("%04d-W%02d", y, w)
	case KMonth:
		return fmt.Sprintf("%04d-%02d", l.Year(), int(l.Month()))
	case KQuarter:
		return fmt.Sprintf("%04d-Q%d", l.Year(), (int(l.Month())-1)/3+1)
	}
	return fmt.Sprintf("%04d", l.Year())
}

// parseKey：桶键 → 桶起点（半开区间的左端）。严格结构 + 规范往返，非法即 error。
func parseKey(k Kind, s string) (time.Time, error) {
	var t time.Time
	switch k {
	case KDay:
		if len(s) != 10 || s[4] != '-' || s[7] != '-' {
			return time.Time{}, fmt.Errorf("%s 键 %q 必须是 YYYY-MM-DD", k, s)
		}
		y, e1 := strconv.Atoi(s[0:4])
		m, e2 := strconv.Atoi(s[5:7])
		d, e3 := strconv.Atoi(s[8:10])
		if e1 != nil || e2 != nil || e3 != nil || m < 1 || m > 12 || d < 1 || d > 31 {
			return time.Time{}, fmt.Errorf("%s 键 %q 月日越界", k, s)
		}
		t = day0(y, m, d)
	case KWeek:
		if len(s) != 8 || s[4] != '-' || s[5] != 'W' {
			return time.Time{}, fmt.Errorf("%s 键 %q 必须是 YYYY-Wnn（周数两位）", k, s)
		}
		y, e1 := strconv.Atoi(s[0:4])
		w, e2 := strconv.Atoi(s[6:8])
		if e1 != nil || e2 != nil || w < 1 {
			return time.Time{}, fmt.Errorf("%s 键 %q 周数非法", k, s)
		}
		t = isoWeekStart(y, w)
	case KMonth:
		if len(s) != 7 || s[4] != '-' {
			return time.Time{}, fmt.Errorf("%s 键 %q 必须是 YYYY-MM", k, s)
		}
		y, e1 := strconv.Atoi(s[0:4])
		m, e2 := strconv.Atoi(s[5:7])
		if e1 != nil || e2 != nil || m < 1 || m > 12 {
			return time.Time{}, fmt.Errorf("%s 键 %q 月份越界", k, s)
		}
		t = day0(y, m, 1)
	case KQuarter:
		if len(s) != 7 || s[4] != '-' || s[5] != 'Q' {
			return time.Time{}, fmt.Errorf("%s 键 %q 必须是 YYYY-Qn", k, s)
		}
		y, e1 := strconv.Atoi(s[0:4])
		q, e2 := strconv.Atoi(s[6:7])
		if e1 != nil || e2 != nil || q < 1 || q > 4 {
			return time.Time{}, fmt.Errorf("%s 键 %q 季号越界", k, s)
		}
		t = day0(y, (q-1)*3+1, 1)
	default:
		if len(s) != 4 {
			return time.Time{}, fmt.Errorf("%s 键 %q 必须是 YYYY", k, s)
		}
		y, e := strconv.Atoi(s)
		if e != nil {
			return time.Time{}, fmt.Errorf("%s 键 %q 不是年份", k, s)
		}
		t = day0(y, 1, 1)
	}
	if got := bucketKey(k, t); got != s { // 规范往返：2025-W53 会被打回 2026-W01
		return time.Time{}, fmt.Errorf("非规范 %s 键 %q，规范形式是 %q", k, s, got)
	}
	return t, nil
}

// isoWeekStart：ISO 8601 第 1 周 = 含该年 1 月 4 日的那一周，起点周一。
func isoWeekStart(y, w int) time.Time {
	jan4 := day0(y, 1, 4)
	mon1 := jan4.AddDate(0, 0, -((int(jan4.Weekday()) + 6) % 7))
	return mon1.AddDate(0, 0, 7*(w-1))
}

// ParentBucket：把低阶桶键归到高阶桶。规则只有一条 —— 取该桶 start 时刻所在的高阶桶。
// 这条规则必须唯一，否则 W47 的前缀和与环比会在跨年周上分叉。
func ParentBucket(k Kind, key string, to Kind) (string, error) {
	if rank[to] <= rank[k] {
		return "", fmt.Errorf("只允许从 %s 上卷到更高阶，%s→%s 非法", k, k, to)
	}
	start, err := parseKey(k, key)
	if err != nil {
		return "", err
	}
	return bucketKey(to, start), nil
}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

func money(c int64) string {
	neg := ""
	if c < 0 {
		neg, c = "-", -c
	}
	return fmt.Sprintf("%s%d.%02d", neg, c/100, c%100)
}

func signed(c int64) string {
	if c >= 0 {
		return "+" + money(c)
	}
	return money(c) // money 已经带负号
}

