func live(t txn) bool { return t.fam == "fam-A" && !t.soft }

// 路径 A：先聚月桶（服务端唯一的原子聚合单位），再把月键上卷到目标档。
func sumByCompose(to Kind) map[string]int64 {
	months := map[string]int64{}
	for _, t := range txns {
		if live(t) {
			months[bucketKey(KMonth, t.at)] += t.cents
		}
	}
	out := map[string]int64{}
	for mk, v := range months {
		pk, err := ParentBucket(KMonth, mk, to)
		if err != nil {
			panic(err)
		}
		out[pk] += v
	}
	return out
}

// 路径 B：流水直接按目标档聚合（等价于 date_trunc('quarter'/'year', occurred_at)）。
func sumDirect(to Kind) map[string]int64 {
	out := map[string]int64{}
	for _, t := range txns {
		if live(t) {
			out[bucketKey(to, t.at)] += t.cents
		}
	}
	return out
}

func keysOf(m map[string]int64) []string {
	var ks []string
	for k := range m {
		ks = append(ks, k)
	}
	for i := 1; i < len(ks); i++ {
		for j := i; j > 0 && ks[j] < ks[j-1]; j-- {
			ks[j], ks[j-1] = ks[j-1], ks[j]
		}
	}
	return ks
}

func compare(to Kind) (int, int, int64) {
	a, b := sumByCompose(to), sumDirect(to)
	keys := keysOf(b)
	var bad int
	for _, k := range keys {
		if a[k] != b[k] {
			bad++
		}
	}
	var tot int64
	for _, k := range keys {
		tot += b[k]
	}
	fmt.Printf("  %-7s %-10s %14s %14s %8s\n", to, "桶键", "A 月桶合成", "B 直接聚合", "差值")
	fmt.Println("  " + strings.Repeat("-", 56))
	for _, k := range keys {
		fmt.Printf("  %-7s %-10s %14s %14s %8d\n", "", k, money(a[k]), money(b[k]), a[k]-b[k])
	}
	verdict := "两路逐桶相等 → 季/年只是月桶的分组别名，不需要第二套口径"
	if bad > 0 {
		verdict = fmt.Sprintf("%d 个桶不一致 → 上卷规则与直接聚合分叉，W47 的前缀和立刻不可信", bad)
	}
	fmt.Printf("  %d 个桶，%d 个差值非 0：%s\n\n", len(keys), bad, verdict)
	return bad, len(keys), tot
}

