type Txn struct {
	ID          string
	FamilyID    string
	Type        string
	AmountCents int64
	OccurredAt  time.Time
}

func (Txn) TableName() string { return "finance_transaction" }

func aggSQL(db *gorm.DB, expr, fam string, from, to time.Time) string {
	sel := fmt.Sprintf("%s AS bucket_key, COALESCE(SUM(amount_cents), 0) AS total_cents, COUNT(*) AS txn_count", expr)
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).
			Select(sel, famTZ).
			Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?",
				fam, from.Format(time.RFC3339Nano), to.Format(time.RFC3339Nano)).
			Group("bucket_key").Order("bucket_key").Find(&[]map[string]any{})
	})
}

func wrap(s string, w int) string {
	var b strings.Builder
	for _, line := range strings.Split(strings.TrimRight(s, "\n"), "\n") {
		rs := []rune(line)
		lead := len(rs) - len(strings.TrimLeft(string(rs), " "))
		for len(rs) > w {
			cut := w
			for cut > lead && rs[cut] != ' ' {
				cut--
			}
			if cut <= lead {
				cut = w
			}
			b.WriteString(string(rs[:cut]) + "\n" + strings.Repeat(" ", lead+2))
			rs = []rune(strings.TrimLeft(string(rs[cut:]), " "))
		}
		b.WriteString(string(rs) + "\n")
	}
	return strings.TrimRight(b.String(), "\n")
}

