// W46 d16：边界日与周起点 —— 同一笔流水，换个约定就落进另一个桶。
//
// d13 定了编码、d14 让 SQL 成立、d15 证明季/年是月桶之和。今天处理「边界归谁」：
// 周起点是周一还是周日、月末 23:59:59.999 这一笔算哪个月、区间用半开还是闭、
// 跨时区家庭按谁的墙上时间切桶、夏令时月份怎么枚举。每一条都跑真实后果，
// 不是嘴上说说：错的那版会少算多少钱、重复算哪一笔，全部由程序自己算出来。
//
// 跑法：cd homecube/server && go run ./lab/s11/d16
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
	_ "time/tzdata"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	gormlogger "gorm.io/gorm/logger"
)

type Kind string

const (
	KDay     Kind = "day"
	KWeek    Kind = "week"
	KMonth   Kind = "month"
	KQuarter Kind = "quarter"
	KYear    Kind = "year"
)

var allKinds = []Kind{KDay, KWeek, KMonth, KQuarter, KYear}

const famTZ = "Asia/Shanghai" // 本家庭时区（来自 homeos 家庭设置）

var (
	famLoc = mustLoad(famTZ)
	laLoc  = mustLoad("America/Los_Angeles") // 第二家庭：跨时区 + 有夏令时
	utcLoc = time.UTC
)

func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err)
	}
	return l
}

func day0In(y, m, d int, loc *time.Location) time.Time {
	return time.Date(y, time.Month(m), d, 0, 0, 0, 0, loc)
}

func atIn(y, m, d, hh, mm int, loc *time.Location) time.Time {
	return time.Date(y, time.Month(m), d, hh, mm, 0, 0, loc)
}

func day0(y, m, d int) time.Time { return day0In(y, m, d, famLoc) }

func bucketStart(k Kind, t time.Time, loc *time.Location) time.Time {
	l := t.In(loc)
	switch k {
	case KDay:
		return day0In(l.Year(), int(l.Month()), l.Day(), loc)
	case KWeek:
		d := day0In(l.Year(), int(l.Month()), l.Day(), loc)
		return d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7)) // 周一：ISO 8601，与 Postgres date_trunc('week') 同口径
	case KMonth:
		return day0In(l.Year(), int(l.Month()), 1, loc)
	case KQuarter:
		return day0In(l.Year(), ((int(l.Month())-1)/3)*3+1, 1, loc)
	}
	return day0In(l.Year(), 1, 1, loc)
}

func bucketEnd(k Kind, t time.Time, loc *time.Location) time.Time {
	s := bucketStart(k, t, loc)
	switch k {
	case KDay:
		return s.AddDate(0, 0, 1)
	case KWeek:
		return s.AddDate(0, 0, 7)
	case KMonth:
		return s.AddDate(0, 1, 0)
	case KQuarter:
		return s.AddDate(0, 3, 0)
	}
	return s.AddDate(1, 0, 0)
}

func bucketKey(k Kind, t time.Time, loc *time.Location) string {
	l := t.In(loc)
	switch k {
	case KDay:
		return fmt.Sprintf("%04d-%02d-%02d", l.Year(), int(l.Month()), l.Day())
	case KWeek:
		y, w := l.ISOWeek()
		return fmt.Sprintf("%04d-W%02d", y, w)
	case KMonth:
		return fmt.Sprintf("%04d-%02d", l.Year(), int(l.Month()))
	case KQuarter:
		return fmt.Sprintf("%04d-Q%d", l.Year(), (int(l.Month())-1)/3+1)
	}
	return fmt.Sprintf("%04d", l.Year())
}

// weekStartDay：把「周起点」做成参数，只为跑反例。工程上这个值必须全项目唯一。
func weekStartDay(t time.Time, first time.Weekday, loc *time.Location) time.Time {
	l := t.In(loc)
	d := day0In(l.Year(), int(l.Month()), l.Day(), loc)
	return d.AddDate(0, 0, -(((int(d.Weekday()) - int(first)) + 7) % 7))
}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

func money(c int64) string {
	neg := ""
	if c < 0 {
		neg, c = "-", -c
	}
	return fmt.Sprintf("%s%d.%02d", neg, c/100, c%100)
}

func signed(c int64) string {
	if c >= 0 {
		return "+" + money(c)
	}
	return money(c)
}

func mark(ok bool) string {
	if ok {
		return "✅"
	}
	return "❌"
}

func wrap(s string, w int) string {
	var b strings.Builder
	for _, line := range strings.Split(strings.TrimRight(s, "\n"), "\n") {
		rs := []rune(line)
		lead := len(rs) - len(strings.TrimLeft(string(rs), " "))
		for len(rs) > w {
			cut := w
			for cut > lead && rs[cut] != ' ' {
				cut--
			}
			if cut <= lead {
				cut = w
			}
			b.WriteString(string(rs[:cut]) + "\n" + strings.Repeat(" ", lead+2))
			rs = []rune(strings.TrimLeft(string(rs[cut:]), " "))
		}
		b.WriteString(string(rs) + "\n")
	}
	return strings.TrimRight(b.String(), "\n")
}

func dryDB() (*gorm.DB, error) {
	return gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
}

