func (Txn) TableName() string { return "finance_transaction" }

// 周档聚合 SQL：expr 传入不同表达式 = 换周起点 / 换时区口径，其它子句一字不动。
// expr 里带 ? 才绑家庭时区参数；不带 ? 就是「忘了转时区」的那种写法。
func weekSQL(db *gorm.DB, expr, fam string, from, to time.Time) string {
	sel := fmt.Sprintf("%s AS bucket_key, COALESCE(SUM(amount_cents), 0) AS total_cents", expr)
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		q := tx.Model(&Txn{}).Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?",
			fam, from.Format(time.RFC3339Nano), to.Format(time.RFC3339Nano))
		if strings.Contains(expr, "?") {
			q = q.Select(sel, famTZ)
		} else {
			q = q.Select(sel)
		}
		return q.Group("bucket_key").Order("bucket_key").Find(&[]map[string]any{})
	})
}

// 区间比较符做成参数：跑「半开 vs 闭」的真实差别。
func rangeSQL(db *gorm.DB, fam string, from, to time.Time, closed bool) string {
	op := "occurred_at < ?"
	if closed {
		op = "occurred_at <= ?"
	}
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).
			Select("COALESCE(SUM(amount_cents), 0) AS total_cents").
			Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND "+op,
				fam, from.Format(time.RFC3339Nano), to.Format(time.RFC3339Nano)).
			Find(&[]map[string]any{})
	})
}

// ---- 样本流水：at 一律是绝对时刻（库里 TIMESTAMPTZ），展示时才转时区 ----

type txn struct {
	id    string
	cents int64
	at    time.Time
}

func utc(y, m, d, hh, mm, ss, ns int) time.Time {
	return time.Date(y, time.Month(m), d, hh, mm, ss, ns, utcLoc)
}

func sh(y, m, d, hh, mm, ss, ns int) time.Time {
	return time.Date(y, time.Month(m), d, hh, mm, ss, ns, famLoc)
}

func main() {
	// 边界日样本：8 月最后一纳秒 / 9 月第一秒 / 季末季初 / 年末年初（含 .999 精度笔）
	edge := []txn{
		{"e1", 120000, sh(2026, 8, 31, 23, 59, 59, 999000000)},
		{"e2", 250000, sh(2026, 9, 1, 0, 0, 0, 0)},
		{"e3", 330000, sh(2026, 6, 30, 23, 59, 59, 999000000)},
		{"e4", 440000, sh(2026, 7, 1, 0, 0, 0, 0)},
		{"e5", 550000, sh(2026, 12, 31, 23, 59, 59, 999000000)},
		{"e6", 660000, sh(2027, 1, 1, 0, 0, 0, 0)},
	}

	hdr("1. 边界归谁：半开区间 [start, end) 一行都不多、一行都不少")
	fmt.Printf("  %-4s %-27s %-11s %-11s %-12s %s\n", "笔", "家庭时区墙上时间", "month", "quarter", "year", "月末/年末那一纳秒")
	fmt.Println("  " + strings.Repeat("-", 100))
	for _, t := range edge {
		l := t.at.In(famLoc)
		flag := "非边界"
		if !bucketEnd(KMonth, t.at, famLoc).Add(-time.Nanosecond).Before(t.at) {
			flag = "本月最后一纳秒 → 归本月"
		}
		if t.at.Equal(bucketStart(KMonth, t.at, famLoc)) {
			flag = "本月第一秒 → 归本月（不是上月）"
		}
		fmt.Printf("  %-4s %-27s %-11s %-11s %-12s %s\n", t.id,
			l.Format("2006-01-02 15:04:05.000"), bucketKey(KMonth, t.at, famLoc),
			bucketKey(KQuarter, t.at, famLoc), bucketKey(KYear, t.at, famLoc), flag)
	}
	db, err := dryDB()
	if err != nil {
		panic(err)
	}
	augFrom, augTo, octTo := day0(2026, 8, 1), day0(2026, 9, 1), day0(2026, 10, 1)
	sum := func(from, to time.Time, closed bool) int64 {
		var s int64
		for _, t := range edge {
			if !t.at.Before(from) && (t.at.Before(to) || (closed && t.at.Equal(to))) {
				s += t.cents
			}
		}
		return s
	}
	halfAug, closedAug := sum(augFrom, augTo, false), sum(augFrom, augTo, true)
	halfSep, closedSep := sum(augTo, octTo, false), sum(augTo, octTo, true)
	winTotal := sum(augFrom, octTo, false)
	var boundary int64 // 正好坐在 9 月 1 日 00:00 的那一笔
	for _, t := range edge {
		if t.at.Equal(augTo) {
			boundary += t.cents
		}
	}
	fmt.Println("\n  8 月桶的右端写成半开还是闭区间，差别就在 e2（9 月第一秒）那一笔：")
	fmt.Printf("  ✅ [08-01, 09-01) → %s      ❌ [08-01, 09-01] → %s\n", money(halfAug), money(closedAug))
	fmt.Printf("  两桶求和：半开 %s + %s = %s｜闭 %s + %s = %s；窗口 [08-01, 10-01) 的真实总额 = %s\n",
		money(halfAug), money(halfSep), money(halfAug+halfSep),
		money(closedAug), money(closedSep), money(closedAug+closedSep), money(winTotal))
	fmt.Printf("  %s 半开时桶和 == 窗总额；闭区间多算 %s（就是坐在边界上的 e2）\n", mark(halfAug+halfSep == winTotal), money(closedAug+closedSep-winTotal))
	if boundary > 0 {
		fmt.Printf("  被重复计入的正是这一笔：%s @ %s\n", money(boundary), edge[1].at.In(famLoc).Format("2006-01-02 15:04:05.000"))
	}
	fmt.Println("  " + wrap(rangeSQL(db, "fam-A", augFrom, augTo, false), 92))
	fmt.Println("  " + wrap(rangeSQL(db, "fam-A", augFrom, augTo, true), 92))
	fmt.Println("  规则：区间恒半开 [start, end)；end 取下一桶的 start，绝不写 23:59:59。")

	hdr("2. 精度截断：把 end 写成 23:59:59 会吃掉最后一纳秒那一笔")
	var naive, exact int64
	endStr := "2026-12-31 23:59:59"
	endT, _ := time.ParseInLocation("2006-01-02 15:04:05", endStr, famLoc)
	for _, t := range edge {
		if bucketKey(KYear, t.at, famLoc) == "2026" {
			exact += t.cents
