			}
		}
	}
	fmt.Printf("  ❌ 窗写成 [%s, %s]（人手上界）→ 2026 年聚到 %s\n", day0(2026, 1, 1).Format("2006-01-02 15:04:05"), endStr, money(naive))
	fmt.Printf("  ✅ 窗写成 [2026-01-01, 2027-01-01) → 2026 年聚到 %s\n", money(exact))
	fmt.Printf("  少掉 %s：e5 发生在 12-31 23:59:59.999，比人手写的上界晚 999 毫秒。列是 TIMESTAMPTZ（微秒精度），\n    这 999 毫秒是真实存在的，不会因为你写成整秒而消失。\n", money(exact-naive))
	fmt.Println("  同源坑：occurred_at 若建成 date 或 timestamp(0)，入库那一刻就把 .999 抹了 —— 迁移 review 时看列类型，别看代码。")

	hdr("3. 周起点：周一（ISO）还是周日 —— 同一笔流水落在不同的周桶")
	fmt.Printf("  %-11s %-5s %-23s %-11s %-23s %-11s %s\n",
		"日期(家庭时区)", "星期", "周一制桶 [start,end)", "键", "周日制桶 [start,end)", "键(演示)", "同桶?")
	fmt.Println("  " + strings.Repeat("-", 112))
	var diffDays int
	for i := 0; i < 14; i++ {
		d := day0(2026, 8, 24).AddDate(0, 0, i)
		mS, mE := bucketStart(KWeek, d, famLoc), bucketEnd(KWeek, d, famLoc)
		sS := weekStartDay(d, time.Sunday, famLoc)
		sE := sS.AddDate(0, 0, 7)
		mK := bucketKey(KWeek, d, famLoc)
		sy, sw := sS.ISOWeek() // 周日制没有标准编码，这里借用起点日的 ISO 周号做演示
		sK := fmt.Sprintf("%04d-W%02d*", sy, sw)
		same := mS.Equal(sS) && mK == strings.TrimSuffix(sK, "*")
		if !same {
			diffDays++
		}
		fmt.Printf("  %-11s %-5s %-23s %-11s %-23s %-11s %s\n",
			d.Format("2006-01-02"), []string{"Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"}[d.Weekday()],
			mS.Format("01-02")+"~"+mE.AddDate(0, 0, -1).Format("01-02"), mK,
			sS.Format("01-02")+"~"+sE.AddDate(0, 0, -1).Format("01-02"), sK, mark(same))
	}
	fmt.Printf("  14 天里 %d 天在两套约定下不同桶：周一制与周日制整组错开一天，七天全都被换过一次桶。\n", diffDays)
	wkTxns := []txn{
		{"w1", 110000, sh(2026, 8, 30, 12, 0, 0, 0)}, // 周日
		{"w2", 220000, sh(2026, 8, 31, 12, 0, 0, 0)}, // 周一
		{"w3", 330000, sh(2026, 9, 5, 12, 0, 0, 0)},  // 周六
		{"w4", 440000, sh(2026, 9, 6, 12, 0, 0, 0)},  // 周日
	}
	type conv struct {
		name  string
		order []string
		sums  map[string]int64
	}
	var convs []conv
	for _, first := range []time.Weekday{time.Monday, time.Sunday} {
		c := conv{sums: map[string]int64{}}
		if first == time.Monday {
			c.name = "周一制（ISO 8601，本项目采用）"
		} else {
			c.name = "周日制（美式日历，仅反例）    "
		}
		for _, t := range wkTxns {
			k := bucketKey(KWeek, t.at, famLoc)
			if first == time.Sunday {
				k = "周起 " + weekStartDay(t.at, first, famLoc).Format("01-02")
			}
			if _, ok := c.sums[k]; !ok {
				c.order = append(c.order, k)
			}
			c.sums[k] += t.cents
		}
		convs = append(convs, c)
	}
	fmt.Println("  金额层面的后果（同一批流水，只换周起点）：")
	fmt.Printf("  %-4s %-19s %-24s %-20s %s\n", "笔", "日期(家庭时区)", "周一制桶 → 键", "周日制桶 → 键", "同桶?")
	fmt.Println("  " + strings.Repeat("-", 96))
	for _, t := range wkTxns {
		mS := weekStartDay(t.at, time.Monday, famLoc)
		sS := weekStartDay(t.at, time.Sunday, famLoc)
		mk, sk := bucketKey(KWeek, t.at, famLoc), "周起 "+mS.Format("01-02")
		sk = "周起 " + sS.Format("01-02")
		fmt.Printf("  %-4s %-19s %-24s %-20s %s\n", t.id, t.at.In(famLoc).Format("2006-01-02 Mon"),
			mS.Format("01-02")+"~"+mS.AddDate(0, 0, 6).Format("01-02")+" "+mk,
			sS.Format("01-02")+"~"+sS.AddDate(0, 0, 6).Format("01-02")+" "+sk,
			mark(mS.Equal(sS)))
	}
	for _, c := range convs {
		var parts []string
		for _, k := range c.order {
			parts = append(parts, fmt.Sprintf("%s=%s", k, money(c.sums[k])))
		}
		fmt.Printf("    %s：%s\n", c.name, strings.Join(parts, "  "))
	}
	mo, so := convs[0], convs[1]
	mDiff := mo.sums[mo.order[1]] - mo.sums[mo.order[0]]
	sDiff := so.sums[so.order[1]] - so.sums[so.order[0]]
	fmt.Printf("  环比（后桶 - 前桶）：周一制 %s，周日制 %s —— 换约定不仅换数值，连正负号都能换。\n", signed(mDiff), signed(sDiff))
	fmt.Println("  ⇒ W47 的「相邻桶相减」必须两侧同用一套起点。前后端各算一次周起点，就是本周要消灭的写法。")
	fmt.Println("  定版：周起点 = 周一（time.ISOWeek / Postgres date_trunc('week')），键 = YYYY-Wnn，跨年用 ISO 年。")
	mon := weekSQL(db, `to_char(date_trunc('week', occurred_at AT TIME ZONE ?), 'IYYY-"W"IW')`, "fam-A", day0(2026, 8, 24), day0(2026, 9, 7))
	sun := weekSQL(db, `to_char(date_trunc('week', (occurred_at AT TIME ZONE ?) - interval '1 day') + interval '1 day', 'YYYY-"W"WW')`, "fam-A", day0(2026, 8, 24), day0(2026, 9, 7))
	fmt.Println("  -- 周一制（date_trunc('week') 本身就是周一）")
	fmt.Println("  " + wrap(mon, 92))
	fmt.Println("  -- 周日制（必须先把时间位移一天再截断，键也换成 %W 风格；这条一旦上线，全项目所有周档口径都得改）")
	fmt.Println("  " + wrap(sun, 92))

	hdr("4. 跨家庭时区：同一个绝对时刻，两个家庭看到不同的桶")
	multi := []txn{
		{"m1", 100000, utc(2026, 8, 31, 16, 30, 0, 0)}, // SH 9-01 00:30 / LA 8-31 09:30
		{"m2", 200000, utc(2026, 9, 1, 7, 0, 0, 0)},    // SH 9-01 15:00 / LA 9-01 00:00（正好踩在 LA 的日界上）
		{"m3", 300000, utc(2026, 10, 1, 0, 0, 0, 0)},   // SH 10-01（Q4）/ LA 9-30 17:00（Q3）
		{"m4", 400000, utc(2026, 12, 31, 16, 0, 0, 0)}, // SH 2027-01-01 / LA 2026-12-31
		{"m5", 500000, utc(2026, 6, 30, 15, 0, 0, 0)},  // SH 6-30 23:00（Q2 末）/ LA 6-30 08:00
		{"m6", 600000, utc(2026, 3, 8, 10, 0, 0, 0)},   // LA 夏令时切换日 03:00 PDT
	}
	fmt.Printf("  %-4s %-25s | %-25s | %-25s | %s\n", "笔", "UTC 绝对时刻", "家庭 A（Asia/Shanghai）", "家庭 B（America/Los_Angeles）", "day 档是否同桶")
	fmt.Println("  " + strings.Repeat("-", 118))
	var cross int
	for _, t := range multi {
		ka := fmt.Sprintf("%s %s %s", bucketKey(KDay, t.at, famLoc), bucketKey(KMonth, t.at, famLoc), bucketKey(KYear, t.at, famLoc))
		kb := fmt.Sprintf("%s %s %s", bucketKey(KDay, t.at, laLoc), bucketKey(KMonth, t.at, laLoc), bucketKey(KYear, t.at, laLoc))
		same := bucketKey(KDay, t.at, famLoc) == bucketKey(KDay, t.at, laLoc)
		if !same {
			cross++
		}
		fmt.Printf("  %-4s %-25s | %-25s | %-25s | %s\n", t.id, t.at.Format("2006-01-02 15:04:05Z"), ka, kb, mark(same))
	}
	fmt.Printf("  %d/%d 笔的日桶就不同，其中 m4 连年桶都不同（A 家 2027、B 家 2026）。\n", cross, len(multi))
	fmt.Println("  ⇒ 每个家庭只能看到按自己家庭时区切的桶：聚合入口必须把 family.timezone 传进去（d14 的 $tz），")
	fmt.Println("     绝不能「全家共用 UTC」或「按请求头猜时区」。")
	fmt.Println("  第三种错法（不转时区直接截断）：")
	fmt.Print("  " + wrap(weekSQL(db, `to_char(date_trunc('week', occurred_at), 'IYYY-"W"IW')`, "fam-A", day0(2026, 8, 24), day0(2026, 9, 7)), 92) + "\n")
	var utcMiss int
	for _, t := range multi {
		if bucketKey(KDay, t.at, utcLoc) != bucketKey(KDay, t.at, famLoc) {
			utcMiss++
		}
	}
	fmt.Printf("  这条 SQL 少了 AT TIME ZONE：本批样本里 %d 笔会被切到 UTC 的日/周桶，家庭 A 的报表凭空串桶。\n", utcMiss)

	hdr("5. 夏令时：枚举桶序列只能 AddDate，+24h 会造出重复桶")
	novStart := atIn(2026, 11, 1, 0, 0, laLoc) // 2026-11-01 02:00 LA 回拨：这天有 25 小时
	novEnd := atIn(2026, 12, 1, 0, 0, laLoc)
	byDate, byWall := map[string]int{}, map[string]int{}
	stepsDate, stepsWall := 0, 0
	for cur := novStart; cur.Before(novEnd); cur = cur.AddDate(0, 0, 1) {
		byDate[bucketKey(KDay, cur, laLoc)]++
		stepsDate++
	}
	for cur := novStart; cur.Before(novEnd); cur = cur.Add(24 * time.Hour) {
		byWall[bucketKey(KDay, cur, laLoc)]++
		stepsWall++
	}
	fmt.Printf("  AddDate(0,0,1)：游标 %d 步，日桶 %d 个，重复 %d 个\n", stepsDate, len(byDate), stepsDate-len(byDate))
	fmt.Printf("  Add(24h)      ：游标 %d 步，日桶 %d 个，重复 %d 个\n", stepsWall, len(byWall), stepsWall-len(byWall))
	fmt.Printf("  ❌ +24h 版本重复出现的日桶：%s\n", func() string {
		var dup []string
		for k, n := range byWall {
			if n > 1 {
				dup = append(dup, fmt.Sprintf("%s×%d", k, n))
			}
		}
		if len(dup) == 0 {
			return "（无）"
		}
		return strings.Join(dup, ", ")
	}())
	fmt.Printf("  游标实际走过的头四步（注意第 1、2 步同一天）：%s\n", func() string {
		var s []string
		cur := novStart
		for i := 0; i < 4; i++ {
			s = append(s, cur.In(laLoc).Format("2006-01-02 15:04 MST"))
			cur = cur.Add(24 * time.Hour)
		}
		return strings.Join(s, " → ")
	}())
	novTxns := []txn{
		{"n1", 480000, atIn(2026, 11, 1, 9, 0, laLoc)},
		{"n3", 260000, atIn(2026, 11, 15, 12, 0, laLoc)},
		{"n2", 1300000, atIn(2026, 11, 30, 9, 0, laLoc)},
	}
	var good, doubled int64
	for _, t := range novTxns {
		good += t.cents // 按笔聚：每笔只进一次
	}
	for cur := novStart; cur.Before(novEnd); cur = cur.Add(24 * time.Hour) { // 按游标逐桶累加
		k := bucketKey(KDay, cur, laLoc)
		for _, t := range novTxns {
			if bucketKey(KDay, t.at, laLoc) == k {
				doubled += t.cents
			}
		}
	}
	fmt.Printf("  现场代价：按 +24h 游标累加得到 %s，按笔聚得到 %s，多出的 %s 就是 %s 那笔被算了两次。\n",
