		{"窗口恒半开 [start, end)，end = 下一桶 start", "闭区间会让边界那一笔被相邻两桶各算一次（第 1 节：桶和比窗总额多出 " + money(boundary) + "）"},
		{"边界日写到纳秒：不手写 23:59:59，列类型 TIMESTAMPTZ", "月末 .999 那一笔真实存在，写成整秒就丢（第 2 节已量化）"},
		{"切桶前先 AT TIME ZONE 家庭时区；家庭时区来自会话，不来自请求参数", "同一绝对时刻在两个家庭属于不同桶，甚至不同年（第 4 节）"},
		{"桶枚举只走 AddDate，不走 +24h；小时档不写 for h:=0..23", "回拨月 +24h 会把 11-01 算两遍；拨快日的不存在小时被静默归一化（第 5 节）"},
	}
	for i, r := range rules {
		fmt.Printf("  %d. %s\n     依据：%s\n", i+1, r.rule, r.why)
	}
	fmt.Println("  谁拥有边界：bucketStart / bucketEnd / bucketKey / parseKey 只在 finance/internal/report 里有一份实现，")
	fmt.Println("  handler、前端、导出脚本一律调它。任何「我在本地再算一次边界」的代码都是本周要消灭的对象。")
	fmt.Println("\n=== W46 d16 到此结束 ===")
	fmt.Println("明天把两条红线跑穿：非法桶键必须 400（不许回落默认档）、0 值桶不许过滤。")
}

// =====================================================================
// W46 d17：两条红线跑穿 —— 非法桶键必须 400（不回落默认档）、0 值桶必须返回
// 这一天解决什么问题：① parse 失败就回落默认档是最省事的写法，用在时间窗上却是换了一道
// 题：要 2026-Q3、拿到 2026-09，两份聚合并不等值，界面却照发 200（第 2 节对拍）；② 只回
// 「有数的桶」：折线按下标贴 x 轴刻度，0 值期一缺席，后面每期整体前移（第 4 节把 2026-Q3
// 的 92 个日历格全打，错位量算成天数）；③ 五档口径逐字沿用 d13，流水沿用 d14（越权 fam-B、
// 软删、季外三行都在），本机没有 PG，聚合在内存表上真跑，SQL 见 d14 第 6 节。
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d17
// =====================================================================
package main

import (
	"encoding/json"
	"fmt"
	"net/url"
	"time"
	_ "time/tzdata"
)

type Kind string // 聚合五档：day / week / month / quarter / year
var (
	KDay, KWeek, KMonth, KQuarter, KYear = Kind("day"), Kind("week"), Kind("month"), Kind("quarter"), Kind("year")
	known                                = map[Kind]bool{KDay: true, KWeek: true, KMonth: true, KQuarter: true, KYear: true} // 白名单之外没有默认档
	layouts                              = map[Kind]string{KDay: "2006-01-02", KWeek: "2006-01-02", KMonth: "2006-01", KQuarter: "2006-01", KYear: "2006"}
	exKey                                = map[Kind]string{KDay: "2026-09-03", KWeek: "2026-W36", KMonth: "2026-09", KQuarter: "2026-Q3", KYear: "2026"}
	stepOf                               = map[Kind][3]int{KDay: {0, 0, 1}, KWeek: {0, 0, 7}, KMonth: {0, 1, 0}, KQuarter: {0, 3, 0}, KYear: {1, 0, 0}}
	mark                                 = map[bool]string{true: "✅", false: "❌"}
	yes                                  = map[bool]int{true: 1, false: 0}
	pr                                   = func(p string, rows [][]any) {
		for _, r := range rows {
			fmt.Printf(p, r...)
		}
	}
	endPeriod = 23*time.Hour + 59*time.Minute + 59*time.Second + 999*time.Millisecond // 期末最后一毫秒
	tz        = func() *time.Location {
		l, e := time.LoadLocation("Asia/Shanghai") // PRD 4.5.3：时间窗一律按家庭时区算；取不到就崩，绝不静默回落 UTC
		if e != nil {
			panic(e)
		}
		return l
	}()
	today = day0(2026, 9, 15).Add(10 * time.Hour) // 真环境 = time.Now()；这里钉死，输出可复算
	day0  = func(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, tz) }
	qv    = func(win, window, kind string) url.Values {
		return url.Values{"family_id": {"fam-A"}, "kind": {kind}, "win": {win}, "window": {window}}
	}
	money = func(c int64) string {
		a, s := map[bool]int64{true: -c, false: c}[c < 0], map[bool]string{true: "-", false: ""}[c < 0]
		return fmt.Sprintf("%s%d.%02d", s, a/100, a%100) // 分 → 元.角分：负号只由这一处前缀决定，链路里不出现浮点
	}
	bucketEnd = func(k Kind, t time.Time) time.Time {
		return bucketStart(k, t).AddDate(stepOf[k][0], stepOf[k][1], stepOf[k][2])
	} // 排他右端：查询永远 >= start AND < end
)

// ---- 桶口径逐字沿用 d13 定稿；d17 只在它上面加「拒绝」与「稠密」两层 ----
func monday(d time.Time) time.Time { return d.AddDate(0, 0, -(int(d.Weekday())+6)%7) } // 周一起点 = date_trunc('week')
func bucketStart(k Kind, t time.Time) time.Time { // 半开区间左端 [start, end)
	l := t.In(tz)
	d, y, mo := day0(l.Year(), int(l.Month()), l.Day()), l.Year(), int(l.Month())
	return map[Kind]time.Time{KDay: d, KWeek: monday(d), KMonth: day0(y, mo, 1), KQuarter: day0(y, (mo-1)/3*3+1, 1), KYear: day0(y, 1, 1)}[k] // 周一制；季首月 1/4/7/10
}
func bucketKey(k Kind, t time.Time) string { // 桶键契约：2026-09-03 / 2026-W36 / 2026-09 / 2026-Q3 / 2026
	s, th := bucketStart(k, t), bucketStart(k, t).AddDate(0, 0, 3) // ISO 周：星期四所在的年与年内日序决定周号
	return map[Kind]string{KDay: s.Format("2006-01-02"), KWeek: fmt.Sprintf("%d-W%02d", th.Year(), (th.YearDay()+6)/7), KMonth: s.Format("2006-01"), KQuarter: fmt.Sprintf("%d-Q%d", s.Year(), (int(s.Month())-1)/3+1), KYear: s.Format("2006")}[k]
}

// maxISOWeek：ISO 8601 里 12 月 28 日恒落在该 ISO 年的最后一周——取那一周的星期四、按年内日序算周号
// 就是这一年的周号上限（2025 → 52、2026 → 53）。越界判定要单独做：只靠 canonical 往返会把 2026-W54
// 归一化成 2027-W01 再说「键对不上」，讲不清是形状错还是这一年根本没有第 54 周。
func maxISOWeek(y int) int {
	th := monday(day0(y, 12, 28)).AddDate(0, 0, 3)
	return (th.YearDay() + 6) / 7
}

// parseKey：五档同一道门，三步全走完才允许返回起点——① 形状（长度 + 分隔符 + 分量逐位是数字）；
// ② 分量越界（月 01..12、季 1..4、ISO 周 01..maxISOWeek(年)、日按真实日历）；③ canonical 往返
// （bucketKey(还原起点) 必须逐字等于入参）。任何一步失败一律 error，由 handle 换成 400。
// 旧版在这里给 week/quarter 开了「长度对就提前 return 一个没校验的起点」的旁路：2026-Q0、2026-Q5、
// 2026-W54、2025-W53 四条非法编码被 time.Date 的日历归一化接走（2025-Q4 / 2027-Q1 / 2027-W01 /
// 2026-W01）、返回 200，本节断言① 只做到 8/12。旁路拆掉，四条一起走这道门 → 12/12。
func parseKey(k Kind, s string) (time.Time, error) {
	no := func(why string) (time.Time, error) { // 唯一的拒绝出口：信息里必须带合法形状与「不回落」
		return time.Time{}, fmt.Errorf("window=%q 非法：%s 档形如 %s（%s）；服务端不猜窗口、不回落默认档", s, k, exKey[k], why)
	}
	num := func(i, j int) (int, bool) { // 逐位查十进制数字：2026q3、2026-0g、2026-W0x 在这一层现形
		v := 0
		for _, c := range []byte(s[i:j]) {
			if c < '0' || c > '9' {
				return 0, false
			}
			v = v*10 + int(c-'0')
		}
		return v, true
	}
	if len(s) != len(exKey[k]) { // 形状真源就是 exKey：2026-09-03(10) / 2026-W36(8) / 2026-09(7) / 2026-Q3(7) / 2026(4)
		return no(fmt.Sprintf("长度应为 %d 个字符", len(exKey[k])))
	}
	y, okYear := num(0, 4)
	if !okYear {
		return no("前 4 位是年份数字")
	}
	if k != KYear && s[4] != '-' { // 年档只有 4 位，其余四档第 5 位必须是 -
		return no("第 5 位是 -")
	}
	var st time.Time
	switch k {
	case KDay: // 日档的两个分量先越界、再交给 time.ParseInLocation 按真实日历把关
		m, okM := num(5, 7)
		d, okD := num(8, 10)
		if s[7] != '-' || !okM || !okD || m < 1 || m > 12 || d < 1 || d > 31 {
			return no("第 8 位是 -，月 01..12、日 01..31")
		}
		if _, err := time.ParseInLocation(layouts[k], s, tz); err != nil { // 2026-09-31、2026-02-30 在这一步出局
			return no("这一天在日历上不存在")
		}
		st = day0(y, m, d)
	case KWeek: // 形状 2026-W36：第 6 位是大写 W，周号占第 7、8 位
		n, okN := num(6, 8)
		if s[5] != 'W' || !okN {
			return no("第 6 位是大写 W、周号 2 位数字")
		}
		if n < 1 || n > maxISOWeek(y) {
			return no(fmt.Sprintf("%d 年的 ISO 周号是 01..%02d", y, maxISOWeek(y)))
		}
		st = monday(day0(y, 1, 4)).AddDate(0, 0, 7*(n-1)) // ISO：1 月 4 日永远落在第 1 周
	case KMonth:
		m, okM := num(5, 7)
		if !okM || m < 1 || m > 12 {
			return no("月是 2 位数字且落在 01..12")
		}
		st = day0(y, m, 1)
	case KQuarter: // 形状 2026-Q3：第 6 位是大写 Q，季号占第 7 位
		n, okN := num(6, 7)
		if s[5] != 'Q' || !okN {
			return no("第 6 位是大写 Q、季号是数字")
		}
		if n < 1 || n > 4 {
			return no("一年只有四季：1..4")
		}
		st = day0(y, (n-1)*3+1, 1) // 季首月 1/4/7/10
	case KYear:
		st = day0(y, 1, 1)
	}
	if rt := bucketKey(k, st); rt != s { // ③ canonical 往返：非规范写法与任何日历归一化都卡在这里
		return no(fmt.Sprintf("这一期的真实键是 %q，与入参逐字不等", rt))
	}
	return st, nil
}

// ---- 内存表：逐字沿用 d14 那批 2026-Q3 流水，脏数据三种（跨家庭 / 软删 / 季外）----
type row struct {
	id, fam  string
	inc, exp int64 // income_cents / expense_cents：只有对应 type 的行非 0，等价 SQL 的 FILTER
	at       time.Time
	soft     bool // true = deleted_at 非空
}

var base = []row{{"t-01", "fam-A", 0, 120000, day0(2026, 7, 3).Add(9 * time.Hour), false}, {"t-02", "fam-A", 0, 45000, day0(2026, 7, 31).Add(endPeriod), false}, {"t-03", "fam-A", 860000, 0, day0(2026, 8, 1), false}, {"t-04", "fam-A", 0, 33000, day0(2026, 8, 19).Add(12 * time.Hour), true}, {"t-05", "fam-A", 0, 210000, day0(2026, 9, 9).Add(20 * time.Hour), false}, {"t-06", "fam-A", 0, 78000, day0(2026, 9, 30).Add(endPeriod), false}, {"t-07", "fam-B", 0, 999000, day0(2026, 8, 8).Add(8 * time.Hour), false}, {"t-08", "fam-A", 150000, 0, day0(2026, 10, 1), false}}

type bucket struct { // 字段形态 = d14 第 7 节响应体契约，d18 要把整份契约交给 W47
	Key          string `json:"key"`
	StartAt      string `json:"start_at"`
	EndAt        string `json:"end_at"`
	IncomeCents  int64  `json:"income_cents"`
	ExpenseCents int64  `json:"expense_cents"`
	NetCents     int64  `json:"net_cents"`
	TxnCount     int64  `json:"txn_count"`
}

// trend：唯一的出桶路径。先把整窗稠密枚举，再按条件累加；dense=false 就是崩法二。
func trend(k Kind, lo, hi time.Time, fam string, dense bool) []bucket {
	idx, out := map[string]int{}, []bucket{}
	for cur := bucketStart(k, lo); cur.Before(hi); cur = bucketEnd(k, cur) { // 稠密枚举：没数的期也占一格
		out = append(out, bucket{Key: bucketKey(k, cur), StartAt: cur.Format(time.RFC3339), EndAt: bucketEnd(k, cur).Format(time.RFC3339)})
		idx[bucketKey(k, cur)] = len(out) - 1
	}
	for _, r := range base {
		if r.soft || (fam != "-" && r.fam != fam) || r.at.Before(lo) || !r.at.Before(hi) {
			continue // deleted_at、family_id、半开区间：三个条件一个都不能少
		}
		b := &out[idx[bucketKey(k, r.at)]]
		b.IncomeCents, b.ExpenseCents, b.TxnCount = b.IncomeCents+r.inc, b.ExpenseCents+r.exp, b.TxnCount+1
		b.NetCents = b.IncomeCents - b.ExpenseCents // 整数分相减，净额可为负
	}
	keep := []bucket{}
	for _, b := range out {
		if dense || b.TxnCount > 0 {
			keep = append(keep, b) // ← 崩法二：0 值桶从这里消失
		}
	}
	return keep
}
func totals(bs []bucket) (int64, int64, int64) {
	var inc, exp, n int64
	for _, b := range bs {
		inc, exp, n = inc+b.IncomeCents, exp+b.ExpenseCents, n+b.TxnCount
	}
	return inc, exp, n
}

// handle：同一个接口装两种做法。strict=true 是 ✅ 红线版（解析失败即 400，信息里给合法
// 形状）；strict=false 是 ❌ 崩法版（悄悄回落本自然月，状态码照发 200）。
func handle(q url.Values, strict bool) (int, string) {
	k, winK := Kind(q.Get("kind")), Kind(q.Get("win"))
	if !known[k] || !known[winK] {
		return 400, fmt.Sprintf("win/kind 必须在聚合档位表内（收到 %q / %q），合法 kind：day / week / month / quarter / year", q.Get("win"), q.Get("kind"))
	}
	lo, err := parseKey(winK, q.Get("window"))
	if err != nil && strict {
		return 400, err.Error()
	}
	if err != nil {
		k, winK, lo = KMonth, KMonth, bucketStart(KMonth, today) // ❌ 事故现场：静默换窗
	}
	bs := trend(k, lo, bucketEnd(winK, lo), q.Get("family_id"), true)
	inc, exp, n := totals(bs)
	j, _ := json.Marshal(map[string]any{"bucket_count": len(bs), "buckets": bs, "degraded": err != nil, "expense_cents": exp, "family_timezone": tz.String(), "income_cents": inc, "kind": string(k), "returned_window": bucketKey(winK, lo), "txn_count": n, "window": q.Get("window")})
	return 200, string(j)
}

func main() {
	si, se, _ := totals(trend(KQuarter, day0(2026, 1, 1), bucketEnd(KYear, today), "-", false))
	fmt.Printf("\n===== 1. 场景：d14 那批 2026-Q3 流水（t-01..t-08），家庭时区 %s =====\n  全表 %d 笔：income %s 元、expense %s 元、净额 %s 元；其中 t-04 是软删行（%s 元）、t-07 属 fam-B（%s 元）、t-08 落在 Q4（%s 元），三笔都不该进 fam-A 的 Q3 桶\n  本机没有 HTTP 服务与库：请求用 url.Values 构造、聚合在内存表上真跑；「今天」钉在 %s\n", tz.String(), len(base), money(si), money(se), money(si-se), money(base[3].exp), money(base[6].exp), money(base[7].inc), today.Format("2006-01-02 15:04"))

	lo, _ := parseKey(KQuarter, "2026-Q3") // Q3 起点：后面几节都从它出发
	q := qv("quarter", "2026q3", "month")
	st1, b1 := handle(q, true)
	st2, b2 := handle(q, false)
	want, got := trend(KMonth, lo, bucketEnd(KQuarter, lo), "fam-A", true), trend(KMonth, bucketStart(KMonth, today), bucketEnd(KMonth, today), "fam-A", true)
	wi, we, wn := totals(want)
	gi, ge, gn := totals(got)
	fmt.Printf("\n===== 2. ❌ 崩法一：parse 失败静默回落 month —— 用户要看季度，拿到的却是本月 =====\n  GET /api/v1/reports/trend?%s\n  ✅ 严格版 → %d：%s\n  ❌ 回落版 → %d：%s\n  %-22s %-6s %-6s %-12s %-12s %s\n", q.Encode(), st1, b1, st2, b2, "这一份是", "桶数", "笔数", "income_cents", "expense_cents", "差额")
	pr("  %-22s %-6d %-6d %-12s %-12s %s\n", [][]any{{"用户以为在看 2026-Q3", len(want), wn, money(wi), money(we), "——"}, {"回落版实际给出 2026-09", len(got), gn, money(gi), money(ge), fmt.Sprintf("少 %d 桶 / %d 笔 / %s 元支出", len(want)-len(got), wn-gn, money(we-ge))}})
	fmt.Printf("  ★ 回落不是「降级显示」，是换了一道题：季度窗本该等于 %d 个月桶之和（d15），响应里却连另外两期都没有，而 %d 状态码把「你没拿到季度」这件事彻底埋掉——前端无从察觉，用户读的是另一道题的答案。\n", len(want), st2)

	bad := [][]string{{"quarter", "2026q3", "month"}, {"quarter", "2026-Q0", "month"}, {"quarter", "2026-Q5", "month"}, {"month", "2026-9", "day"}, {"month", "202609", "day"}, {"month", "", "day"}, {"month", "2026-09", "hour"}, {"month", "2026-09", ""}, {"week", "2026-W54", "day"}, {"week", "2025-W53", "day"}, {"day", "2026-09-31", "day"}, {"year", "1753843200000", "month"}}
	fmt.Printf("\n===== 3. ✅ 红线一：非法编码一律 400，不回落、不猜（d13 第 4 节那张名单逐条打到接口上）=====\n  %-3s %-42s %-5s %s\n", "#", "query", "状态", "错误信息（必须给出合法形状）")
	rej := 0
	for i, c := range bad {
		st, msg := handle(qv(c[0], c[1], c[2]), true)
		rej += yes[st == 400]
		fmt.Printf("  %-3d %-42s %-5d %s\n", i+1, qv(c[0], c[1], c[2]).Encode(), st, msg)
	}
	stG, msgG := handle(qv("quarter", "2026-Q3", "month"), true)
	fmt.Printf("  %s %d 条非法请求全部 400（%d/%d），对照合法编码 win=quarter&window=2026-Q3&kind=month → %d：严格版里根本没有回落分支，所以不可能「悄悄降级」\n", mark[rej == len(bad) && stG == 200], len(bad), rej, len(bad), stG)

	dense, filt := trend(KDay, lo, bucketEnd(KQuarter, lo), "fam-A", true), trend(KDay, lo, bucketEnd(KQuarter, lo), "fam-A", false)
	pad, pos := append(append([]bucket{}, filt...), make([]bucket, len(dense)-len(filt))...), map[string]int{}
	for i, b := range dense {
		pos[b.Key] = i
	}
	fmt.Printf("\n===== 4. ❌ 崩法二：把 0 值桶过滤掉 —— 折线 x 轴按下标整体错位 =====\n  窗 2026-Q3 / day 档：稠密出桶 %d 个，过滤后只剩 %d 个 —— 少掉的 %d 个正是「没花钱也没进账的那些天」\n  %-4s %-11s %-10s %-11s %-10s %s\n", len(dense), len(filt), len(dense)-len(filt), "下标", "x 轴刻度", "稠密 net", "过滤同下标", "过滤 net", "错位")
	for i, b := range dense {
		none := pad[i].Key == "" // 过滤版在这里根本没有点
		fmt.Printf("  %-4d %-11s %-10s %-11s %-10s %s\n", i, b.Key, money(b.NetCents), map[bool]string{true: "无值可画", false: pad[i].Key}[none], map[bool]string{true: "——", false: money(pad[i].NetCents)}[none], map[bool]string{true: "", false: map[bool]string{true: "对得上", false: fmt.Sprintf("★ 提前 %d 天画", pos[pad[i].Key]-i)}[pos[pad[i].Key] == i]}[none])
	}
