	for _, b := range want {
		fmt.Printf("    %-9s [%s ~ %s) income %9s ｜ expense %9s ｜ net %10s ｜ 笔数 %d %s\n", b.Key, b.StartAt[:10], b.EndAt[:10], money(b.IncomeCents), money(b.ExpenseCents), money(b.NetCents), b.TxnCount, map[bool]string{true: "← 空桶也带三个字段", false: ""}[b.TxnCount == 0])
	}
	qi, qe, qn := totals(trend(KQuarter, lo, bucketEnd(KQuarter, lo), "fam-A", true))
	_, ae, an := totals(trend(KQuarter, lo, bucketEnd(KQuarter, lo), "-", true))
