	fmt.Printf("\n===== 6. 两条红线的机器自检 + 交给 d18 =====\n")
	ok1, ok2, ok3, ok4, ok5, ok6 := rej == len(bad) && st1 == 400 && stG == 200, len(dense) == 92 && len(filt) == 5, pos[filt[1].Key] != 1, an == wn+1, wn == int64(len(base))-3, wi == qi && we == qe && wn == qn
	pr("  %s 断言 %s：%s\n     证据：%s\n", [][]any{{mark[ok1], "①", "非法编码返 400，无一条被静默降级", fmt.Sprintf("%d/%d 条 400，合法对照 %d；回落分支只存在于崩法版 handle(strict=false)", rej, len(bad), stG)}, {mark[ok2], "②", "空桶必须返回", fmt.Sprintf("day 档 2026-Q3 稠密出 %d 桶，其中 %d 个 txn_count=0 仍带 key/start_at/end_at", len(dense), len(dense)-len(filt))}, {mark[ok3], "③", "0 值桶不得改变下标", fmt.Sprintf("过滤版第 1 格 %s 在稠密序列里排第 %d，画在第 1 格就是前移 %d 天", filt[1].Key, pos[filt[1].Key], pos[filt[1].Key]-1)}, {mark[ok4], "④", "family_id 是硬条件", fmt.Sprintf("不带 family_id 时 Q3 有 %d 笔（混入 t-07 %s 元），带上只有 %d 笔", an, money(base[6].exp), wn)}, {mark[ok5], "⑤", "软删与季外不进桶", fmt.Sprintf("t-04 软删 %s 元、t-08 Q4 %s 元都不在这 %d 笔里", money(base[3].exp), money(base[7].inc), wn)}, {mark[ok6], "⑥", "聚合全程整数分", fmt.Sprintf("Σ月桶 expense %d 分 == 直取季窗 %d 分、income %d == %d，链路里没出现 float64", we, qe, wi, qi)}})
