}

// =====================================================================
// W46 d18：五档逐条判定与桶契约交接 —— 把「档」这件事一次结清
// ① 五档对照表由单一真源（bucketStart/bucketEnd/bucketKey）现场生成，手抄一份就会与 d13 漂移；② day/week/month 三档各自聚合后把 day 逐层合成，与直接聚合逐桶 diff，全 0 才算机器自检通过；
// ③ quarter/year 换一批带跨月退款/红冲（会互相抵消的负数项）的数据再证一次「月桶之和 == 直接季/年聚合」，专门暴露「先加后减」与「先减后加」的口径差；④ 金额全程 *_cents 整数，float64 那一版点名偏差落在哪个桶；
// ⑤ 六条判据逐条自测，其中整数分那条的对拍两边连时间窗一起传（跨窗比较由 versus 直接拒绝判定，不给你「两边各自都对、合起来是两道题」的机会）；⑥ 桶键编码 / 空桶占位 / 环比取上一桶三条契约整份交给 W47（d19..d24 只消费，不再重算任何一次边界）。
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d18
// =====================================================================
package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"
	_ "time/tzdata"
)

type Kind string // 聚合五档：档名、桶键编码、区间边界逐字沿用 d13 与 d17，不另起一套
var (
	KDay, KWeek, KMonth, KQuarter, KYear = Kind("day"), Kind("week"), Kind("month"), Kind("quarter"), Kind("year")
	exKey                                = map[Kind]string{KDay: "2026-09-03", KWeek: "2026-W36", KMonth: "2026-09", KQuarter: "2026-Q3", KYear: "2026"} // 五档样例键（d13 定稿），同时是白名单：档名不在这里，就没有「当前期」可回落
	layout                               = map[Kind]string{KDay: "2006-01-02", KWeek: "2006-01-02", KMonth: "2006-01", KQuarter: "2006-01", KYear: "2006"}
	stepOf                               = map[Kind][3]int{KDay: {0, 0, 1}, KWeek: {0, 0, 7}, KMonth: {0, 1, 0}, KQuarter: {0, 3, 0}, KYear: {1, 0, 0}}                                                                                                                                                                                                   // 日历量步进，不是 Add(24h)（d16 的 DST 坑）
	noteOf                               = map[Kind][2]string{KDay: {"YYYY-MM-DD", "start 升序：键即日期，字典序 == 时间序"}, KWeek: {"YYYY-Wnn", "start 升序：ISO 年号可跨年（2027-W01 仍属 2026 年）"}, KMonth: {"YYYY-MM", "start 升序：唯一的原子入账单位，季/年由它合成"}, KQuarter: {"YYYY-Qn（n∈1..4）", "start 升序：自然季从 1/4/7/10 月起，不是滚动 90 天"}, KYear: {"YYYY", "start 升序：键就是 YYYY，跨年红冲只能在年内相抵"}} // [编码形状, 排序方向]
	mark                                 = map[bool]string{true: "✅", false: "❌"}
	verd                                 = map[bool]string{true: "✅ 通过", false: "❌ 不通过"}
	yes                                  = map[bool]int{true: 1, false: 0}
	famID, famTZ                         = "fam-A", "Asia/Shanghai"                                              // family_id 由 JWT claims 解出、时区来自家庭设置（PRD 4.5.3）：两个都不是 query 参数
	endPeriod                            = 23*time.Hour + 59*time.Minute + 59*time.Second + 999*time.Millisecond // 期末最后一毫秒（d16 第 2 节）
	today                                = day0(2026, 9, 30).Add(endPeriod)                                      // 探针瞬间：真环境是 time.Now()，这里钉在月末最后一毫秒才能连跑复算
	tz                                   = mustLoad(famTZ)
)

func day0(y, m, d int) time.Time              { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, tz) }
func atoi(s string) int                       { n, _ := strconv.Atoi(s); return n }
func mustTime(l, s string) time.Time          { t, _ := time.ParseInLocation(l, s, tz); return t } // 解析失败返回零值时间，交给后面的 canonical 往返去判死
func mustLoad(n string) *time.Location        { l, _ := time.LoadLocation(n); return l }           // 时区取不到就在第一次 day0 当场崩，不静默回落 UTC
func monday(d time.Time) time.Time            { return d.AddDate(0, 0, -(int(d.Weekday())+6)%7) }  // 周一起点 = date_trunc('week')；1 月 4 日永远落在第 1 周（d13）
func addStep(k Kind, s time.Time) time.Time   { p := stepOf[k]; return s.AddDate(p[0], p[1], p[2]) }
func bucketEnd(k Kind, t time.Time) time.Time { return addStep(k, bucketStart(k, t)) } // 排他右端恒等于下一桶 start：窗口拼接不重不漏
func abs(c int64) int64                       { return map[bool]int64{true: -c, false: c}[c < 0] }
func money(c int64) string                    { return fmt.Sprintf("%d.%02d", c/100, abs(c)%100) } // 分→元：全链路唯一一次换算，只在展示层、只在聚合之后
func bucketStart(k Kind, t time.Time) time.Time { // 半开区间左端 [start, end)：周一/月初/季初/年初的墙上 00:00
	l, d := t.In(tz), day0(t.In(tz).Year(), int(t.In(tz).Month()), t.In(tz).Day())
	return map[Kind]time.Time{KDay: d, KWeek: monday(d), KMonth: day0(l.Year(), int(l.Month()), 1), KQuarter: day0(l.Year(), (int(l.Month())-1)/3*3+1, 1), KYear: day0(l.Year(), 1, 1)}[k]
}
func bucketKey(k Kind, t time.Time) string { // 契约 1：五种编码的唯一产出点，客户端只回传键串；ISO 周号由星期四所在的年决定，Format 表达不了
	s, th := bucketStart(k, t), bucketStart(k, t).AddDate(0, 0, 3)
	return map[Kind]string{KDay: s.Format("2006-01-02"), KWeek: fmt.Sprintf("%d-W%02d", th.Year(), (th.YearDay()+6)/7), KMonth: s.Format("2006-01"), KQuarter: fmt.Sprintf("%d-Q%d", s.Year(), (int(s.Month())-1)/3+1), KYear: s.Format("2006")}[k]
}

// 契约 1 的反向是 parseKey：canonical 往返，bucketKey(还原起点) 必须逐字等于入参。空串、2026-9、202609、2026-Q0、2026-Q5、2025-W53、2026-W54、2026-W00、2026-09-31、时间戳、未知档全卡在这道门上；这里没有回落分支，失败一律 error，由 handle 换成 400。同一套往返门也是 d17 第 3 节那条红线的地基：d17 原先给 week/quarter 开了「长度对就提前 return」的旁路，四条非法编码被 time.Date 的日历归一化接走返回 200，旁路拆掉后它的名单也逐条 400。
func parseKey(k Kind, s string) (time.Time, error) {
	y, n, p := atoi(s[:min(4, len(s))]), atoi(strings.TrimLeft(s[max(0, len(s)-2):], "WQ")), mustTime(layout[k], s) // min/max 只为非法输入不 panic；week/quarter 的键在 layout 下解析不出，p 自然是零值
	t := map[Kind]time.Time{KDay: p, KMonth: p, KYear: p, KQuarter: day0(y, (n-1)*3+1, 1), KWeek: monday(day0(y, 1, 4)).AddDate(0, 0, 7*(n-1))}[k]
	rt := bucketKey(k, t)
	return map[bool]time.Time{true: t, false: time.Time{}}[rt == s], map[bool]error{true: nil, false: fmt.Errorf("window=%q 非法：%s 档形如 %s%s服务端不猜当前窗、不回落默认档", s, k, map[bool]string{true: noteOf[k][0], false: "day / week / month / quarter / year"}[noteOf[k][0] != ""], map[bool]string{true: fmt.Sprintf("，还原出来是 %q，对不上", rt), false: ""}[rt != "" && !t.IsZero()])}[rt == s]
}
func shiftKey(k Kind, s string, back bool) (string, error) { // 契约 3 的实现：环比与累计的唯一位移函数，W47 只准调它；Add(-1) = 退 1 纳秒
	st, e := parseKey(k, s)
	return bucketKey(k, map[bool]time.Time{true: st.Add(-1), false: bucketEnd(k, st)}[back]), e
}

type row struct { // 内存表 = finance_transaction 的行，金额只有 *_cents 整数
	id, fam  string
	inc, exp int64 // income_cents / expense_cents：只有对应 type 那列非 0，等价 SQL 的 FILTER
	at       time.Time
	soft     bool // true = deleted_at 非空
}

func (r row) backAt() time.Time { // B 口径：红冲搬回原支出月；没有 origin 就还在自己所在的月
	o, _ := parseKey(KMonth, originOf[r.id])
	return map[bool]time.Time{true: o, false: r.at}[originOf[r.id] == ""]
}

type bucket struct { // 响应体形态 = d14 第 7 节那份契约，七个字段整份交给 W47（第 6 节）
	Key          string    `json:"key"`
	StartAt      string    `json:"start_at"`
	EndAt        string    `json:"end_at"`
	IncomeCents  int64     `json:"income_cents"`
	ExpenseCents int64     `json:"expense_cents"`
	NetCents     int64     `json:"net_cents"`
	TxnCount     int64     `json:"txn_count"`
	start        time.Time // 未导出：不进响应体，跨档上卷与环比只认这一条路（d15 的 ParentBucket）
}

var base = []row{{"t-01", famID, 0, 120000, day0(2026, 7, 3).Add(9 * time.Hour), false}, {"t-02", famID, 0, 45000, day0(2026, 7, 31).Add(endPeriod), false}, {"t-03", famID, 860000, 0, day0(2026, 8, 1), false}, {"t-04", famID, 0, 33000, day0(2026, 8, 19).Add(12 * time.Hour), true}, {"t-05", famID, 0, 210000, day0(2026, 9, 9).Add(20 * time.Hour), false}, {"t-06", famID, 0, 78000, day0(2026, 9, 30).Add(endPeriod), false}, {"t-07", "fam-B", 0, 999000, day0(2026, 8, 8).Add(8 * time.Hour), false}, {"t-08", famID, 150000, 0, day0(2026, 10, 1), false}}                                                                                                                         // 逐字沿用 d14/d17 那批 2026-Q3 流水（软删 / 越权 / 季外三行都在）
var reds = []row{{"r-01", famID, 0, 88500, day0(2026, 5, 6).Add(9 * time.Hour), false}, {"r-02", famID, 0, -88500, day0(2026, 6, 3).Add(10 * time.Hour), false}, {"r-03", famID, 0, 120000, day0(2026, 7, 20).Add(8 * time.Hour), false}, {"r-04", famID, 0, -210000, day0(2026, 10, 5).Add(9 * time.Hour), false}, {"r-05", famID, 0, 88500, day0(2026, 12, 5).Add(14 * time.Hour), false}, {"r-06", famID, 0, 33333, day0(2026, 12, 18).Add(9 * time.Hour), false}, {"r-07", famID, 0, -120000, day0(2026, 12, 31).Add(endPeriod), false}, {"r-08", famID, 0, -45000, day0(2027, 1, 8).Add(11 * time.Hour), false}, {"r-09", famID, 0, 50000, day0(2027, 1, 20).Add(20 * time.Hour), false}} // 带跨月 / 跨季 / 跨年红冲的一批：负数支出 = 退款，r-06 那笔 333.33 元专门喂浮点偏差
var originOf = map[string]string{"r-02": "2026-05", "r-04": "2026-09", "r-07": "2026-07", "r-08": "2026-07"}                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   // 四条红冲：季内、跨季、跨季、跨年四种搬法各占一条
var trendCalls, chain int                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // 判据④「聚合只在服务端一处完成」的证据就是 trendCalls；chain 收第 6 节 prev 的 next 回原键的通过数

// trend：全项目唯一的出桶 + 聚合现场（契约 2 的补桶就在那条枚举循环里）。行集已由 pick 挡掉 deleted_at / family_id / 窗外，这里只剩稠密枚举（没数的期也占一格）与整数分累加；moved 切「先减后加」（红冲搬回原期 = B 口径）与「先加后减」（按 occurred_at = A 口径），生产代码里只有 A 这一条路。
func trend(k Kind, f, t time.Time, rows []row, moved bool) []bucket {
	trendCalls++
	idx, out := map[string]int{}, []bucket{}
	for cur := bucketStart(k, f); cur.Before(t); cur = bucketEnd(k, cur) {
		out, idx[bucketKey(k, cur)] = append(out, bucket{Key: bucketKey(k, cur), StartAt: cur.Format(time.RFC3339), EndAt: bucketEnd(k, cur).Format(time.RFC3339), start: cur}), len(out)
	}
	for _, r := range rows {
		x := &out[idx[bucketKey(k, map[bool]time.Time{true: r.backAt(), false: r.at}[moved])]] // 行集必须与桶同一扇窗出，否则键不在稠密序列里
		x.IncomeCents, x.ExpenseCents, x.NetCents, x.TxnCount = x.IncomeCents+r.inc, x.ExpenseCents+r.exp, x.NetCents+r.inc-r.exp, x.TxnCount+1
	}
	return out
}
func roll(from []bucket, to Kind) map[string]int64 { // 低阶桶 → 高阶桶：只认桶 start，换时区或按键串切片都会错（d15）
	out := map[string]int64{}
	for _, x := range from {
		out[bucketKey(to, x.start)] += x.NetCents
	}
	return out
}
func empt(bs []bucket) (n int) { // 0 值桶个数：稠密枚举留下的空格，一个都不过滤
	for _, x := range bs {
		n += yes[x.TxnCount == 0]
	}
	return n
}
func sumRows(rows []row) (v int64) { // 逐笔相加：与桶和完全独立的一条算路，diff 才有意义
	for _, r := range rows {
		v += r.inc - r.exp
	}
	return v
}
func sumBuckets(bs []bucket) (v int64) { // 稠密桶序列 → 窗内总和：与 sumRows 同为「一段窗的和」，两边同窗才允许比
	for _, x := range bs {
		v += x.NetCents
	}
	return v
}

// measure：一个比较量连同产出它的那段半开窗。versus 是这天的教学增量——对拍的防护：
// 两个量不在同一扇窗里就没有「相等」可言，直接拒绝判定，而不是把两个数印到同一行等号两侧。
// 本程序第一版栽的正是这个：拿 2026 年单桶（6451.67 元）去比含 2027 的全窗逐笔和（6401.67 元），
// 于是打出「Σ月桶 6451.67 元 == Σ逐笔 6401.67 元」这种自相矛盾的结论、判据⑥ 白挂 ❌。
// 跨窗比较不是数值错，是比较量选错——报表里这类「两边各自都算对、合起来答的是两道题」最难查。
type measure struct {
	label    string
	from, to time.Time
	cents    int64
}

func versus(a, b measure) (string, bool) { // 同窗才比：窗不一致就拒绝判定，并把两边的窗原样打出来
	d := func(x time.Time) string { return x.Format("2006-01-02") }
	if !a.from.Equal(b.from) || !a.to.Equal(b.to) {
		return fmt.Sprintf("❌ 拒绝跨窗对拍：%s 窗 [%s, %s) %s 元 vs %s 窗 [%s, %s) %s 元 —— 两边各自都没算错，只是不是同一段窗，先把比较量挪到同一扇窗再谈等号",
			a.label, d(a.from), d(a.to), money(a.cents), b.label, d(b.from), d(b.to), money(b.cents)), false
	}
	return fmt.Sprintf("✅ 同窗 [%s, %s)：%s %s 元 == %s %s 元（差 %d 分）", d(a.from), d(a.to), a.label, money(a.cents), b.label, money(b.cents), a.cents-b.cents), a.cents == b.cents
}
func pick(fam string, f, t time.Time) (out []row) { // 等价 WHERE family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?（"-" 模拟忘带 family_id）
	for _, r := range append(append([]row{}, base...), reds...) {
		out = append(out, map[bool][]row{true: {r}, false: nil}[!r.soft && (fam == "-" || r.fam == fam) && !r.at.Before(f) && r.at.Before(t)]...)
	}
	return out
}
func handle(win Kind, window string) (int, string, int, string) { // 一次调用拿到两份结果：红线版解析失败即 400、信息里给合法形状；崩法版（d17 第 2 节那道题）状态码照发 200，窗却被静默换成当前期。
	st, err := parseKey(win, window)
	if err != nil || noteOf[win][0] == "" { // 未知档也走这条岔路：它没有「当前期」可回落，绝不允许掉进下面那行按未知档枚举的循环
		return 400, err.Error(), 200, fmt.Sprintf("❌ 静默换窗：丢掉 window=%q，改成当前期 %s 的 %d 个月桶，200 照发", window, bucketKey(KMonth, today), len(trend(KMonth, today, bucketEnd(KMonth, today), pick(famID, today, bucketEnd(KMonth, today)), false)))
	}
	bs := trend(win, st, bucketEnd(win, st), pick(famID, st, bucketEnd(win, st)), false)
	return 200, fmt.Sprintf("窗 [%s, %s) 稠密出桶 %d 个，其中 %d 个 0 值桶照样带 key/start_at/end_at", st.Format("2006-01-02"), bucketEnd(win, st).Format("2006-01-02"), len(bs), empt(bs)), 200, "合法 query 两版同样 200"
}

// diffs：一条算路的逐桶对拍表。a = 低阶桶之和、b = 另一口径之和（传 nil 表示这条算路没有 B 口径），返回 桶数 / A 相等数 / B 相等数 / 半桶数。
func diffs(lab string, k Kind, f, t time.Time, bs []bucket, a, b map[string]int64) (int, int, int, int) {
	n, za, zb, half := 0, 0, 0, 0
	for _, x := range bs {
		v, w, has := a[x.Key], b[x.Key], b != nil
		full := !x.start.Before(f) && !bucketEnd(k, x.start).After(t)
		n, za, zb, half = n+1, za+yes[v == x.NetCents], zb+yes[!has || w == x.NetCents], half+yes[!full]
		fmt.Printf("  %-13s %-11s %-12s %-12s %-8d %-12s %-11s %-4s %s %s\n", lab, x.Key, money(x.NetCents), money(v), v-x.NetCents, map[bool]string{true: "——", false: money(w)}[!has], map[bool]string{true: "——", false: fmt.Sprintf("%d 分", w-x.NetCents)}[!has], map[bool]string{true: "整", false: "半"}[full], mark[v == x.NetCents], map[bool]string{true: "——", false: mark[w == x.NetCents]}[!has])
	}
	return n, za, zb, half
}
