// =====================================================================
// W47 d19：为什么要服务端算累计 —— 「前端二次累加必须为 0」是验收项。
//
// 累计余额 = 期初 + 单期净值的前缀和。看着像「前端把单期值再加一遍」的顺手活儿：
// 今天四种前端加法只有一种差值全 0 —— 丢期初、自算符号、分页清零，每一种都会把
// 后面整条链带走，而且错得很像（前几期还是对的、不炸也不 NaN）。
// 五档桶口径（编码、[start,end) 边界、家庭时区）逐字沿用 W46 d13。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d19
// =====================================================================

package main

import "fmt"
import "time"
import _ "time/tzdata" // 打包时区库：家庭时区可以是任意 IANA 名（W46 d13）

// ---------- W46 d13 定稿的五档桶口径，照搬不另起一套 ----------
type Kind string

const KDay, KWeek, KMonth, KQuarter, KYear = Kind("day"), Kind("week"), Kind("month"), Kind("quarter"), Kind("year")

var famLoc = mustLoad("Asia/Shanghai") // PRD 4.5.3：时间窗一律按家庭时区算
var step = map[Kind][3]int{KDay: {0, 0, 1}, KWeek: {0, 0, 7}, KMonth: {0, 1, 0}, KQuarter: {0, 3, 0}, KYear: {1, 0, 0}}
var layout = map[Kind]string{KDay: "2006-01-02", KMonth: "2006-01", KYear: "2006"} // 另外两档：YYYY-Wnn、YYYY-Qn
var mark = map[bool]string{true: "✅ 对齐", false: "❌ 断链"}
var state = map[bool]string{true: "空桶", false: "有流水"}

func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err) // 取不到时区就崩，绝不静默回落 UTC
	}
	return l
}
func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }

// bucketStart：桶起点。周一 / 月初 / 季初 / 年初，全部取家庭时区的墙上 00:00。
func bucketStart(k Kind, t time.Time) time.Time {
	l := t.In(famLoc)
	d := day0(l.Year(), int(l.Month()), l.Day())
	switch k {
	case KWeek:
		return d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7)) // 周一起点 = Postgres date_trunc('week')
	case KMonth:
		return day0(l.Year(), int(l.Month()), 1)
	case KQuarter:
		return day0(l.Year(), ((int(l.Month())-1)/3)*3+1, 1) // 自然季 1/4/7/10 月，不是滚动 90 天
	case KYear:
		return day0(l.Year(), 1, 1)
	}
	return d
}
func bucketEnd(k Kind, t time.Time) time.Time { // 排他终点：查询永远是 >= start AND < end
	s := bucketStart(k, t)
	return s.AddDate(step[k][0], step[k][1], step[k][2]) // 步进用日历量，不用 Add(24h)
}
func bucketKey(k Kind, t time.Time) string { // 五档五种编码，全项目只在这里产出
	l := t.In(famLoc)
	if k == KQuarter {
		return fmt.Sprintf("%04d-Q%d", l.Year(), (int(l.Month())-1)/3+1)
	}
	if k == KWeek {
		y, w := l.ISOWeek() // Go 的 time.Format 表达不了 ISO 周，必须走 ISOWeek()
		return fmt.Sprintf("%04d-W%02d", y, w)
	}
	return l.Format(layout[k])
}
func bucketKeys(k Kind, f, t time.Time) []string { // 一个窗 → 稠密桶键序列：没流水的期也占一格
	var out []string
	for cur := bucketStart(k, f); cur.Before(t); cur = bucketEnd(k, cur) {
		out = append(out, bucketKey(k, cur))
	}
	return out
}
func money(c int64) string { // 分 → 元.角分：纯整数格式化，聚合链路上不出现浮点
	neg := ""
	if c < 0 {
		neg, c = "-", -c
	}
	return fmt.Sprintf("%s%d.%02d", neg, c/100, c%100)
}
func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---------- 期初 + 流水：金额一律 *_cents 整数 ----------
type Txn struct {
	ID, Kind    string
