// series：服务端唯一一次遍历 —— 先按桶键聚合，再按稠密桶序列补零对齐。
func series(k Kind, f, t time.Time, sign map[string]int64) ([]string, []int64, []int) {
	sum, cnt := map[string]int64{}, map[string]int{}
	for _, x := range txns {
		key := bucketKey(k, x.At)
		sum[key] += sign[x.Kind] * x.AmountCents // 符号表查不到 → Go 的 map 缺失静默返 0，不报错
		cnt[key]++
	}
	keys := bucketKeys(k, f, t)
	nets, nc := make([]int64, len(keys)), make([]int, len(keys))
	for i, key := range keys {
		nets[i], nc[i] = sum[key], cnt[key] // 空桶在这里补 0：占位而不缺席
	}
	return keys, nets, nc
}

// accumulate：前端那一遍「二次累加」。reset>0 模拟游标分页每页重开累加器。
func accumulate(nets []int64, start int64, reset int) []int64 {
	out, run := make([]int64, len(nets)), start
	for i, n := range nets {
		if reset > 0 && i%reset == 0 {
			run = 0
		}
		run += n
		out[i] = run
	}
	return out
}
func lastDiff(server, client []int64) int64 { return client[len(client)-1] - server[len(server)-1] }
func diffTable(keys []string, server, client []int64) (int, int64) {
	fmt.Printf("  %-9s %-12s %-12s %-12s %s\n", "period", "server_cum", "client_cum", "diff", "判定")
	bad, last := 0, int64(0)
	for i := range keys {
		d := client[i] - server[i]
		if d != 0 {
			bad, last = bad+1, d
		}
		fmt.Printf("  %-9s %-12s %-12s %-12s %s\n", keys[i], money(server[i]), money(client[i]), money(d), mark[d == 0])
	}
	return bad, last
}

func main() {
	from, to := day0(2026, 1, 1), day0(2026, 9, 1)
	hdr(fmt.Sprintf("1. 场景：%d 笔流水 + 期初 %s 元，服务端按「月档」逐期累加", len(txns), money(openingCents)))
	fmt.Printf("  符号表（家庭视角，PRD 4.5.3）服务端 %v\n", famSign)
	fmt.Printf("    前端自写的那份 %v ← 缺 refund（Go 的 map 缺失静默返 0）、transfer 符号相反\n", naiveSign)
	keys, nets, cnt := series(KMonth, from, to, famSign)
	cum := accumulate(nets, openingCents, 0)
	fmt.Println("  每笔落哪个桶（桶键由 bucketKey 按家庭时区产出，家庭增量按 famSign）：")
	for _, x := range txns {
		fmt.Printf("  %s %-8s %9s 元 @ %s → 桶 %s，家庭增量 %9s 元\n", x.ID, x.Kind, money(x.AmountCents), x.At.In(famLoc).Format("2006-01-02 15:04"), bucketKey(KMonth, x.At), money(famSign[x.Kind]*x.AmountCents))
	}
	fmt.Printf("  %-9s %-4s %-7s %-12s %-12s %s\n", "period", "笔数", "状态", "net_cents", "cum_cents", "检查：cum − 期初 = Σnet 到本期")
	for i, key := range keys {
		fmt.Printf("  %-9s %-4d %-7s %-12s %-12s %s\n", key, cnt[i], state[cnt[i] == 0], money(nets[i]), money(cum[i]), money(cum[i]-openingCents))
	}
	fmt.Printf("  校验：期末 cum %s 元 = 期初 %s 元 + Σnet %s 元 —— 最后这步加法就是前端每天要做的事\n", money(cum[len(cum)-1]), money(openingCents), money(cum[len(cum)-1]-openingCents))
	hdr("2. ✅ 协议齐全（net_cents + cum_cents + opening_cents）：逐期差值全 0")
	badP, _ := diffTable(keys, cum, accumulate(nets, openingCents, 0))
	fmt.Printf("  非 0 差值 %d 处 —— PRD 18.3#9 的验收项就是这一列。\n", badP)
	fmt.Println("  前端只做「展示 + 自检」：cum_cents 用服务端的，自己加的那一遍只拿来对比，绝不进渲染。")
	hdr("3. ❌ 崩法 A：payload 没带 opening_cents，前端从 0 起加")
	badA, lastA := diffTable(keys, cum, accumulate(nets, 0, 0))
	fmt.Printf("  非 0 %d/%d 期，末期偏差 %s 元 == 期初 —— 曲线形状完全正确、整条链等量下移。\n", badA, len(keys), money(lastA))
	fmt.Println("  它不炸、不 NaN，只是每期都少同一个数：肉眼 review 挡不住，只有逐期 diff 能挡。")
	hdr("4. ❌ 崩法 B：前端用自写符号表算 net（漏 refund、转账按单腿扣）")
	_, nNets, _ := series(KMonth, from, to, naiveSign)
	badB, lastB := diffTable(keys, cum, accumulate(nNets, openingCents, 0))
	fmt.Printf("  非 0 %d/%d 期，末期偏差 %s 元。第一期还是 0，偏差从有退款/转账的那一期才冒出来。\n", badB, len(keys), money(lastB))
	fmt.Println("  纪律：符号表只有一份，在服务端。客户端出现第二套 kind→符号 映射，账就永远对不上。")
	hdr("5. ❌ 崩法 C：游标分页 page_size=3，每页把累加器清零")
	badC, lastC := diffTable(keys, cum, accumulate(nets, openingCents, 3))
	fmt.Printf("  非 0 %d/%d 期，末期偏差 %s 元 —— 每翻一页断一次链，翻页后余额突然变小。\n", badC, len(keys), money(lastC))
	fmt.Println("  正确做法：游标带状态，下一页带上上一页最后一期的 cum_cents 当起点，而不是只带页码。")
	hdr("6. 换档 = 换一条链：五个档位各自的桶数与末期偏差")
	fmt.Printf("  %-8s %-6s %-14s %-14s %-14s %s\n", "kind", "桶数", "协议齐全末期差", "丢期初末期差", "分页清零末期差", "首/末桶")
	for _, k := range []Kind{KDay, KWeek, KMonth, KQuarter, KYear} {
		ks, ns, _ := series(k, from, to, famSign)
		sc := accumulate(ns, openingCents, 0)
		fmt.Printf("  %-8s 桶 %3d  %-14s %-14s %-14s %s → %s\n", k, len(ks), money(lastDiff(sc, accumulate(ns, openingCents, 0))), money(lastDiff(sc, accumulate(ns, 0, 0))), money(lastDiff(sc, accumulate(ns, openingCents, 3))), ks[0], ks[len(ks)-1])
	}
	fmt.Println("  累计余额属于「档位 + 窗 + 期初」三元组：切档必须整段重算，拿上一档的尾巴接这一档的头就是错（d20 展开）。")
