	fmt.Println("  · kind：day/week/month/quarter/year 五档之一，前端不得自己推桶边界（W46 d13 的 bucketStart/bucketEnd/bucketKey）")
	fmt.Println("  · window_from / window_to：桶起点与排他终点，RFC3339 带家庭时区")
	fmt.Println("  · opening_cents：期初余额。缺了它整条链下移，而且看不出错")
	fmt.Println("  · buckets[].period：稠密桶键，空期也必须出现（d22 的空桶对齐）")
	fmt.Println("  · buckets[].net_cents / cum_cents / txn_count：单期值、服务端累计值、笔数")
	fmt.Println("  · 金额字段一律 *_cents 整数，百分比用定点（d21）：浮点不进聚合链路")
	fmt.Println("  · 前端自检里必须有一条「二次累加逐期 diff == 0」的断言，否则改渲染时会悄悄改平了账")
	fmt.Println("\n=== W47 d19 到此结束 ===")
	fmt.Println("明天把这条链做成前缀和：账户维度、分类维度各一条，并证明季/年的累计等于月桶之和。")
}

