// netsOf：把 txns 按维度拆腿、按稠密桶键聚合。账户维度转账拆两腿（一出一入合计 0）；分类不落转账；家庭按 famSign 记（转账恒 0）。
func netsOf(dim string, k Kind, f, t time.Time) ([]string, []string, map[string][]int64) {
	keys := bucketKeys(k, f, t)
	pos := map[string]int{}
	for i, key := range keys {
		pos[key] = i
	}
	var ents []string
	net := map[string][]int64{}
	add := func(ent string, cents int64, at time.Time) {
		row, seen := net[ent]
		if !seen {
			row = make([]int64, len(keys))
			net[ent] = row
			ents = append(ents, ent)
		}
		row[pos[bucketKey(k, at)]] += cents
	}
	for _, x := range txns {
		switch dim {
		case "account":
			if x.Kind == "transfer" {
				add(x.AccountID, -x.AmountCents, x.At)
				add(x.ToAccountID, x.AmountCents, x.At)
			} else {
				add(x.AccountID, famSign[x.Kind]*x.AmountCents, x.At)
			}
		case "category":
			if x.Kind != "transfer" {
				add(x.CategoryID, famSign[x.Kind]*x.AmountCents, x.At)
			}
		default:
			add("FAMILY", famSign[x.Kind]*x.AmountCents, x.At)
		}
	}
	return keys, ents, net
}

func main() {
	from, to := day0(2026, 1, 1), day0(2027, 7, 1) // 18 个月桶：无流水的月份照样占位（前缀和 += 0）
	mk, _, fam := netsOf("family", KMonth, from, to)
	frow := prefix(fam["FAMILY"], openingCents)
	hdr("1. 家庭维度：每笔按 bucketKey（家庭时区）落进月桶，转账记 0")
	for _, x := range txns {
		fmt.Printf("  %s %-8s %9s 元 @ %s → %s 桶，家庭增量 %9s 元\n", x.ID, x.Kind, money(x.AmountCents), x.At.In(famLoc).Format("2006-01-02 15:04"), bucketKey(KMonth, x.At), money(famSign[x.Kind]*x.AmountCents))
	}
	hdr("2. 逐期前缀和：期初 + 累计 net = 一条 cum 链；空期原地不动")
	fmt.Printf("  %-9s %-11s %-13s %s\n", "period", "net_cents", "cum_cents", "校验 cum−期初=Σnet")
	acc := int64(0)
	for i, key := range mk {
		acc += fam["FAMILY"][i]
		fmt.Printf("  %-9s %-11s %-13s %s\n", key, money(fam["FAMILY"][i]), money(frow[i]), ok[frow[i]-openingCents == acc])
	}
	hdr("3. 账户维度：转账拆两腿、家庭相抵；Σ各账户 cum = 家庭 cum")
	ak, accts, anet := netsOf("account", KMonth, from, to)
	sum := int64(0)
	for _, a := range accts {
		sum += acctStart[a]
	} // Σ账户期初：维度对账的第一道前置校验，不等则后面每行 cum 必然全 ❌
	fmt.Printf("  账户 %v，Σ账户期初 %s，家庭期初 %s，校验 Σ账户期初=家庭期初 %s\n", accts, money(sum), money(openingCents), ok[sum == openingCents])
	bc, cc := prefix(anet["ac-bank"], acctStart["ac-bank"]), prefix(anet["ac-cash"], acctStart["ac-cash"])
	for i, key := range ak {
		fmt.Printf("  %-9s bank净 %-9s cash净 %-9s Σ净 %-9s 家庭净 %-9s Σcum %-12s 家庭cum %-12s %s\n", key, money(anet["ac-bank"][i]), money(anet["ac-cash"][i]), money(anet["ac-bank"][i]+anet["ac-cash"][i]), money(fam["FAMILY"][i]), money(bc[i]+cc[i]), money(frow[i]), ok[bc[i]+cc[i] == frow[i]])
	}
	hdr("4. 分类维度：只有流量、没有期初；逐分类逐期，Σ分类 net = 家庭 net")
	ck, cats, cnet := netsOf("category", KMonth, from, to)
	for i, key := range ck {
		tot, line := int64(0), ""
		for _, c := range cats {
			tot += cnet[c][i]
			line += " " + c + "=" + money(cnet[c][i])
		}
		fmt.Printf("  %-9s%s Σ=%-9s 家庭=%-9s %s\n", key, line, money(tot), money(fam["FAMILY"][i]), ok[tot == fam["FAMILY"][i]])
	}
	hdr("5. 季 = 月桶之和（net 口径）；细→粗必须对齐才能合成")
	qk, _, qnet := netsOf("family", KQuarter, from, to)
	for i, q := range qk {
		sm, mon := int64(0), ""
		for j := i * 3; j < i*3+3 && j < len(mk); j++ {
			sm += fam["FAMILY"][j]
			mon += " " + mk[j]
		}
		fmt.Printf("  %-8s 由月桶[%s] 合成，季净 %-9s 各月和 %-9s %s\n", q, mon, money(qnet["FAMILY"][i]), money(sm), ok[qnet["FAMILY"][i] == sm])
	}
	hdr("6. 跨档混算必偏：周桶跨月，把周硬拼成月就漏（列全部跨月周）")
	wk, _, wnet := netsOf("family", KWeek, from, to)
	n := 0
	for cur := bucketStart(KWeek, from); cur.Before(to); cur = bucketEnd(KWeek, cur) {
		lo, hi := cur.In(famLoc), bucketEnd(KWeek, cur).AddDate(0, 0, -1).In(famLoc)
		if int(lo.Month()) != int(hi.Month()) { // 起月 ≠ 止月：该周 net 骑在两个整月桶之间，归不进单月
			fmt.Printf("  周 %-9s %s~%s 跨 %d/%d 两月，net %-9s 归不进单个整月桶\n", wk[n], lo.Format("01-02"), hi.Format("01-02"), int(lo.Month()), int(hi.Month()), money(wnet["FAMILY"][n]))
		}
		n++
	}
	hdr("7. 边界切桶只认家庭时区：同一笔按 UTC 会错一整月")
	x := txns[11] // T-12 @ 家庭 07-01 00:30 = UTC 06-30 16:30
	fmt.Printf("  %s income %s 元 @ 家庭 %s = UTC %s\n", x.ID, money(x.AmountCents), x.At.In(famLoc).Format("2006-01-02 15:04"), x.At.UTC().Format("2006-01-02 15:04"))
	fmt.Printf("  正确 bucketKey(KMonth)=%s；错误按 UTC 切=%s → 落错桶，该期 net 与 cum 双双错位。日→月→季→年可对齐合成，周桶例外；切桶口径唯一：famLoc + bucketKey，前端不重算边界。\n", bucketKey(KMonth, x.At), x.At.UTC().Format("2006-01"))
	fmt.Println("\n=== W47 d20 到此结束 ===")
	fmt.Println("明天把「本期 ÷ 上期」的环比立起来：除零怎么不炸、无对比基数怎么显。")
}

// =====================================================================
// W47 d21：环比的定义与除零 —— 「(本期−上期)/上期」在上期为 0 时根本不能除。
// d19/d20 立了累计（前缀和），今天补环比这一半：分母是相邻的上一个桶。
// d19 那批数据里 2026-04 一笔流水都没有、净值为 0：整数除它 panic、浮点除它得
// +Inf/NaN，两个都进不了响应体（encoding/json 直接报错）；2026-07 净值是负的，
// 符号口径再咬一口。定稿：定点万分比（bp）+ 状态位，没有基数就显「无对比基数」，不是 0%、∞、NaN%。
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d21
// =====================================================================
package main

import "encoding/json"
import "fmt"
import "math"
import "time"
import _ "time/tzdata" // 打包时区库：家庭时区可以是任意 IANA 名（W46 d13）
// ---------- W46 d13 的五档桶口径 + W47 d19 的样例数据：照搬，不另起一套 ----------
type Kind string

const KDay, KWeek, KMonth, KQuarter, KYear = Kind("day"), Kind("week"), Kind("month"), Kind("quarter"), Kind("year")

var famLoc = mustLoad("Asia/Shanghai") // PRD 4.5.3：时间窗一律按家庭时区算
var step = map[Kind][3]int{KDay: {0, 0, 1}, KWeek: {0, 0, 7}, KMonth: {0, 1, 0}, KQuarter: {0, 3, 0}, KYear: {1, 0, 0}}
var famSign = map[string]int64{"income": 1, "expense": -1, "refund": 1, "transfer": 0} // d19 的符号表，全项目只此一份
var label = map[string]string{"ok": "", "no_base": "无对比基数", "neg_base": "上期净赤，环比不可比"}

const openingCents int64 = 2350000 // d19 的家庭期初：环比用不到它，但同一批数据必须同一个期初
const fam = "fam-A"                // 租户边界：这张内存表只装 fam-A（跨家泄露后果见 W46 d14）
const tbl = "finance_transaction"  // 表名沿用 W46 d14/d16 与 W47 d19，不另起一套

func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err) // 取不到时区就崩，绝不静默回落 UTC
	}
	return l
}
func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }
func bucketStart(k Kind, t time.Time) time.Time { // 桶起点：周一/月初/季初/年初，一律家庭时区墙上 00:00
	l := t.In(famLoc)
	d := day0(l.Year(), int(l.Month()), l.Day())
	w := d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7))                                                                                                                            // 周一起点 = Postgres date_trunc('week')，跨月也整周（d20）
	return map[Kind]time.Time{KDay: d, KWeek: w, KMonth: day0(l.Year(), int(l.Month()), 1), KQuarter: day0(l.Year(), (int(l.Month())-1)/3*3+1, 1), KYear: day0(l.Year(), 1, 1)}[k] // 自然季 1/4/7/10 月，不是滚动 90 天
}
func bucketEnd(k Kind, t time.Time) time.Time { // 排他终点：查询永远是 >= start AND < end
	return bucketStart(k, t).AddDate(step[k][0], step[k][1], step[k][2]) // 步进用日历量，不用 Add(24h)
}
func bucketKey(k Kind, t time.Time) string { // 五档五种编码，全项目只在这里产出（ISO 周只能走 ISOWeek()，time.Format 表达不了）
	l := t.In(famLoc)
	y, w := l.ISOWeek()
	return map[Kind]string{KDay: l.Format("2006-01-02"), KWeek: fmt.Sprintf("%04d-W%02d", y, w), KMonth: l.Format("2006-01"), KQuarter: fmt.Sprintf("%04d-Q%d", l.Year(), (int(l.Month())-1)/3+1), KYear: l.Format("2006")}[k]
}
func bucketKeys(k Kind, f, t time.Time) []string { // 一个窗 → 稠密桶键序列：没流水的期也占一格（d22 的主角）
	var out []string
	for cur := bucketStart(k, f); cur.Before(t); cur = bucketEnd(k, cur) {
		out = append(out, bucketKey(k, cur))
	}
	return out
}
func money(c int64) string { // 分 → 元.角分：纯整数格式化，聚合与展示链路上都不出现浮点
	neg := ""
	if c < 0 {
		neg, c = "-", -c
	}
	return fmt.Sprintf("%s%d.%02d", neg, c/100, c%100)
}
func signed(c int64) string { return map[bool]string{true: "+", false: ""}[c >= 0] + money(c) }
func hdr(s string)          { fmt.Printf("\n===== %s =====\n", s) }
func abs64(v int64) int64   { return map[bool]int64{true: -v, false: v}[v < 0] }
func boolInt(b bool) int    { return map[bool]int{true: 1, false: 0}[b] }

// ---------- 定点百分比：万分比（bp）。分母为 0 时不做除法，改发状态位 ----------
func divRound(a, b int64) int64 { // 截断让正负两侧不对称（-0.4% 被记成 0）：按远离 0 的方向进位
	s, q, r := int64(1-2*boolInt((a < 0) != (b < 0))), abs64(a)/abs64(b), abs64(a)%abs64(b)
	return s * (q + int64(boolInt(2*r >= abs64(b))))
}
func pct(bp int64) string { // 展示串由整数拼出来：float 不参与任何一步
	return map[bool]string{true: "+", false: "-"}[bp >= 0] + fmt.Sprintf("%d.%02d%%", abs64(bp)/100, abs64(bp)%100)
}
func textOf(bp int64, st string) string {
	return map[bool]string{true: pct(bp), false: label[st]}[st == "ok"]
}

func chainRatio(prev, cur int64) (int64, string) { // 环比唯一入口：先判分母、再做除法，顺序反了就是第 2 节那两种崩法
	if prev == 0 {
		return 0, "no_base" // 一步都不除：整数 panic、浮点 +Inf/NaN，这两个都不该出现在响应里
	}
	return divRound((cur-prev)*10000, abs64(prev)), map[bool]string{true: "neg_base", false: "ok"}[prev < 0]
}
func bpOf(prev, cur int64) int64 { v, _ := chainRatio(prev, cur); return v }

// wrongWay：同一对相邻桶把两种错法各跑一遍——整数那路在 return 那行炸、被 recover 兜成字符串，float 那路只换个非法值。
func wrongWay(prev, cur int64) (ip, fp string) {
	f := float64(cur-prev) / float64(prev) // 这是比值：要 ×100 才是百分数，忘了乘就少 100 倍
	_, err := json.Marshal(map[string]any{"ratio": f})
	fp = fmt.Sprintf("%v IsInf=%v IsNaN=%v；×100 印成 %q；json: %v", f, math.IsInf(f, 0), math.IsNaN(f), fmt.Sprintf("%.2f%%", f*100), map[bool]string{true: "可序列化", false: fmt.Sprint(err)}[err == nil])
	defer func() {
		if r := recover(); r != nil {
			ip = fmt.Sprintf("panic(%v)", r)
		}
	}()
	return fmt.Sprintf("%d bp", (cur-prev)*10000/prev), fp // 分母为 0 → 炸在这一句
}

