// series：d19 那遍聚合原样复用（稠密桶键、净值、笔数）。笔数是 d22 要用的「有没有桶」。
func series(k Kind, f, t time.Time) ([]string, []int64, []int) {
	sum, cnt := map[string]int64{}, map[string]int{}
	for _, x := range txns {
		key := bucketKey(k, x.At)
		sum[key] += famSign[x.Kind] * x.AmountCents // 符号表查不到 → Go 的 map 缺失静默返 0，不报错
		cnt[key]++
	}
	keys := bucketKeys(k, f, t)
	nets, nc := make([]int64, len(keys)), make([]int, len(keys))
	for i, key := range keys {
		nets[i], nc[i] = sum[key], cnt[key] // 空桶在这里补 0：占位而不缺席
	}
	return keys, nets, nc
}

