	}
	hdr("2. ❌ 整数除 vs ❌ 浮点除 vs ✅ 定点 bp：月档 7 对相邻桶并排跑")
	fmt.Printf("  %-12s %-10s %-10s %-22s %-62s %-7s %s\n", "本期/上期", "本期净", "上期净", "整数 (cur−prev)*10000/prev", "float64 除（得比值，不是百分数）", "✅ bp", "展示/state")
