		fmt.Printf("  %-12s %-10s %-10s %-22s %-62s %-7s %s\n", keys[i]+"/"+keys[i-1], money(nets[i]), money(nets[i-1]), ip, fp, map[bool]string{true: fmt.Sprint(bp), false: "—"}[st != "no_base"], textOf(bp, st)+" "+st)
	}
	fmt.Printf("  两处崩点都在真实数据里：%s 的上期 %s 净值 %s（笔数 %d）→ 整数 panic、浮点 +Inf；日档 %s→%s 两格净值都是 0（前一格笔数 %d，转账不改变家庭净资产）→ 0÷0 = NaN。\n", keys[4], keys[3], money(nets[3]), cnt[3], dk[zi], dk[zi+1], dc[zi])
	fmt.Printf("  「本期为 0」不是除零：%s 本期 %s、上期 %s → %s：真实的跌到零，照常展示（分母是上期，不是本期）。\n", keys[3], money(nets[3]), money(nets[2]), pct(bpOf(nets[2], nets[3])))
	tr := (nets[5] - nets[4]) * 10000 / nets[4]
	fmt.Printf("  定点要进位不要截断：%s→%s 截断 %d bp=%s、进位 %d bp=%s —— 差 0.01%% 也是差，和账户对账时它一定漂。\n", keys[4], keys[5], tr, pct(tr), bpOf(nets[4], nets[5]), pct(bpOf(nets[4], nets[5])))
	fmt.Println("  线上后果分两种：panic 被 gin Recovery 接住 = 该请求 500（监控看得见）；+Inf/NaN 不是合法 JSON（上面 json 那列报的就是它），\n  用 fmt 硬印成字符串则页面上出现 \"NaN%\"、\"+Inf%\"，前端拿它排序着色，整屏跟着 NaN —— 比 500 更难查。两种都不许进响应。\n  挪进 SQL 同理：Postgres 里 (cur−prev)/prev 报 division by zero —— 除法只能发生在判过分母之后那一步。")
	hdr("3. 换到日档：2026-02 整月逐期环比（结论在表末统计）")
	fmt.Printf("  %-11s %-4s %-11s %-11s %s\n", "day", "笔数", "本期净", "上期净", "环比（✅ 口径）")
	sts := map[string]int{}
	for i := 1; i < len(dk); i++ {
		bp, st := chainRatio(dn[i-1], dn[i])
		sts[st]++ // 三种状态各自数一遍：表末那句结论由这张计数表出，不写死
		fmt.Printf("  %-11s %-4d %-11s %-11s %s\n", dk[i], dc[i], money(dn[i]), money(dn[i-1]), map[bool]string{true: textOf(bp, st), false: textOf(bp, st) + " " + st}[st == "ok"])
	}
	fmt.Printf("  月档 %d 对里 ok=%d；日档 %d 对里 ok=%d、no_base=%d、neg_base=%d：粒度越细空期越多，除零是主路径而不是边角情况。\n  %s 那一格：笔数 %d、净值 %s —— 有流水也可能没基数，它做分母、本期也空时除出去就是 0÷0 = NaN。\n", len(keys)-1, mok, len(dk)-1, sts["ok"], sts["no_base"], sts["neg_base"], dk[zi], dc[zi], money(dn[zi]))
	hdr(fmt.Sprintf("4. 负数期（%s 净赤）：符号朝哪个方向定都误导，改用绝对增量 + 状态位", keys[6]))
	neg, pos := divRound((nets[7]-nets[6])*10000, nets[6]), divRound((nets[7]-nets[6])*10000, abs64(nets[6]))
	fmt.Printf("  %s 净 %s → %s 净 %s；事实只有「由负转正，绝对增量 %s 元」这一句是可证的。\n  按原分母算得 %s —— 明明是转正却显示成下降；按 |分母| 算得 %s —— %s 元的转正被读成三倍增长。\n", keys[6], money(nets[6]), keys[7], money(nets[7]), signed(nets[7]-nets[6]), pct(neg), pct(pos), money(nets[7]-nets[6]))
	fmt.Printf("  定稿：state=neg_base，不渲染百分比，只渲染「%s 元 + %s」；bp=%d 留着当排序键。\n  对照组（分母为正、本期转赤是合法的）：%s→%s 上期 %s → %s，超过 -100%% 照常展示。\n", signed(nets[7]-nets[6]), label["neg_base"], bpOf(nets[6], nets[7]), keys[5], keys[6], money(nets[5]), pct(bpOf(nets[5], nets[6])))
	hdr(fmt.Sprintf("5. 响应体：环比是三个字段，不是一个百分号字符串（表 %s / 租户 %s）", tbl, fam))
	var out []map[string]any
	for i := 1; i < len(keys); i++ {
		bp, st := chainRatio(nets[i-1], nets[i])
		out = append(out, map[string]any{"family_id": fam, "period": keys[i], "net_cents": nets[i], "prev_net_cents": nets[i-1], "ratio_bp": map[bool]any{true: bp, false: nil}[st == "ok"], "ratio_text": textOf(bp, st), "ratio_state": st})
	}
	body, err := json.Marshal(map[string]any{"code": 0, "message": "ok", "data": map[string]any{"kind": KMonth, "family_timezone": famLoc.String(), "buckets": out}})
	fmt.Printf("  全量 %d 桶（不含窗首）一次序列化：err=%v，%d 字节，ratio_bp=null 的 %d 期逐行如下：\n", len(out), err, len(body), len(out)-mok)
	for _, r := range out {
		line, _ := json.Marshal(r)
		fmt.Printf("  %s\n", line)
	}
	one, _ := json.MarshalIndent(out[3], "", "  ") // 2026-05：上期（2026-04）为空的那一期
	fmt.Printf("  单桶展开 %s：\n%s\n", out[3]["period"], string(one))
	fmt.Println("  分工：SQL 侧只出整数 net_cents/txn_count（桶键与 family_id 条件见 W46 d14）；Go 侧做稠密补位 + chainRatio；\n  前端只渲染 ratio_text/ratio_state，不得拿 net_cents 再除一次——除零口径一旦出现第二份就一定会漂。\n  纪律：ratio_bp 用 *int64，没基数发 null、前端见 null 显「无对比基数」；发 0 会被读成「持平」，发 \"∞\"/\"NaN%\" 是让渲染层替数据层背锅。")
	fmt.Println("\n=== W47 d21 到此结束 ===\n明天分清两种「没有」：上期压根没有桶，和有桶但净值为 0 —— 它们在 SQL 结果集里长得一模一样。")
}

// =====================================================================
// W47 d22：空桶对齐与「上期缺失」——「上期没有桶」和「有桶但值为 0」是两回事。
// GROUP BY 只为有流水的桶吐一行：缺的那一行不会留空位，只会让后面每行左移一格。
// 三个错法各真跑一遍：①「没有」补 0 再除（当场炸）或加个 if 兜底（凭空 +100%，空月到空月也敢报翻倍）；
// ② 拿结果集的「上一行」当上期（5 月的上期变成 3 月）；③ 稀疏行按下标对齐稠密桶键（累计链整体错位）。
// 定稿：稠密补位在 Go 侧做，no_prev_bucket 与 zero_prev 各发各的 state；桶键与样例数据沿用 d13/d19，今天只用月档。
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d22
// =====================================================================
package main

import "encoding/json"
import "fmt"
import "time"
import _ "time/tzdata" // 打包时区库：家庭时区可以是任意 IANA 名（W46 d13）
import "gorm.io/driver/postgres"
import "gorm.io/gorm"
import gormlogger "gorm.io/gorm/logger"

// ---------- W46 d13/d14 的口径 + W47 d19/d21 的样例数据：照搬，不另起一套 ----------
const famTZ = "Asia/Shanghai"     // 家庭时区：来自 homeos 的家庭设置，不是请求参数（W46 d14）
const tbl = "finance_transaction" // 表名沿用 W46 d14/d16 与 W47 d19，不另起一套
const fam = "fam-A"               // 租户边界：聚合 SQL 与内存表都只装 fam-A（跨家泄露见 W46 d14）
var famLoc = mustLoad(famTZ)
var famSign = map[string]int64{"income": 1, "expense": -1, "refund": 1, "transfer": 0} // d19 的符号表，全项目只此一份
var label = map[string]string{"ok": "照常做除法", "neg_base": "上期净赤，环比不可比", "no_prev_window": "③ 上一桶在查询窗外", "no_prev_bucket": "① 上期没有桶：GROUP BY 无行", "zero_prev": "② 上期有桶但净 0：一进一出抵平"}
var openingCents = int64(2350000) // d19 的家庭期初：同一批数据必须同一个期初
var fixedNow = day0(2026, 11, 1)  // DryRun 也要固定时钟：NowFunc 飘了 SQL 就飘，两次跑必须一字不差

func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err) // 取不到时区就崩，绝不静默回落 UTC
	}
	return l
}
func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }
func mKey(t time.Time) string    { return t.In(famLoc).Format("2006-01") } // 月档桶键：与 d13/d19 同编码；SQL 侧是 to_char(...,'YYYY-MM')
func money(c int64) string {
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs64(c)/100, abs64(c)%100)
}
func signed(c int64) string { return map[bool]string{true: "+", false: ""}[c >= 0] + money(c) }
func hdr(s string)          { fmt.Printf("\n===== %s =====\n", s) }
func abs64(v int64) int64   { return map[bool]int64{true: -v, false: v}[v < 0] }
func boolInt(b bool) int    { return map[bool]int{true: 1, false: 0}[b] }
func pct(bp int64) string {
	return fmt.Sprintf("%s%d.%02d%%", map[bool]string{true: "+", false: "-"}[bp >= 0], abs64(bp)/100, abs64(bp)%100)
}
func divRound(a, b int64) int64 { // 定点进位，不用截断：理由见 d21 第 2 节
	s, q, r := int64(1-2*boolInt((a < 0) != (b < 0))), abs64(a)/abs64(b), abs64(a)%abs64(b)
	return s * (q + int64(boolInt(2*r >= abs64(b))))
}
func safecall(f func() string) (s string) { // 把 ❌ 写法真的跑一遍：崩在里面、收在外面，程序继续走完
	defer func() {
		if r := recover(); r != nil {
			s = fmt.Sprintf("panic(%v)", r)
		}
	}()
	return f()
}

// ratioOf：d21 的 no_base 在这里裂成三个 state。先判「上期在不在窗外/有没有桶」，再判「净值为 0」，最后才做除法。
func ratioOf(prev, cur int64, prevCount int) (int64, string) {
	if prevCount <= 0 || prev == 0 { // 窗首（-1，窗外查不到）／上期没桶（0）／有桶但净 0：三条都不许进除法
		return 0, map[bool]string{true: "no_prev_window", false: map[bool]string{true: "no_prev_bucket", false: "zero_prev"}[prevCount == 0]}[prevCount < 0]
	}
	return divRound((cur-prev)*10000, abs64(prev)), map[bool]string{true: "neg_base", false: "ok"}[prev < 0] // 负数期的符号口径见 d21 第 4 节
}

type Txn struct {
	ID, Kind    string
	AmountCents int64
	At          time.Time
}

func (Txn) TableName() string { return tbl }

var txns = []Txn{
	{"T-01", "income", 860000, day0(2026, 1, 5).Add(9 * time.Hour)},
	{"T-02", "expense", 230000, day0(2026, 1, 10).Add(8 * time.Hour)},
	{"T-03", "income", 860000, day0(2026, 2, 5).Add(9 * time.Hour)},
	{"T-04", "expense", 230000, day0(2026, 2, 10).Add(8 * time.Hour)},
	{"T-05", "refund", 12800, day0(2026, 2, 14).Add(11 * time.Hour)},
	{"T-06", "transfer", 500000, day0(2026, 2, 25).Add(21 * time.Hour)},
	{"T-07", "income", 860000, day0(2026, 3, 5).Add(9 * time.Hour)},
	{"T-08", "expense", 318400, day0(2026, 3, 10).Add(8 * time.Hour)},
	{"T-09", "income", 860000, day0(2026, 5, 5).Add(9 * time.Hour)},
	{"T-10", "expense", 386000, day0(2026, 5, 10).Add(8 * time.Hour)},
	{"T-11", "income", 860000, day0(2026, 6, 5).Add(9 * time.Hour)},
	{"T-12", "expense", 230000, day0(2026, 6, 10).Add(8 * time.Hour)},
	{"T-13", "refund", 200000, day0(2026, 6, 20).Add(10 * time.Hour)},
	{"T-14", "income", 860000, day0(2026, 7, 5).Add(9 * time.Hour)},
	{"T-15", "expense", 1130000, day0(2026, 7, 25).Add(3 * time.Hour)},
	{"T-16", "income", 860000, day0(2026, 8, 5).Add(9 * time.Hour)},
	{"T-17", "expense", 230000, day0(2026, 8, 10).Add(8 * time.Hour)},
	{"T-18", "income", 460000, day0(2026, 9, 5).Add(9 * time.Hour)}, // 今天新增：与 T-19 一进一出抵平
	{"T-19", "expense", 460000, day0(2026, 9, 12).Add(8 * time.Hour)},
}

// series：d19 那遍聚合原样复用，但只走稠密月序列。cnt==0 ⟺ GROUP BY 结果里没有这一行——就是「没有桶」。
func series(f, t time.Time) ([]string, []int64, []int) {
	sum, cnt := map[string]int64{}, map[string]int{}
	for _, x := range txns {
		sum[mKey(x.At)] += famSign[x.Kind] * x.AmountCents
		cnt[mKey(x.At)]++
	}
	keys := []string{}
	for cur := day0(f.Year(), int(f.Month()), 1); cur.Before(t); cur = cur.AddDate(0, 1, 0) { // 稠密：没流水的月也占一格；日历步进，不用 Add(24h)
		keys = append(keys, mKey(cur))
	}
	nets, nc := make([]int64, len(keys)), make([]int, len(keys))
	for i, key := range keys {
		nets[i], nc[i] = sum[key], cnt[key] // 空桶在这里补 0：占位而不缺席
	}
	return keys, nets, nc
}

// ---- GORM DryRun：本机无 Postgres，也要出真实 SQL（W46 d14 的口径） ----
func dryDB() *gorm.DB { // postgres.Config 只管 DSN；DisableAutomaticPing 在 gorm.Config 上——放错地方编不过
	db, err := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	if err != nil {
		panic(err)
	}
	return db
}
func aggSQL(db *gorm.DB, fam string, from, to time.Time) string { // 聚合必须带 family_id：漏了就是跨家泄露
	sel := "to_char(occurred_at AT TIME ZONE ?, 'YYYY-MM') AS bucket_key, SUM(amount_cents) AS net_cents, COUNT(*) AS txn_count"
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).Select(sel, famTZ).Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?", fam, from.Format(time.RFC3339Nano), to.Format(time.RFC3339Nano)).Group("bucket_key").Order("bucket_key").Find(&[]map[string]any{})
	})
}

func main() {
	from, to := day0(2026, 1, 1), day0(2026, 11, 1)
	keys, nets, cnt := series(from, to)
	pk := append([]string{mKey(from.AddDate(0, -1, 0))}, keys[:len(keys)-1]...) // 每格同族上一桶；窗首那格在窗外
	pc := append([]int{-1}, cnt[:len(cnt)-1]...)                                // 上一桶笔数：-1 = 窗外查不到
	pv := append([]int64{0}, nets[:len(nets)-1]...)                             // 上一桶净值：窗首那格的 0 只是占位
	sp, si, last := make([]int, len(keys)), []int{}, -1
	for i, n := range cnt {
		sp[i] = last                                                                                                      // ❌ 错法二拿它当「上期」：缺行不留空位，只会让后面整排左移
		si, last = append(si, map[bool][]int{true: {i}, false: nil}[n > 0]...), map[bool]int{true: i, false: last}[n > 0] // 本格在结果集里有行，才成为后面各行的「上一行」
	}
	hdr(fmt.Sprintf("1. 场景：%s 的 %d 笔流水（d19 原 17 笔 + 今天 T-18/T-19）落月档 %d 桶，期初 %s 元", fam, len(txns), len(keys), money(openingCents)))
	for _, x := range txns {
		fmt.Printf("  %s %-8s %8s 元 @ %s → %s 桶，家庭增量 %8s 元%s\n", x.ID, x.Kind, money(x.AmountCents), x.At.In(famLoc).Format("2006-01-02 15:04"), mKey(x.At), money(famSign[x.Kind]*x.AmountCents), map[bool]string{true: "  ← 今天新增", false: ""}[x.ID > "T-17"])
	}
	fmt.Printf("  聚合 SQL（GORM DryRun 真实生成，非手抄；WHERE 里 family_id 不能少）：\n    %s\n", aggSQL(dryDB(), fam, from, to))
	fmt.Printf("  稠密桶键 %d 格，但这条 SQL 只返回 %d 行。逐格看它属于哪种情况：\n", len(keys), len(si))
	fmt.Printf("  %-9s %-4s %-10s %-13s %-9s %-9s %s\n", "period", "笔数", "本期净", "结果集有行吗", "上一桶", "上一桶笔数", "这一格的上期是什么情况")
	for i, key := range keys {
		_, st := ratioOf(pv[i], nets[i], pc[i])
		fmt.Printf("  %-9s %-4d %-10s %-13s %-9s %-9d %s\n", key, cnt[i], money(nets[i]), map[bool]string{true: "有", false: "没有 ← 没有桶"}[cnt[i] > 0], pk[i], pc[i], label[st])
	}
	fmt.Println("  除法上「窗外/没桶/净 0」都等于 0，事实上一条都不相同：把三种压成一个数，就是今天三个错法的共同病根。")
	hdr("2. ❌ 补 0 硬除 / ❌ 补 0 + if 兜底 / ❌ 拿上一行当上期 / ✅ 判存在再判零：同 9 对相邻桶")
	fmt.Printf("  %-9s %-8s %-32s %-11s %-32s %s\n", "本期", "上期笔数", "❌ 补 0 后照除", "❌ 加 if 保护", "✅ 定稿 ratioOf", "❌ 拿结果集上一行算")
	miss, firstBad, guardBp := 0, -1, int64(10000) // ❌ 兜底分支里凭空写出来的 +100%：它不是算出来的，是编出来的
	for i := 1; i < len(keys); i++ {
		bp, st := ratioOf(pv[i], nets[i], pc[i])
		div := safecall(func() string { return fmt.Sprintf("%d bp", (nets[i]-nets[i-1])*10000/nets[i-1]) })      // ❌ 判都不判就除：上期净 0 当场炸
		spr := safecall(func() string { return pct(divRound((nets[i]-nets[sp[i]])*10000, abs64(nets[sp[i]]))) }) // ❌ 上一行自己也可能净 0
		gd := guardBp                                                                                            // ❌ 只挡 0，不挡「上期根本没有桶」
		if nets[i-1] != 0 {
			gd = (nets[i] - nets[i-1]) * 10000 / abs64(nets[i-1])
		}
		miss += boolInt(sp[i] != i-1)
		firstBad = map[bool]int{true: i, false: firstBad}[sp[i] != i-1 && firstBad < 0]
		fmt.Printf("  %-9s %-8d %-32s %-11s %-32s %s\n", keys[i], pc[i], div, pct(gd), label[st]+map[bool]string{true: " " + pct(bp), false: ""}[st == "ok"], map[bool]string{true: spr + " ← " + keys[sp[i]] + " 冒充上期", false: spr + "（上一行正好是上一桶）"}[sp[i] != i-1])
	}
	z := len(keys) - 1 // 相邻两期：z 的上期就是 z-1
	fmt.Printf("  最扎眼的是 %s→%s：两格净值都是 %s 元（上一格笔数 %d、本格笔数 %d），❌ 保护版照样报 %s——空月到空月「增长 100%%」，那个数与流水无关，是兜底分支自己写的。\n  ❌ 上一行咬住 %d/%d 期：%s 的真值是「上期没有桶」，它把 %s 当成上期（中间空了 %d 格）；%s 的上一行没咬错，但那一行净 %s，照样当场炸。\n", keys[z-1], keys[z], money(nets[z]), cnt[z-1], cnt[z], pct(guardBp), miss, len(keys)-1, keys[firstBad], keys[sp[firstBad]], firstBad-sp[firstBad], keys[z], money(nets[z-1]))
	fmt.Println("  为什么 +100% 是假事实：它把「不可比」翻译成「翻倍」，前端据此标红、排序、进趋势图，事后没人能追回。\n  除法只允许发生在判过分母之后；分母不合格就发状态位，不许拿一个百分数占位（d21 第 5 节的三字段契约）。")
	hdr("3. ❌ 错法三：稀疏行按「行号」对齐稠密桶键 —— 累计链从缺行那期起整体错位")
	cumD, cumS, s := make([]int64, len(keys)), make([]int64, 0, len(si)), openingCents
	for i := range nets {
		s += nets[i]
		cumD[i] = s // 稠密补位：空格加 0，链条不断
	}
	fmt.Printf("  %-9s %-10s %-12s %-16s %-11s %s\n", "period", "本期净", "✅ 稠密累计", "❌ 按行号对齐", "差值", "判定")
	bad, firstRow, lucky, s := 0, -1, -1, openingCents
	for j, i := range si { // SQL 的第 j 行被按位置写进第 j 期
		s += nets[i]
		cumS = append(cumS, s) // 数值本身没错，错在它是「第 j 行」而不是「第 i 期」
		bad += boolInt(i != j)
		firstRow = map[bool]int{true: j, false: firstRow}[i != j && firstRow < 0]
		lucky = map[bool]int{true: j, false: lucky}[i != j && s == cumD[j]] // 错位但差值为 0：被误并进来的那期恰好净 0
		fmt.Printf("  %-9s %-10s %-12s %-16s %-11s %s\n", keys[j], money(nets[j]), money(cumD[j]), money(s), signed(s-cumD[j]), map[bool]string{true: "对齐：SQL 第 " + fmt.Sprint(j+1) + " 行正好落在这期", false: "错位 ← 第 " + fmt.Sprint(j+1) + " 行是 " + keys[i] + " 的累计，被写成 " + keys[j]}[i == j])
	}
	for j := len(si); j < len(keys); j++ { // 稠密 10 期 / SQL 8 行：多出来的期按下标取就是越界
		bad++
		fmt.Printf("  %-9s %-10s %-12s %-16s %-11s %s\n", keys[j], money(nets[j]), money(cumD[j]), fmt.Sprintf("（SQL 只有 %d 行，取不到第 %d 行）", len(si), j+1), "—", "越界 ← 页脚只能留空或复用上一格")
	}
	fmt.Printf("  错位或取不到 %d/%d 期：%s 一笔流水都没有，累计却被写成 %s 元——那是 %s 的累计（多算了它的本期净值 %s）。前端拿这列画曲线，整条链从缺行那期起整体左移。\n  最阴的一行是 SQL 第 %d 行：差值 %s 看着完全对齐，其实它是 %s 的累计——只因那一期本期净 %s，错位的差额被抵消掉了。运气不是正确性。\n", bad, len(keys), keys[firstRow], money(cumS[firstRow]), keys[si[firstRow]], money(nets[si[firstRow]]), lucky+1, signed(cumS[lucky]-cumD[lucky]), keys[si[lucky]], money(nets[si[lucky]]))
	hdr(fmt.Sprintf("4. ✅ 定稿：Go 侧稠密补位，几种「没有」各发各的 state（表 %s / 租户 %s）", tbl, fam))
	out, kinds, noBucketEx, zeroEx := []map[string]any{}, map[string]int{}, -1, -1
	for i := 1; i < len(keys); i++ {
		bp, st := ratioOf(pv[i], nets[i], pc[i])
		kinds[st]++
		noBucketEx, zeroEx = map[bool]int{true: len(out), false: noBucketEx}[st == "no_prev_bucket" && noBucketEx < 0], map[bool]int{true: len(out), false: zeroEx}[st == "zero_prev" && zeroEx < 0]
		out = append(out, map[string]any{"family_id": fam, "period": keys[i], "kind": "month", "prev_period": pk[i], "prev_bucket_exists": pc[i] > 0, "txn_count": cnt[i], "prev_txn_count": pc[i], "net_cents": nets[i], "prev_net_cents": pv[i], "cum_cents": cumD[i], "cum_method": "server_prefix_sum", "ratio_bp": map[bool]any{true: bp, false: nil}[st == "ok"], "ratio_text": map[bool]string{true: pct(bp), false: label[st]}[st == "ok"], "ratio_state": st})
	}
	body, err := json.Marshal(map[string]any{"code": 0, "message": "ok", "data": map[string]any{"family_timezone": famTZ, "dense_buckets": len(keys), "sql_rows": len(si), "buckets": out}})
	fmt.Printf("  全量序列化：err=%v，%d 字节，稠密 %d 格 / SQL %d 行，状态分布 %v\n", err, len(body), len(keys), len(si), kinds)
	for _, i := range []int{noBucketEx, zeroEx} { // 两种「没有」各展开一期：下标是上面按 state 现挑的，不是数出来的
		one, _ := json.MarshalIndent(out[i], "", "  ")
		fmt.Printf("  单桶展开 %s（%s）：\n%s\n", out[i]["period"], out[i]["ratio_state"], string(one))
	}
	fmt.Println("  分工：SQL 只管 GROUP BY（它不知道什么是空桶）；补位、判「有没有桶」、判分母，全在 Go 侧这一份代码里；\n  前端只渲染 ratio_text/ratio_state，不得自己按数组下标找上期、不得把 null 画成 0%。\n  纪律：prev_bucket_exists 必须与 prev_net_cents 一起发——只发净值不发存在位，接收方就会把「没有」当成 0。")
	fmt.Println("\n=== W47 d22 到此结束 ===\n明天动历史：一笔红冲改的是 3 月，但 4/5/6 月的累计值会跟着整链重算。")
}

// =====================================================================
// W47 d23：红冲 / 改历史期 —— 一笔改在 3 月，4、5、6… 月的累计值必须整链位移。
// 累计余额是前缀和：历史期一旦变动，它之后每一期的 cum 都跟着变，「只改当期」这种操作不存在。
// 三种错法各真跑一遍：① 原地 UPDATE 历史单金额（期末能与新聚合对上，但旧值查无出处、笔数不变）；
// ② 只把差额打进取当期那一格、后面各期沿用旧累计（期末与账户余额整整差一个 delta）；
// ③ 网络重试把同一笔红冲提交两遍且库里没有唯一键拦（delta 被加两次，整条后缀等量偏移）。
// 定稿：红冲+重录都是「追加」，重算只重算受影响后缀（增量法与全量法逐期 diff 必须全 0）；
// 已关账期不许回溯，红冲落当期——期末相同、期间归属不同，这个口径必须写进判据，不能让聚合层猜。
// 桶键 / 符号表 / 样例流水沿用 d19、d21、d22（今天新增 T-20/T-21 两张冲销单）。
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d23
// =====================================================================
package main

import "encoding/json"
import "fmt"
import "time"
import _ "time/tzdata" // 打包时区库：家庭时区可以是任意 IANA 名（W46 d13）
import "gorm.io/driver/postgres"
import "gorm.io/gorm"
import gormlogger "gorm.io/gorm/logger"
import "gorm.io/gorm/clause"

// ---------- W46 d13 的月档桶键 + W47 d19/d21 的样例数据与符号表：照搬，不另起一套 ----------
const famTZ = "Asia/Shanghai"
const tbl = "finance_transaction" // 表名沿用 W46 d14/d16 与 W47 d19，不另起一套
const fam = "fam-A"               // 租户边界：聚合、追加、UPDATE 的条件里 family_id 一个都不能少
const wrongCents, rightCents = int64(318400), int64(118400)

var famLoc = mustLoad(famTZ)
var famSign = map[string]int64{"income": 1, "expense": -1, "refund": 1, "transfer": 0} // d19 的符号表，全项目只此一份
var mark = map[bool]string{true: "✅ 对齐", false: "❌ 断链"}                                // d19 的判定词：同一条链同一套话
var revOf = map[string]string{"T-20": "T-08", "T-21": "T-08-RE"}                       // 幂等键：红冲指回原单，重录指回原单的重录位
var openingCents = int64(2350000)                                                      // d19 的家庭期初：同一批数据必须同一个期初
var fixedNow = day0(2026, 11, 1)                                                       // DryRun 也要固定时钟：NowFunc 飘了 SQL 就飘

func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err) // 取不到时区就崩，绝不静默回落 UTC
	}
	return l
}
func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }
func at(m int) time.Time         { return day0(2026, m, 10).Add(8 * time.Hour) } // 同一张单落在哪一期：桶键由它决定
func mKey(t time.Time) string    { return t.In(famLoc).Format("2006-01") }
func money(c int64) string {
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs64(c)/100, abs64(c)%100)
}
func signed(c int64) string { return map[bool]string{true: "+", false: ""}[c >= 0] + money(c) }
func hdr(s string)          { fmt.Printf("\n===== %s =====\n", s) }
func abs64(v int64) int64   { return map[bool]int64{true: -v, false: v}[v < 0] }
func boolInt(b bool) int    { return map[bool]int{true: 1, false: 0}[b] }
func pct(bp int64) string {
	return fmt.Sprintf("%s%d.%02d%%", map[bool]string{true: "+", false: "-"}[bp >= 0], abs64(bp)/100, abs64(bp)%100)
}
func divRound(a, b int64) int64 { // 定点进位，不用截断：理由见 d21 第 2 节
	s, q, r := int64(1-2*boolInt((a < 0) != (b < 0))), abs64(a)/abs64(b), abs64(a)%abs64(b)
	return s * (q + int64(boolInt(2*r >= abs64(b))))
}
func ratioOf(prev, cur int64) (int64, string) { // d21 的 chainRatio：分母不合格就不进除法
	return map[bool]int64{true: divRound((cur-prev)*10000, abs64(prev)), false: 0}[prev != 0], map[bool]string{true: map[bool]string{true: "neg_base", false: "ok"}[prev < 0], false: "no_base"}[prev != 0]
}
func idxOf(keys []string, want string) int { // 下标由桶键查出来，不靠手数
	for i, k := range keys {
		if k == want {
			return i
		}
	}
	panic("桶键 " + want + " 不在稠密序列里")
}

type Txn struct {
	ID, Kind    string
	AmountCents int64
	At          time.Time `gorm:"column:occurred_at"`
}

func (Txn) TableName() string { return tbl }

var txns = []Txn{
	{"T-01", "income", 860000, day0(2026, 1, 5).Add(9 * time.Hour)},
	{"T-02", "expense", 230000, day0(2026, 1, 10).Add(8 * time.Hour)},
	{"T-03", "income", 860000, day0(2026, 2, 5).Add(9 * time.Hour)},
	{"T-04", "expense", 230000, day0(2026, 2, 10).Add(8 * time.Hour)},
	{"T-05", "refund", 12800, day0(2026, 2, 14).Add(11 * time.Hour)},
	{"T-06", "transfer", 500000, day0(2026, 2, 25).Add(21 * time.Hour)},
	{"T-07", "income", 860000, day0(2026, 3, 5).Add(9 * time.Hour)},
	{"T-08", "expense", 318400, day0(2026, 3, 10).Add(8 * time.Hour)}, // ← 今天发现的错单：支出录重了 2000.00 元
	{"T-09", "income", 860000, day0(2026, 5, 5).Add(9 * time.Hour)},
	{"T-10", "expense", 386000, day0(2026, 5, 10).Add(8 * time.Hour)},
	{"T-11", "income", 860000, day0(2026, 6, 5).Add(9 * time.Hour)},
	{"T-12", "expense", 230000, day0(2026, 6, 10).Add(8 * time.Hour)},
	{"T-13", "refund", 200000, day0(2026, 6, 20).Add(10 * time.Hour)},
	{"T-14", "income", 860000, day0(2026, 7, 5).Add(9 * time.Hour)},
	{"T-15", "expense", 1130000, day0(2026, 7, 25).Add(3 * time.Hour)},
	{"T-16", "income", 860000, day0(2026, 8, 5).Add(9 * time.Hour)},
	{"T-17", "expense", 230000, day0(2026, 8, 10).Add(8 * time.Hour)},
}

// 红冲 = 追加一张反向单（reversal_of 指回原单），重录 = 再追加一张正确单。两张都不碰历史单。
var pair = []Txn{{"T-20", "refund", wrongCents, at(3)}, {"T-21", "expense", rightCents, at(3)}}

// ledger：同一个错的四种处理法。0 改前 / 1 ✅ 红冲落原期 / 2 ❌ 原地 UPDATE / 3 已关账口径（落当期）/ 4 ❌ 重试提交两遍
func ledger(m int) []Txn {
	l := append([]Txn{}, txns...)
	if m == 2 { // ❌ 就地改掉历史单：改前的金额从此在这套系统里查无出处
		for i := range l {
			if l[i].ID == "T-08" {
				l[i].AmountCents = rightCents
			}
		}
		return l
	}
	if m == 0 {
		return l
	}
	d := map[int]time.Time{1: at(3), 3: at(9), 4: at(3)}[m]
	for _, x := range pair {
		y := x
		y.At = d
		l = append(l, y)
		if m == 4 {
			l = append(l, y) // ❌ 客户端重试的第二遍：没有 (family_id, reversal_of) 唯一键它就进得来
		}
	}
	return l
}

// series：d19 那遍聚合原样复用（先按桶键求和，再按稠密月序列补 0），只是流水集合换了版本。
func series(l []Txn) ([]string, []int64, []int) {
	sum, cnt := map[string]int64{}, map[string]int{}
	for _, x := range l {
		sum[mKey(x.At)] += famSign[x.Kind] * x.AmountCents
		cnt[mKey(x.At)]++
	}
	keys := []string{}
	for cur := day0(2026, 1, 1); cur.Before(day0(2026, 11, 1)); cur = cur.AddDate(0, 1, 0) { // 稠密：空月也占格；日历步进，不用 Add(24h)
		keys = append(keys, mKey(cur))
	}
	nets, nc := make([]int64, len(keys)), make([]int, len(keys))
	for i, key := range keys {
		nets[i], nc[i] = sum[key], cnt[key] // 空桶在这里补 0：占位而不缺席
	}
	return keys, nets, nc
}
func cumOf(nets []int64) []int64 { // 期初 + 前缀和：整条链一次算完，压根没有「只算当期」这一步
	out, run := make([]int64, len(nets)), openingCents
	for i, n := range nets {
		run += n
		out[i] = run
	}
	return out
}
func diffRows(keys []string, a, b []int64, ha, hb string) (int, int64) { // 逐期 diff：真做、真印，不是一句「已对齐」
	fmt.Printf("  %-9s %-12s %-12s %-11s %s\n", "period", ha, hb, "diff", "判定")
	bad, last := 0, int64(0)
	for i := range keys {
		d := b[i] - a[i]
		bad, last = bad+boolInt(d != 0), d
		fmt.Printf("  %-9s %-12s %-12s %-11s %s\n", keys[i], money(a[i]), money(b[i]), signed(d), mark[d == 0])
	}
	return bad, last
}

// ---- GORM DryRun：本机无 Postgres，也要出真实 SQL（W46 d14 的口径） ----
func dryDB() *gorm.DB { // postgres.Config 只管 DSN；DisableAutomaticPing 在 gorm.Config 上——放错地方编不过
	db, err := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	if err != nil {
		panic(err)
	}
	return db
}
func aggSQL(db *gorm.DB) string { // 聚合只带 family_id + 时间窗：它不知道什么是空桶，更不该知道什么是红冲
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).Select("to_char(occurred_at AT TIME ZONE ?, 'YYYY-MM') AS bucket_key, SUM(amount_cents) AS net_cents, COUNT(*) AS txn_count", famTZ).Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?", fam, day0(2026, 1, 1).Format(time.RFC3339Nano), day0(2026, 11, 1).Format(time.RFC3339Nano)).Group("bucket_key").Order("bucket_key").Find(&[]map[string]any{})
	})
}
func appendSQL(db *gorm.DB) string { // ✅ 追加两张单：ON CONFLICT 让「同一笔红冲提交两遍」在库里就变成 no-op
	rows := []map[string]any{{"family_id": fam, "id": pair[0].ID, "kind": pair[0].Kind, "amount_cents": pair[0].AmountCents, "occurred_at": pair[0].At, "reversal_of": revOf[pair[0].ID]}, {"family_id": fam, "id": pair[1].ID, "kind": pair[1].Kind, "amount_cents": pair[1].AmountCents, "occurred_at": pair[1].At, "reversal_of": revOf[pair[1].ID]}}
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Table(tbl).Model(&Txn{}).Clauses(clause.OnConflict{Columns: []clause.Column{{Name: "family_id"}, {Name: "reversal_of"}}, DoNothing: true}).Create(rows)
	})
}
func updateSQL(db *gorm.DB) string { // ❌ 就是这条语句把历史抹平的
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).Where("family_id = ? AND id = ?", fam, "T-08").Update("amount_cents", rightCents)
	})
}

func main() {
	keys, nets0, cnt0 := series(ledger(0))
	_, netsOK, cntOK := series(ledger(1))
	_, nets2, cnt2 := series(ledger(2))
	_, nets3, _ := series(ledger(3))
	_, nets4, _ := series(ledger(4))
	cum0, cumOK, cum2, cum3, cum4 := cumOf(nets0), cumOf(netsOK), cumOf(nets2), cumOf(nets3), cumOf(nets4)
	i0, i3, last := idxOf(keys, "2026-03"), idxOf(keys, mKey(at(9))), len(keys)-1
	delta := wrongCents - rightCents // 更正带来的家庭侧净位移：expense 录重了，往回补
	hdr(fmt.Sprintf("1. 场景：%s 的 %d 笔流水（d19 原表）+ T-08 这笔支出录成 %s 元、应为 %s 元；月档 %d 桶，期初 %s 元", fam, len(txns), money(wrongCents), money(rightCents), len(keys), money(openingCents)))
	fmt.Printf("  更正动作是「追加两张单」，不是「改一张单」：%s 红冲 T-08（落 %s 桶）+ %s 重录正确金额（落同一桶）\n", pair[0].ID, mKey(pair[0].At), pair[1].ID)
	fmt.Printf("  单期净位移 delta = 红冲腿 %s + 重录腿 %s = %s 元，即录错金额 %s − 正确金额 %s；它对 %s 之后的每一期累计都有效，不止 %s 这一期。\n", money(famSign["refund"]*wrongCents), money(famSign["expense"]*rightCents), money(famSign["refund"]*wrongCents+famSign["expense"]*rightCents), money(wrongCents), money(rightCents), keys[i0], keys[i0])
	fmt.Printf("  聚合 SQL（GORM DryRun 真实生成；WHERE 里 family_id 不能少）：\n    %s\n  ✅ 追加 SQL（重试幂等靠它，见第 4 节）：\n    %s\n", aggSQL(dryDB()), appendSQL(dryDB()))
	fmt.Printf("  %-9s %-4s %-11s %-11s %s\n", "period", "笔数", "改前 net", "改前 cum", "检查：cum − 期初 = Σnet 到本期")
	for i, k := range keys {
		fmt.Printf("  %-9s %-4d %-11s %-11s %s\n", k, cnt0[i], money(nets0[i]), money(cum0[i]), money(cum0[i]-openingCents))
	}
	hdr("2. ❌ 错法一：原地 UPDATE 历史单金额（改得动数字，改不动历史）")
	fmt.Printf("  这条语句真的跑得通、期末也真的对得上新聚合：\n    %s\n", updateSQL(dryDB()))
	fmt.Printf("  %-9s %-4s %-4s %-11s %-11s %-11s %s\n", "period", "旧笔", "新笔", "旧 net", "新 net", "net 差", "有没有留下改动的痕迹")
	for i, k := range keys {
		fmt.Printf("  %-9s %-4d %-4d %-11s %-11s %-11s %s\n", k, cnt0[i], cnt2[i], money(nets0[i]), money(nets2[i]), signed(nets2[i]-nets0[i]), map[bool]string{true: map[bool]string{true: "笔数不变 ← 金额凭啥变？看的人只能猜", false: "未受影响"}[nets2[i] != nets0[i]], false: "笔数变了"}[cnt2[i] == cnt0[i]])
	}
	bad2, last2 := diffRows(keys, cumOK, cum2, "✅ 红冲 cum", "❌ UPDATE cum")
	fmt.Printf("  两条链逐期 diff：非 0 %d 处、末期差 %s 元——期末值一模一样，「对一下余额」根本查不出它。\n  查得出来的是：改前那份响应体（%s 的 net_cents=%d、cum_cents=%d）从此在任何库里都复现不出来，导出文件、缓存、审计全部悬空；红冲版同一期笔数 %d→%d，改动自己带着证据。\n", bad2, money(last2), keys[i0], nets0[i0], cum0[i0], cnt0[i0], cntOK[i0])
	hdr("3. ❌ 错法二：只把差额打进取当期那一格，后面各期沿用旧累计")
	patch := append([]int64{}, cum0...)
	patch[i0] += delta // ❌「改当期」：只动 %s 这一格，后面的 cum 还是老链
	bad3, last3 := diffRows(keys, cumOK, patch, "✅ 整链 cum", "❌ 补丁 cum")
	ending := openingCents
	for _, n := range netsOK {
		ending += n
	}
	fmt.Printf("  前 %d 期 diff 全 0（%s 及之前确实对），从 %s 起整段偏移：非 0 %d 期、末期差 %s 元。\n  账户余额 = 期初 %s + Σ改后 net = %s 元；❌ 补丁链末值只有 %s 元——「期末值对不上账户余额」差的正是 delta %s 元，不是四舍五入。\n", i0+1, keys[i0], keys[i0+1], bad3, money(last3), money(openingCents), money(ending), money(patch[last]), money(delta))
	hdr("4. ✅ 定稿：只重算受影响后缀（增量法），并与全量重算逐期对齐；重试由唯一键挡下")
	inc := append([]int64{}, cumOK[:i0]...) // 前缀原样搬过来：它们与这次改动无关
	run := cumOK[i0-1]
	for i := i0; i < len(keys); i++ {
		run += netsOK[i]
		inc = append(inc, run)
	}
	bad4, last4 := diffRows(keys, cumOK, inc, "✅ 全量重算", "✅ 增量重算")
	seen, dup := map[string]bool{}, []string{}
	for _, x := range ledger(4) {
		if _, ok := revOf[x.ID]; !ok {
			continue
		}
		k := fam + "/" + revOf[x.ID] // 唯一键 (family_id, reversal_of)：库里挡重试就靠它，不靠「前端别重复点」
		if seen[k] {
			dup = append(dup, k)
			continue
		}
		seen[k] = true
	}
	fmt.Printf("  增量法非 0 %d 处、末期差 %s 元：改 %s 只要重算 %d 期后缀，但必须一路重算到 %s——半条链不动就是错链。\n", bad4, money(last4), keys[i0], len(keys)-i0, keys[last])
	fmt.Printf("  第 4 种情形（重试两遍）共 %d 张冲销单进账，唯一键挡下 %d 次（%v），实际入账 %d 张；若库里没这个键，2×delta 会把期末推到 %s 元，比定稿多 %s 元。\n", len(ledger(4))-len(txns), len(dup), dup, len(seen), money(cum4[last]), money(cum4[last]-cumOK[last]))
	fmt.Printf("  没拦住的链与定稿链 diff：从 %s 起 %d 期每期差 %s 元——幂等不是防重复点击，是防整条累计后缀等量偏移。\n", keys[i0], len(keys)-i0, money(cum4[i0]-cumOK[i0]))
	hdr("5. 已关账就回溯不了：红冲落原期 vs 落当期，期末相同、期间归属不同")
	fmt.Printf("  %-9s %-11s %-11s %-11s %-11s %s\n", "period", "✅ 落原期 net", "✅ cum", "已关账 net", "已关账 cum", "两口径关系")
	for i, k := range keys {
		fmt.Printf("  %-9s %-11s %-11s %-11s %-11s %s\n", k, money(netsOK[i]), money(cumOK[i]), money(nets3[i]), money(cum3[i]), map[bool]string{true: map[bool]string{true: "同期同值", false: "本期被更正单改动，cum 一起位移"}[cum3[i] == cumOK[i]], false: "期末追平、期间不同 ← 中间那段曲线是两条"}[nets3[i] == netsOK[i]])
	}
	bpA, stA := ratioOf(netsOK[i3-1], netsOK[i3])
	bpB, stB := ratioOf(nets3[i3-1], nets3[i3])
	fmt.Printf("  同一笔更正，两种落法在 %s 这期的环比：落原期 = %s(%s)、落当期 = %s(%s)；期末余额却都是 %s 元。\n  纪律：落哪一期由「该期是否关账」决定，这个状态在服务端有一份，绝不让聚合层猜——未关账 → 回溯重算后缀；已关账 → 追加到当期并在 %s 之后的报表里带更正说明。历史上那个错值 %s 元永远留在 %s。\n", keys[i3], map[bool]string{true: pct(bpA), false: stA}[stA == "ok"], stA, map[bool]string{true: pct(bpB), false: stB}[stB == "ok"], stB, money(cum3[last]), keys[i3], money(nets0[i0]), keys[i0])
	hdr("6. 收口：改历史期必须写进协议的几行")
	body, err := json.Marshal(map[string]any{"code": 0, "message": "ok", "data": map[string]any{"family_id": fam, "kind": "month", "family_timezone": famTZ, "opening_cents": openingCents, "recalculated_from": keys[i0], "affected_periods": len(keys) - i0, "revision": 2, "buckets": []map[string]any{{"period": keys[i0], "net_cents": netsOK[i0], "cum_cents": cumOK[i0], "txn_count": cntOK[i0], "reversal_of": revOf[pair[0].ID]}}}})
	fmt.Printf("  最小响应体（err=%v，%d 字节，%d 期受影响、delta %s 元全部由上面几节算出来）：\n%s\n", err, len(body), len(keys)-i0, money(delta), string(body))
	fmt.Println("  · 改历史期 = 追加红冲 + 追加正确单，绝不 UPDATE 原单金额：原单是事实，错了也要留着当证据")
	fmt.Println("  · reversal_of + (family_id, reversal_of) 唯一键：幂等落在库里，重试第二遍在 SQL 层就是 no-op")
	fmt.Println("  · recalculated_from = 最早被改动的桶键：该桶之后的 cum 全部重算，之前的原样搬（增量法与全量法逐期 diff 必须为 0）")
	fmt.Println("  · 关账状态决定红冲落哪一期：未关账回溯、已关账落当期，两者期末相同期间不同——口径由服务端发（PRD 4.5.3）")
	fmt.Println("  · 前端不许改历史：它拿到的 cum_cents 只用于展示与自检，二次累加逐期 diff 仍须为 0（d19，明天 d24 收口）")
	fmt.Println("\n=== W47 d23 到此结束 ===\n明天把 d19〜d23 的判据一次跑完：服务端逐期累加 vs 前端二次累加，差值逐期真 diff，全 0 才算过。")
}

