func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err) // 取不到时区就崩，绝不静默回落 UTC
	}
	return l
}
func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }
func bucketStart(k Kind, t time.Time) time.Time { // 桶起点：月初 / 季初，取家庭时区墙上 00:00（d13/d19）
	l := t.In(famLoc)
	return map[Kind]time.Time{KMonth: day0(l.Year(), int(l.Month()), 1), KQuarter: day0(l.Year(), (int(l.Month())-1)/3*3+1, 1)}[k]
}
func bucketEnd(k Kind, t time.Time) time.Time { // 排他终点：查询永远是 >= start AND < end
	return bucketStart(k, t).AddDate(step[k][0], step[k][1], step[k][2]) // 步进用日历量，不用 Add(24h)
}
func bucketKey(k Kind, t time.Time) string { // PRD 4.5.3 定版编码，只有这一种：month=YYYY-MM、quarter=YYYY-Qn
	l := t.In(famLoc)
	return map[Kind]string{KMonth: l.Format("2006-01"), KQuarter: fmt.Sprintf("%04d-Q%d", l.Year(), (int(l.Month())-1)/3+1)}[k]
}
func bucketKeys(k Kind, f, t time.Time) []string { // 一个窗 → 稠密桶键序列：没流水的期也占一格
	var out []string
	for cur := bucketStart(k, f); cur.Before(t); cur = bucketEnd(k, cur) {
		out = append(out, bucketKey(k, cur))
	}
	return out
}
func money(c int64) string { // 分 → 元.角分：纯整数格式化，聚合与展示链路上都不出现浮点
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs64(c)/100, abs64(c)%100)
}
func signed(c int64) string { return map[bool]string{true: "+", false: ""}[c >= 0] + money(c) }
func hdr(s string)          { fmt.Printf("\n===== %s =====\n", s) }
func abs64(v int64) int64   { return map[bool]int64{true: -v, false: v}[v < 0] }
func boolInt(b bool) int    { return map[bool]int{true: 1, false: 0}[b] }
func verdict(b bool) string { return map[bool]string{true: "✅ 通过", false: "❌ 未通过"}[b] }
func pct(bp int64) string {
	return map[bool]string{true: "+", false: "-"}[bp >= 0] + fmt.Sprintf("%d.%02d%%", abs64(bp)/100, abs64(bp)%100)
}
func divRound(a, b int64) int64 { // 定点进位，不用截断：理由见 d21 第 2 节
	s, q, r := int64(1-2*boolInt((a < 0) != (b < 0))), abs64(a)/abs64(b), abs64(a)%abs64(b)
	return s * (q + int64(boolInt(2*r >= abs64(b))))
}
func ratioOf(prev, cur int64, prevCount int) (int64, string) { // d22 的 ratioOf：先判窗外/有没有桶，再判净 0，最后才除
	// 三条「不能比」各自 return：写成一行 map 的话，两个分支都会被求值，除法照旧在 prev==0 那格炸（Go 不短路）
	if prevCount < 0 || prevCount == 0 || prev == 0 {
		return 0, map[bool]string{true: "no_prev_window", false: map[bool]string{true: "no_prev_bucket", false: "zero_prev"}[prevCount == 0]}[prevCount < 0]
	}
	return divRound((cur-prev)*10000, abs64(prev)), map[bool]string{true: "neg_base", false: "ok"}[prev < 0]
}
func caseOf(prev, cur int64, pc int) string { // 情形由输入判出来，不是给每行手写一个名字
	return map[bool]string{true: "窗首：上一桶在查询窗外", false: map[bool]string{true: "A 上期缺桶：GROUP BY 无行", false: map[bool]string{true: "B 上期为 0：有流水但净 0", false: map[bool]string{true: map[bool]string{true: "D 两期同为负", false: "E 上期负、本期转正"}[cur < 0], false: map[bool]string{true: "C 本期为负（上期为正）", false: "常规：两期同为正"}[cur < 0]}[prev < 0]}[prev == 0]}[pc == 0]}[pc < 0]
}
func safecall(f func() string) (s string) { // 把 ❌ 写法真的跑一遍：崩在里面、收在外面，程序继续走完
	defer func() {
		if r := recover(); r != nil {
			s = fmt.Sprintf("panic(%v)", r)
		}
	}()
	return f()
}
func sortedKeys[V any](m map[string]V) []string { // 并发结果 / JSON 的 map 遍历：先取 key 排序，到达顺序不参与输出
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}
func fill[V any](m map[string]V, ks []string, vs []V) { // goroutine 里只干这一件事：结果按桶键进 map，等 wait 完再排序打印
	for i, k := range ks {
		m[k] = vs[i]
	}
}
func zeros(nets []int64, cnt []int) (empty, zeroNet, zeroHas int) { // 三种「零」各数各的：empty=没桶、zeroHas=有桶但净 0
	for i := range nets {
		empty += boolInt(cnt[i] == 0)
		zeroNet += boolInt(nets[i] == 0)
		zeroHas += boolInt(nets[i] == 0 && cnt[i] > 0)
	}
	return
}

