var pair = []Txn{{"T-20", "refund", wrongCents, day0(2026, 3, 10).Add(8 * time.Hour)}, {"T-21", "expense", rightCents, day0(2026, 3, 10).Add(8 * time.Hour)}}
var revOf = map[string]string{"T-20": "T-08", "T-21": "T-08-RE"}

// series：d19 那遍聚合原样复用（先按桶键求和，再按稠密桶序列补 0）。cnt==0 ⟺ SQL 里没有这一行 = 没有桶。
func series(k Kind, l []Txn, f, t time.Time) ([]string, []int64, []int) {
	sum, cnt := map[string]int64{}, map[string]int{}
	for _, x := range l {
		sum[bucketKey(k, x.At)] += famSign[x.Kind] * x.AmountCents // 符号表查不到 → 静默返 0，不报错（d19）
		cnt[bucketKey(k, x.At)]++
	}
	keys := bucketKeys(k, f, t)
	nets, nc := make([]int64, len(keys)), make([]int, len(keys))
	for i, key := range keys {
		nets[i], nc[i] = sum[key], cnt[key] // 空桶在这里补 0：占位而不缺席
	}
	return keys, nets, nc
}
func prefix(row []int64, start int64) []int64 { // A 路：期初 + 逐期净值的前缀和；空期 += 0，原地不动
	out, run := make([]int64, len(row)), start
	for i, n := range row {
		run += n
		out[i] = run
	}
	return out
}
func shift(keys []string, nets []int64, cnt []int) ([]string, []int64, []int) { // 同族上一桶：窗首那格 pc=-1 表示窗外查不到
	return append([]string{"—（窗外）"}, keys[:len(keys)-1]...), append([]int64{0}, nets[:len(nets)-1]...), append([]int{-1}, cnt[:len(cnt)-1]...)
}
func balance(l []Txn) int64 { // 账户余额的独立算法：直接遍历流水，不经过桶、不经过前缀和（第 4 节拿它对账）
	run := openingCents
	for _, x := range l {
		run += famSign[x.Kind] * x.AmountCents
	}
	return run
}

// ---------- B 路：服务端只发单期值，累加交给「前端」 ----------
type Bucket struct {
	Period   string `json:"period"`
	NetCents int64  `json:"net_cents"`
}
type Payload struct {
	FamilyID       string   `json:"family_id"`
	Kind           Kind     `json:"kind"`
	FamilyTimezone string   `json:"family_timezone"`
	OpeningCents   int64    `json:"opening_cents"` // 缺了它整条链等量下移（d19 崩法 A）
	Buckets        []Bucket `json:"buckets"`
}

func toBuckets(keys []string, nets []int64) []Bucket {
	out := make([]Bucket, len(keys))
	for i := range keys {
		out[i] = Bucket{keys[i], nets[i]}
	}
	return out
}

// frontendCum：这就是「前端」。下面三行逐字等价于前端 TS 会写的那几行——
//
//	let run = payload.opening_cents; const cum = [];
//	for (const b of payload.buckets) { run += b.net_cents; cum.push(run); }
//
// 纪律（d19）：算出来的 cum 只进自检断言，渲染永远用服务端发的 cum_cents。
func frontendCum(p Payload) []int64 {
	out, run := make([]int64, 0, len(p.Buckets)), p.OpeningCents
	for _, b := range p.Buckets {
		run += b.NetCents
		out = append(out, run)
	}
	return out
}

// badDrop 坏法①：翻页只取到上一页，最后一期整格丢掉。—— 坏在 p.Buckets[:len-1] 这半行 + 下面那行「复用上一格」。
func badDrop(p Payload) []int64 {
	out, run := []int64{}, p.OpeningCents
	for _, b := range p.Buckets[:len(p.Buckets)-1] { // ❌ 最后一期压根没进循环
		run += b.NetCents
		out = append(out, run)
	}
	return append(out, out[len(out)-1]) // ❌ 长度凑齐了，末期填的却是上一格的 cum：页脚看着有数，数是旧的
}

// badFilter 坏法②：把 net_cents==0 的格子当「没有这一期」滤掉，剩下的按下标接着算 cum 与环比。
// —— 坏在 continue 那一行：它同时滤掉了「空桶」（2026-04）和「有流水但净 0」（2026-09），两种「没有」被压成一个条件。
func badFilter(p Payload) ([]string, []int64) {
	ks, cum, run := []string{}, []int64{}, p.OpeningCents
	for _, b := range p.Buckets {
		if b.NetCents == 0 {
			continue // ❌ 空桶是「有这一期、本期 0」，不是「没有这一期」：滤掉它，后面每格左移一位
		}
		run += b.NetCents
		ks, cum = append(ks, b.Period), append(cum, run)
	}
	return ks, cum
}

// badGrade 坏法③：切到季档不整段重算。—— 坏在 run := seed 那一行：seed 用的是月档末期。
func badGrade(qn []int64, seed int64) []int64 {
	out, run := make([]int64, len(qn)), seed
	for i, n := range qn {
		run += n
		out[i] = run // ❌ 起点已经是「期初 + 全窗 Σnet」，再把同一批 net 加第二遍
	}
	return out
}

// diffTable：逐期 diff 真做、真印（返回非 0 处数、max|diff| 分、末期差）。
func diffTable(keys []string, server, client []int64, tag string) (int, int64, int64) {
	bad, mx, last := 0, int64(0), int64(0)
	fmt.Printf("  %-9s %-12s %-12s %-11s %s\n", "period", "✅ A 服务端 cum", "❌ B "+tag, "diff", "判定")
	for i := range keys {
		if i >= len(client) {
			bad++
			fmt.Printf("  %-9s %-12s %-12s %-11s %s\n", keys[i], money(server[i]), "（前端数组到头）", "—", "缺格 ← 少一行，页脚只能空着或复用上一格")
			continue
		}
		d := client[i] - server[i]
		bad, last = bad+boolInt(d != 0), d
		mx = map[bool]int64{true: abs64(d), false: mx}[abs64(d) > mx]
		fmt.Printf("  %-9s %-12s %-12s %-11s %s\n", keys[i], money(server[i]), money(client[i]), signed(d), mark[d == 0])
	}
	return bad, mx, last
}

