func aggSQL(db *gorm.DB, k Kind, from, to time.Time) string { // 聚合只带 family_id + 时间窗：它不知道什么是空桶
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).Select("to_char(occurred_at AT TIME ZONE ?, ?) AS bucket_key, SUM(amount_cents) AS net_cents, COUNT(*) AS txn_count", famTZ, map[Kind]string{KMonth: "YYYY-MM", KQuarter: "YYYY-\"Q\"Q"}[k]).Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?", fam, from.Format(time.RFC3339Nano), to.Format(time.RFC3339Nano)).Group("bucket_key").Order("bucket_key").Find(&[]map[string]any{})
	})
}
func exportSQL(db *gorm.DB, kinds []string, days, limit int) string { // W48 明细取数：type/days/format 三参数全生效 + 全员数据（PRD 4.5.3）
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Table(tbl).Select("id", "family_id", "member_id", "account_id", "category_id", "kind", "amount_cents", "reversal_of", "occurred_at", "created_by").Where("family_id = ? AND deleted_at IS NULL AND kind IN ? AND occurred_at >= ? AND occurred_at < ?", fam, kinds, fixedNow.AddDate(0, 0, -days).Format(time.RFC3339Nano), fixedNow.Format(time.RFC3339Nano)).Order("occurred_at, id").Limit(limit).Find(&[]map[string]any{})
