}
func appendSQL(db *gorm.DB) string { // ✅ 追加两张冲销单：(family_id, reversal_of) 唯一键让重试第二遍在库里就是 no-op
	rows := []map[string]any{{"family_id": fam, "id": pair[0].ID, "kind": pair[0].Kind, "amount_cents": pair[0].AmountCents, "occurred_at": pair[0].At, "reversal_of": revOf[pair[0].ID]}, {"family_id": fam, "id": pair[1].ID, "kind": pair[1].Kind, "amount_cents": pair[1].AmountCents, "occurred_at": pair[1].At, "reversal_of": revOf[pair[1].ID]}}
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Clauses(clause.OnConflict{Columns: []clause.Column{{Name: "family_id"}, {Name: "reversal_of"}}, DoNothing: true}).Table(tbl).Create(rows)
	})
}

// walk：递归走一遍响应体，按类型数数——任何数字字段出现小数点 / 指数就被记进 bad（判据 6 的证据）。
func walk(v any, key string, ip, fp *int, bad *[]string) {
	switch x := v.(type) {
	case json.Number:
		f := boolInt(strings.ContainsAny(string(x), ".eE")) // 1 = 这个数不是整数分/整数 bp
		*ip, *fp = *ip+1-f, *fp+f
		*bad = append(*bad, map[bool][]string{true: {key + "=" + string(x)}, false: nil}[f == 1]...)
	case map[string]any:
		for _, k := range sortedKeys(x) {
			walk(x[k], k, ip, fp, bad)
		}
	case []any:
		for _, e := range x {
			walk(e, key, ip, fp, bad)
		}
	}
}

