func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err) // 取不到时区就崩，绝不静默回落 UTC（d13）
	}
	return l
}
func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }

// 时间窗口径逐字沿用 d13/d17：d25 用得上 month / quarter / year 三档
func bucketStart(k Kind, t time.Time) time.Time {
	l := t.In(famLoc)
	return map[Kind]time.Time{KMonth: day0(l.Year(), int(l.Month()), 1), KQuarter: day0(l.Year(), (int(l.Month())-1)/3*3+1, 1), KYear: day0(l.Year(), 1, 1)}[k]
}
func bucketEnd(k Kind, t time.Time) time.Time {
	return bucketStart(k, t).AddDate(step[k][0], step[k][1], step[k][2])
}
func bucketKey(k Kind, t time.Time) string {
	l := t.In(famLoc)
	return map[Kind]string{KMonth: l.Format("2006-01"), KQuarter: fmt.Sprintf("%04d-Q%d", l.Year(), (int(l.Month())-1)/3+1), KYear: l.Format("2006")}[k]
}

// parseKey：d17 红线一的实现——形状不对或 canonical 往返不等就是错误，绝不回落默认窗
func parseKey(k Kind, s string) (time.Time, error) {
	st := time.Time{}
	if k == KQuarter {
		if len(s) != 7 || s[4:6] != "-Q" || s[6] < '1' || s[6] > '4' {
			return st, fmt.Errorf("window=%q 不符合 quarter 形状（形如 %s）", s, ex[k])
		}
		st = day0(atoi4(s[:4]), int(s[6]-'0'-1)*3+1, 1)
	} else if t, err := time.ParseInLocation(lay[k], s, famLoc); err != nil {
		return st, fmt.Errorf("window=%q 解析失败：%s 档形如 %s", s, k, ex[k])
	} else {
		st = t
	}
	if got := bucketKey(k, st); got != s {
		return st, fmt.Errorf("window=%q 不是规范桶键：%s 档这一期的真实键是 %q", s, k, got)
	}
	return st, nil
}
func atoi4(s string) int {
	return int(s[0]-'0')*1000 + int(s[1]-'0')*100 + int(s[2]-'0')*10 + int(s[3]-'0')
}
func money(c int64) string {
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs(c)/100, abs(c)%100)
}
func abs(v int64) int64       { return map[bool]int64{true: -v, false: v}[v < 0] }
func signed(c int64) string   { return map[bool]string{true: "+", false: ""}[c >= 0] + money(c) }
func hdr(s string)            { fmt.Printf("\n===== %s =====\n", s) }
func at(t time.Time) string   { return t.In(famLoc).Format("2006-01-02 15:04:05.000") }
func idsOf(rs []Txn) []string { return collect(rs, func(t Txn) string { return t.ID }) }
func collect[V any](rs []Txn, f func(Txn) V) []V {
	out := []V{}
	for _, t := range rs {
		out = append(out, f(t))
	}
	return out
}

