// T-33 是时区边界探针（家庭时区 00:00~08:00 那段，UTC 日界的写法会整段丢）；T-34 是排他右端探针；
// T-30 / T-31 软删；T-32 是别家的行（金额同 d14 的 t-07）；T-20 / T-22 落在窗外。

// ---------- Filter：唯一的条件源。查询侧与导出侧都只从它生成 WHERE ----------
type cond struct {
	sql  string
	args []any
}
type Filter struct {
	Fam, Direction, CategoryID, AccountID, Keyword string
	K                                              Kind
	Period                                         string
	CursorAt                                       time.Time
	CursorID                                       string
	Limit                                          int  // 0 = 全量（导出就该是这样）；>0 = 分页或「照抄来的坑」
	NoDeleted                                      bool // ❌ 漂移开关：导出侧把 deleted_at IS NULL 弄丢了
	UTCDay                                         bool // ❌ 漂移开关：窗口按 UTC 日界拼，不按家庭时区
}

func (f Filter) window() (time.Time, time.Time) {
	st, err := parseKey(f.K, f.Period)
	if err != nil {
		panic(err) // handler 层已经把这种请求打成 400（d17），走到这里说明是内部拼错
	}
	en := bucketEnd(f.K, st)
	if !f.UTCDay {
		return st, en
	}
	return time.Date(st.Year(), st.Month(), st.Day(), 0, 0, 0, 0, time.UTC), time.Date(en.Year(), en.Month(), en.Day(), 0, 0, 0, 0, time.UTC)
}

// conds：WHERE 片段只有这一处生产者（d27 把这张表打成四列对照表）
func (f Filter) conds() []cond {
	st, en := f.window()
	cs := []cond{{"family_id = ?", []any{f.Fam}}}
	if !f.NoDeleted {
		cs = append(cs, cond{"deleted_at IS NULL", nil})
	}
	cs = append(cs, cond{"occurred_at >= ? AND occurred_at < ?", []any{st.Format(time.RFC3339Nano), en.Format(time.RFC3339Nano)}})
	for _, o := range []struct{ v, sql string }{{f.Direction, "type = ?"}, {f.CategoryID, "category_id = ?"}, {f.AccountID, "account_id = ?"}} {
		if o.v != "" {
			cs = append(cs, cond{o.sql, []any{o.v}})
		}
	}
	if f.Keyword != "" {
		cs = append(cs, cond{"note ILIKE ?", []any{"%" + f.Keyword + "%"}})
	}
	if f.CursorID != "" {
		cs = append(cs, cond{"(occurred_at, id) < (?, ?)", []any{f.CursorAt.Format(time.RFC3339Nano), f.CursorID}})
	}
	return cs
}
func sqlOf(db *gorm.DB, f Filter, cols []string) string {
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		q := tx.Table(tbl).Select(strings.Join(cols, ", "))
		for _, c := range f.conds() {
			q = q.Where(c.sql, c.args...)
		}
		if f.Limit > 0 {
			q = q.Limit(f.Limit) // 0 不传：导出全量根本没有 LIMIT 这个子句
		}
		return q.Order("occurred_at DESC, id DESC").Find(&[]map[string]any{}) // 全序键两侧共用（S10 d10）
	})
}
func run(rows []Txn, f Filter) []Txn { // 内存表上跑同一段语义：WHERE + ORDER BY + LIMIT
	st, en := f.window()
	out := []Txn{}
	for _, t := range rows {
		if t.Fam != f.Fam || (!f.NoDeleted && t.Deleted) || t.At.Before(st) || !t.At.Before(en) {
			continue
		}
		if (f.Direction != "" && t.Type != f.Direction) || (f.CategoryID != "" && t.CategoryID != f.CategoryID) || (f.AccountID != "" && t.AccountID != f.AccountID) || (f.Keyword != "" && !strings.Contains(t.Note, f.Keyword)) {
			continue
		}
		if f.CursorID != "" && !(t.At.Before(f.CursorAt) || (t.At.Equal(f.CursorAt) && t.ID < f.CursorID)) {
			continue // 严格小于游标那一行：同秒多笔靠 id 分出全序
		}
		out = append(out, t)
	}
	sort.Slice(out, func(i, j int) bool {
		return map[bool]bool{true: out[i].At.After(out[j].At), false: out[i].ID > out[j].ID}[!out[i].At.Equal(out[j].At)]
	})
	if f.Limit > 0 && len(out) > f.Limit {
		out = out[:f.Limit] // LIMIT 在 ORDER BY 之后生效，截的是尾部
	}
	return out
}

var famSign = map[string]int64{"income": 1, "expense": -1, "refund": 1, "transfer": 0} // d19 的符号表，全项目只此一份

func totals(rows []Txn) (inc, exp, net, sum, n int64) {
	for _, t := range rows { // 整数分累加：导出脚本里没有第二次聚合
		n++
		inc += map[bool]int64{true: t.AmountCents, false: 0}[t.Type == "income" || t.Type == "refund"]
		exp += map[bool]int64{true: t.AmountCents, false: 0}[t.Type == "expense"]
		net, sum = net+famSign[t.Type]*t.AmountCents, sum+t.AmountCents
	}
	return
}
func idset(rs []Txn) map[string]bool {
	m := map[string]bool{}
	for _, t := range rs {
		m[t.ID] = true
	}
	return m
}
func diff(a, b map[string]bool) []string { // a 有 b 没有；先取 key 排序再打印（map 遍历不定序）
	out := []string{}
	for k := range a {
		if !b[k] {
			out = append(out, k)
		}
	}
	sort.Strings(out)
	return out
}

