func queryRow(t Txn) map[string]string {
	return map[string]string{"id": t.ID, "family_id": t.Fam, "occurred_at": t.At.Format(time.RFC3339Nano), "occurred_at_home_tz": at(t.At),
		"type": t.Type, "amount_cents": fmt.Sprint(t.AmountCents), "account_id": t.AccountID, "account_name": acctName[t.AccountID],
		"category_id": t.CategoryID, "category_name": catName[t.CategoryID], "member_id": t.MemberID, "created_by": t.MemberID,
		"note": t.Note, "has_receipt": "false", "reversal_of": t.ReversalOf,
		"deleted_at": map[bool]string{true: "2026-08-20T10:00:00+08:00", false: ""}[t.Deleted]}
}
func exportRow(t Txn) []string { // 导出行：与查询侧同一个构造函数，只是按固定列序取值（列顺序稳定 = d26）
	out, r := []string{}, queryRow(t)
	for _, c := range detailCols {
		out = append(out, r[c])
	}
	return out
}

