func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err) // 取不到时区就崩，绝不静默回落 UTC（d13）
	}
	return l
}
func d(y, m, day, h int) time.Time { return time.Date(y, time.Month(m), day, h, 0, 0, 0, famLoc) }
func hdr(s string)                 { fmt.Printf("\n===== %s =====\n", s) }
func abs64(v int64) int64          { return map[bool]int64{true: -v, false: v}[v < 0] }
func sgn(c int64) string           { return map[bool]string{true: "-", false: ""}[c < 0] }
func money(c int64) string         { return sgn(c) + fmt.Sprintf("%d.%02d", abs64(c)/100, abs64(c)%100) }
func boolInt(b bool) int           { return map[bool]int{true: 1, false: 0}[b] }
func yes(b bool) string            { return map[bool]string{true: "✅", false: "❌"}[b] }
func hexOf(s string, n int) string { return fmt.Sprintf("% X", []byte(s)[:min(n, len(s))]) }
func isFormula(s string) bool      { return s != "" && strings.ContainsAny(s[:1], "=+-@") }
func nonASCII(s string) bool       { return strings.IndexFunc(s, func(r rune) bool { return r > 127 }) >= 0 }
func rangeNum(s string) int        { n, _ := strconv.Atoi(s[1:]); return n }
func cellLine(file, id string) string {
	for _, l := range strings.Split(file, "\n") {
		if strings.HasPrefix(l, id) {
			return l
		}
	}
	return ""
}
func group(c int64) string { // ❌ 给人看的千分位串 11,300.00：逗和小数点都是后加进去的
	ip, fr := fmt.Sprint(abs64(c)/100), fmt.Sprintf("%02d", abs64(c)%100)
	s := ip[:min(len(ip), (len(ip)-1)%3+1)]
	for i := min(len(ip), (len(ip)-1)%3+1); i < len(ip); i += 3 {
		s += "," + ip[i:i+3]
	}
	return sgn(c) + s + "." + fr
}
func latin1(s string) string { // ❌ 无 BOM 时 Excel 把每个 UTF-8 字节当成一个 ANSI 字符
	b, r := []byte(s), make([]rune, 0, len(s))
	for i := range b {
		r = append(r, rune(b[i]))
	}
	return string(r)
}
func cells(r Row, o opts) []string {
	return []string{r.ID, map[bool]string{true: r.At.In(famLoc).Format(time.RFC3339), false: r.At.In(famLoc).Format("2006-01-02 15:04:05")}[!o.naiveDate], r.Type, map[bool]string{true: fmt.Sprint(r.Cents), false: group(r.Cents)}[o.cents], r.Acct, r.Cat, map[bool]string{true: "'" + r.Note, false: r.Note}[o.sanitize && isFormula(r.Note)]} // ✅ RFC3339 带偏移 / 整数 *_cents / ' 前缀只多一个字符，原字节不动
}
func build(o opts) string {
	recs, naive := [][]string{cols}, strings.Join(cols, ",")+"\n"
	for _, r := range ledger {
		c := cells(r, o)
		recs, naive = append(recs, c), naive+strings.Join(c, ",")+"\n" // ❌ naive 那条：逗号、引号、换行原样落盘
	}
	var sink bytes.Buffer
	cw := csv.NewWriter(&sink)
	cw.UseCRLF = o.crlf // 默认 LF；UseCRLF 只动行尾，内容一个字节不改
	for _, r := range recs {
		_ = cw.Write(r)
	}
	cw.Flush()
	return map[bool]string{true: bom, false: ""}[o.bom] + map[bool]string{true: sink.String(), false: naive}[!o.naive]
}
func strictRead(file string) ([][]string, error) {
	r := csv.NewReader(strings.NewReader(strings.TrimPrefix(file, bom)))
	return r.ReadAll()
}
func cellOf(file, id string, j int) string {
	recs, err := strictRead(file)
	if err != nil {
		return "（解析失败）"
	}
	for _, r := range recs[1:] {
		if r[0] == id {
			return r[j]
		}
	}
	return "（无此行）"
}
func sumRange(cell string) int64 { // =SUM(D2:D9)：表头占第 1 行，数据行号 k → ledger[k-2]；D 列 = amount_cents
	ab := strings.Split(strings.TrimSuffix(strings.TrimPrefix(cell, "=SUM("), ")"), ":")
	sum := int64(0)
	for k := rangeNum(ab[0]); k <= rangeNum(ab[1]) && k-2 < len(ledger); k++ {
		sum += map[bool]int64{true: ledger[k-2].Cents, false: 0}[k >= 2]
	}
	return sum
}

type pcol struct {
	name, dtype, sample string
	bad                 int
	sum                 int64
}

func pandasRead(file string) []pcol { // 模拟 pandas：没有 BOM 概念、按字节 UTF-8 解码、下游 to_numeric(errors="coerce")
	recs, err := strictRead(file)
	if err != nil {
		panic(err) // 定稿文件必须能被标准解析器整读
	}
	out := []pcol{}
	for j, c := range cols {
		p := pcol{name: c, dtype: "int64"}
		for i := 1; i < len(recs); i++ {
			n, e := strconv.ParseInt(recs[i][j], 10, 64)
			p.bad += boolInt(e != nil)
			p.sum += map[bool]int64{true: n, false: 0}[e == nil] // 失败格不进和 = sum(skipna) 的语义
			p.sample = map[bool]string{true: recs[i][j], false: p.sample}[e != nil && p.sample == ""]
		}
		p.dtype = map[bool]string{true: "int64", false: "object"}[p.bad == 0]
		out = append(out, p)
	}
	return out
}
func formulaCells(file string) []string { // 模拟 Excel 公式引擎：=/+/-/@ 开头的单元格被执行而不是被显示
	recs, _ := strictRead(file)
	out := []string{}
	for i := 1; i < len(recs); i++ {
		for j, c := range recs[i] {
			if isFormula(c) {
				t := "Excel 也按公式求值：-4+3 = -1（引擎算的，不是文案）" // 注意：这里不能用 map 三元——map 两个分支都会被求值，非 SUM 格会把 sumRange 做炸（d24 第 3 节同款教训）
				if strings.HasPrefix(c, "=SUM(") {
					t = fmt.Sprintf("Excel 真算：Σ %s = %d 分（%s 元），备注成了公式、文件成了计算器", c[5:len(c)-1], sumRange(c), money(sumRange(c)))
				}
				out = append(out, fmt.Sprintf("第 %d 行 · %s 列：%q ← %s", i+1, cols[j], c, t))
			}
		}
	}
	return out
}

