	return l
}
func day0(y, m, dd int) time.Time { return time.Date(y, time.Month(m), dd, 0, 0, 0, 0, famLoc) }
func at(t time.Time) string       { return t.In(famLoc).Format("2006-01-02 15:04:05") }
func hdr(s string)                { fmt.Printf("\n===== %s =====\n", s) }
func abs64(v int64) int64         { return map[bool]int64{true: -v, false: v}[v < 0] }
func money(c int64) string {
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs64(c)/100, abs64(c)%100)
}
func boolInt(b bool) int { return map[bool]int{true: 1, false: 0}[b] }
func splitCols(s string) []string {
	return strings.FieldsFunc(s, func(r rune) bool { return r == ',' })
}
func dayOK(d int) bool { return inDict(fmt.Sprint(d), okDaysS) }
func inDict(s string, ss ...[]string) bool {
	for _, l := range ss {
		for _, v := range l {
			if v == s {
				return true
			}
		}
	}
	return false
}
func colWhy(c string) string { // 字典外的列分三类，判错代价不一样
	if inDict(c, internalCols) {
		return "库里真存在但不在导出字典：页面看不见 ≠ 可以点名"
	}
	if inDict(c, foreignCols) {
		return "本服务没有任何跨家庭列：越权与拼错同判 400"
	}
	return "形状都不像列名：拼接入口就是这么打开的"
}
func legalCols() string {
	return "合法形状：columns 逐列取自明细 " + strings.Join(detailCols, ",") + " 或报表 " + strings.Join(reportCols, ",")
}

// ---------- validate：四个参数全走白名单；非法 → 400 + 合法形状（禁止回落默认） ----------
type req struct {
	typ     string
	days    int
	format  string
	columns string
	silent  bool // ❌ 演示开关：走「静默兜底」那条路的 handler
}

func mixedSheet(cols []string) string { // 明细面与报表面（d24 §6）是两张表，一张文件只许一面
	if len(cols) < 2 {
		return ""
	}
	want := inDict(cols[0], reportCols)
	for _, c := range cols {
		if inDict(c, reportCols) != want {
			return c
		}
	}
	return ""
}
func validate(q req) ([]string, int, string) {
	cols := splitCols(q.columns)
	if !q.silent { // ✅ 白名单版：一条不合格就 400，并把合法形状写在错误里
		if q.format != "csv" {
			return nil, 400, fmt.Sprintf("format=%q 不支持：本期只交付 csv（合法形状：format=csv）", q.format)
		}
		if q.typ != "" && !inDict(q.typ, okTypes) {
			return nil, 400, fmt.Sprintf("type=%q 不在枚举里（合法：空=all 或 %s）", q.typ, strings.Join(okTypes, " / "))
		}
		if !dayOK(q.days) {
			return nil, 400, fmt.Sprintf("days=%d 不在档位里（合法：%s；档位是枚举不是区间，不做就近取整）", q.days, strings.Join(okDaysS, " / "))
		}
		if len(cols) == 0 {
			return nil, 400, "columns 为空：导出必须点名列集。" + legalCols()
		}
		for _, c := range cols {
			if inDict(c, foreignCols) {
				return nil, 400, fmt.Sprintf("columns 含列 %q：本服务没有任何跨家庭列（400 不 404：字典里查不到这个名字，越权与拼错同判）。%s", c, legalCols())
			}
			if !inDict(c, detailCols, reportCols) {
				return nil, 400, fmt.Sprintf("columns 含未知列 %q（%s）。%s", c, colWhy(c), legalCols())
			}
		}
		if c := mixedSheet(cols); c != "" {
			return nil, 400, fmt.Sprintf("columns=%q 混面：%q 属于另一张表（明细 1 行 1 列 vs 报表 1 桶 1 行），一个文件只许一面", strings.Join(cols, ","), c)
		}
		return cols, 200, "ok：四参数全命中白名单"
	}
	// ❌ 静默兜底版：全都「过了」，但每一条都在暗中改口径
	sw := []string{}
	if q.format != "csv" {
		sw = append(sw, fmt.Sprintf("format=%q 手上按 csv 出、响应字段原样回显", q.format))
	}
	if q.typ != "" && !inDict(q.typ, okTypes) {
		sw = append(sw, fmt.Sprintf("type=%q 枚举查不到 → 当成 all（income 也混进 expense 的账）", q.typ))
	}
	if !dayOK(q.days) {
		sw = append(sw, fmt.Sprintf("days=%d 档位查不到 → 悄悄用默认 %d", q.days, defaultDays))
	}
	if len(cols) == 0 {
		cols = append([]string{}, detailCols...) // ❌ 演示版真的这么干：嘴上不说，手里塞满整面
		sw = append(sw, fmt.Sprintf("columns 空 → 悄悄用字典明细面全 %d 列", len(cols)))
	}
	leak := []string{}
	for _, c := range cols {
		if !inDict(c, detailCols, reportCols) {
			leak = append(leak, c)
		}
	}
	if len(leak) > 0 {
		sw = append(sw, fmt.Sprintf("%d 个字典外列不拦（%s：%s）→ 原样带进 SQL 拼接（第 3 节那条串）", len(leak), colWhy(leak[0]), strings.Join(leak, ",")))
	}
	if c := mixedSheet(cols); c != "" {
		sw = append(sw, fmt.Sprintf("混面列 %q 照拼：两张稠密表挤进一个文件", c))
	}
	return cols, 200, strings.Join(sw, "；")
}

// ---------- 取数：查询侧与导出侧共用同一段 WHERE（d25 的结构前提） ----------
func eff(q req) req { // ❌ 兜底版的真实口径：嘴上说的参数被换成「能用」的默认
	if !q.silent {
		return q
	}
	if q.typ != "" && !inDict(q.typ, okTypes) {
		q.typ = ""
	}
	if !dayOK(q.days) {
		q.days = defaultDays // ❌ 演示版：漂掉的不是报错，是天数口径
	}
	return q
}
func window(days int) (time.Time, time.Time) { return fixedNow.AddDate(0, 0, -days), fixedNow }
func run(q req) ([]Txn, int64) {
	q = eff(q)
	st, en := window(q.days)
	rows := []Txn{}
	for _, t := range ledger {
		if t.Fam != famA || t.Deleted || t.At.Before(st) || !t.At.Before(en) || (q.typ != "" && t.Type != q.typ) {
			continue
		}
		rows = append(rows, t)
	}
	sort.Slice(rows, func(i, j int) bool {
		return rows[i].At.Before(rows[j].At) || (rows[i].At.Equal(rows[j].At) && rows[i].ID < rows[j].ID)
	})
	sum := int64(0)
	for _, t := range rows {
		sum += t.Cents
	}
	return rows, sum
}
func colVal(t Txn, c string) string {
	v := map[string]string{"id": t.ID, "type": t.Type, "occurred_at": t.At.In(famLoc).Format(time.RFC3339), "occurred_at_home_tz": at(t.At), "amount_cents": fmt.Sprint(t.Cents), "account_name": t.AccountID, "category_name": t.CategoryID, "member_id": t.MemberID, "note": t.Note, "has_receipt": "false", "deleted_at": map[bool]string{true: "非空", false: ""}[t.Deleted], "fam_b_note": "（别家数据）"}[c]
	return v
}

// ---------- DryRun：本机无 Postgres，打印 GORM 真实生成的 Postgres 方言原文（不是手写示意 SQL） ----------
func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable"}),
		&gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	if err != nil {
		panic(err)
	}
	return db
}

var brk = strings.NewReplacer(" FROM ", "\n     FROM ", " WHERE ", "\n     WHERE ", " AND ", "\n       AND ", " ORDER BY ", "\n     ORDER BY ")

func okSQL(db *gorm.DB, q req, cols []string) string { // ✅ 列名来自字典，值走占位符
	st, en := window(q.days)
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		t := tx.Table(tbl).Select(strings.Join(cols, ", ")).Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?", famA, st.Format(time.RFC3339Nano), en.Format(time.RFC3339Nano))
		if q.typ != "" {
			t = t.Where("type = ?", q.typ)
		}
		return t.Order("occurred_at, id").Find(&[]map[string]any{})
	})
}
func badSQL(db *gorm.DB, rawType string, rawCols []string, days int) string { // ❌ 把参数当代码：列名、值、间隔全拼进串
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Table(tbl).Select(strings.Join(rawCols, ", ")).Where("family_id = '" + famA + "' AND deleted_at IS NULL AND type = '" + rawType + "' AND occurred_at >= now() - interval '" + fmt.Sprint(days) + " days'").Order("occurred_at, id").Find(&[]map[string]any{})
	})
}

// ---------- 任务侧：param_hash = 规范参数的 sha256；漂了就不是同一个请求 ----------
type task struct{ id, crid, hash string }

func ph(parts ...string) string {
	h := sha256.Sum256([]byte(strings.Join(parts, "|")))
	return hex.EncodeToString(h[:])[:12]
}
func normHash(q req) string {
	cols := splitCols(q.columns)
	sort.Strings(cols) // 列顺序不参与「同一个请求」判定；值域漂了才算
	return ph(famA, q.typ, fmt.Sprint(q.days), q.format, strings.Join(cols, ","))
}

