const famTZ = "Asia/Shanghai"
const fam = "fam-A"
const tbl = "finance_transaction"
const bom = "\ufeff" // d24 §6：UTF-8 BOM，让 Excel 认 UTF-8
const perMonth = 1500
const streamFlushEvery = 250 // 流式：攒这么多行排一次水，驻留行数峰值恒为 1
const rowLimit = 2000        // 超过它就别在请求线程里出结果（第 1 节的阈值）

var famLoc = mustLoad(famTZ)
var fixedNow = day0(2026, 12, 1).Add(9 * time.Hour) // 任务时钟也固定：两次跑字节一致
