var budgetCents = map[string]int64{"2026-01": 2200000, "2026-02": 2200000, "2026-03": 2200000, "2026-06": 2500000, "2026-07": 2500000, "2026-08": 2500000}
var ratioText = map[string]string{"ok": "", "neg_base": "上期净赤，环比不可比", "no_prev_window": "无对比基数", "no_prev_bucket": "无对比基数", "zero_prev": "无对比基数"}

func mustLoad(n string) *time.Location {
	l, err := time.LoadLocation(n)
	if err != nil {
		panic(err)
	}
	return l
}
func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }
func bucketStart(t time.Time) time.Time {
	l := t.In(famLoc)
	return day0(l.Year(), int(l.Month()), 1)
}
func bucketKey(t time.Time) string { return t.In(famLoc).Format("2006-01") } // month=YYYY-MM（d13 定版编码）
func bucketKeys(f, to time.Time) []string { // d13 的 enumerate：稠密桶，空期也占一格
	var out []string
	for cur := bucketStart(f); cur.Before(to); cur = bucketStart(cur).AddDate(0, 1, 0) {
		out = append(out, bucketKey(cur))
	}
	return out
}
func money(c int64) string {
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs64(c)/100, abs64(c)%100)
}
func abs64(v int64) int64 { return map[bool]int64{true: -v, false: v}[v < 0] }
func boolInt(b bool) int  { return map[bool]int{true: 1, false: 0}[b] }
func hdr(s string)        { fmt.Printf("\n===== %s =====\n", s) }
func pct(bp int64) string {
	return map[bool]string{true: "+", false: "-"}[bp >= 0] + fmt.Sprintf("%d.%02d%%", abs64(bp)/100, abs64(bp)%100)
}
func sortedKeys[V any](m map[string]V) []string { // map 遍历先收集 key 排序：输出与到达顺序无关
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}
func divRound(a, b int64) int64 { // d21 的定点进位：环比只有万分比整数，不出现浮点
	s, q, r := int64(1-2*boolInt((a < 0) != (b < 0))), abs64(a)/abs64(b), abs64(a)%abs64(b)
	return s * (q + int64(boolInt(2*r >= abs64(b))))
}
func ratioOf(prev, cur int64, prevCount int) (int64, string) { // d22：先判窗外/有没有桶，再判净 0，最后才除
	if prevCount < 0 || prevCount == 0 || prev == 0 {
		return 0, map[bool]string{true: "no_prev_window", false: map[bool]string{true: "no_prev_bucket", false: "zero_prev"}[prevCount == 0]}[prevCount < 0]
	}
	return divRound((cur-prev)*10000, abs64(prev)), map[bool]string{true: "neg_base", false: "ok"}[prev < 0]
}

