func reportCSV(keys []string) []string { // d24 §6 的 11 列原样重放：列名/顺序/留空规则一字不改
	net, cnt := map[string]int64{}, map[string]int{}
	for _, x := range ledger {
		net[bucketKey(x.At)] += famSign[x.Kind] * x.Cents
		cnt[bucketKey(x.At)]++
	}
	head := strings.Join([]string{"period", "txn_count", "net_cents", "cum_cents", "prev_net_cents", "prev_bucket_exists", "ratio_bp", "ratio_text", "ratio_state", "budget_cents", "budget_state"}, ",")
	out, run, prevNet, prevCnt := []string{bom + head}, int64(0), int64(0), -1
	for _, k := range keys {
		run += net[k] // cum_cents：服务端前缀和原值导出，导出脚本不二次累加（红线①）
		bp, st := ratioOf(prevNet, net[k], prevCnt)
		bc, has := budgetCents[k]
		out = append(out, strings.Join([]string{k, fmt.Sprint(cnt[k]), fmt.Sprint(net[k]), fmt.Sprint(run),
			map[bool]string{true: fmt.Sprint(prevNet), false: ""}[prevCnt > 0], fmt.Sprint(prevCnt > 0),
			map[bool]string{true: fmt.Sprint(bp), false: ""}[st == "ok"], map[bool]string{true: pct(bp), false: ratioText[st]}[st == "ok"],
			st, map[bool]string{true: fmt.Sprint(bc), false: ""}[has], map[bool]string{true: "set", false: "not_set"}[has]}, ","))
		prevNet, prevCnt = net[k], cnt[k]
	}
	return out
}

// ---------- 大结果集：明细行 = 确定公式造的 12×1500 笔 ----------
func detailAt(m, k int) (det string, at, acc, kind string, cents int64) {
	kind = map[bool]string{true: "refund", false: map[bool]string{true: "income", false: "expense"}[k%3 == 1]}[k%500 == 0]
	return fmt.Sprintf("D-%02d-%04d", m, k), fmt.Sprintf("2026-%02d-%02dT%02d:00+08:00", m, k%28+1, k%24),
		[]string{"acc-cash", "acc-bank", "acc-credit"}[k%3], kind, 1000 + int64((k*137+m*53)%50000) // 分：金额一律 *_cents
}
func detailHead() []string {
	return []string{"txn_id", "occurred_at", "account_id", "kind", "amount_cents"}
}

// ❌ 一把梭：SELECT * 进 slice，再逐行拼成一个大字符串返回
func batchExport() (body string, peakRows, concatOps int, copyBytes int64) {
	type row struct{ id, at, acc, kind string }
	var rows []row
	for m := 1; m <= 12; m++ {
		for k := 1; k <= perMonth; k++ {
			id, at, acc, kind, _ := detailAt(m, k)
			rows = append(rows, row{id, at, acc, kind})
		}
	}
	peakRows = len(rows) // 全表物化：请求不结束，这 18000 行一个都还不给 GC
	var sb strings.Builder
	sb.WriteString(bom + strings.Join(detailHead(), ",") + "\n")
	for m := 1; m <= 12; m++ {
		for k := 1; k <= perMonth; k++ {
			id, at, acc, kind, c := detailAt(m, k)
			line := strings.Join([]string{id, at, acc, kind, fmt.Sprint(c)}, ",") + "\n"
			concatOps++
			copyBytes += int64(sb.Len()) // body = body + line：每拼一次，前面攒的整段再复制一遍
			sb.WriteString(line)
		}
	}
	return sb.String(), peakRows, concatOps, copyBytes
}

// ✅ 流式：csv.Writer 边聚合边写，内存里同一时刻只有一行 + 一块有界缓冲
func streamExport() (out string, written, maxBuf int, monthNet map[string]int64) {
	var sink bytes.Buffer
	bw := bufio.NewWriterSize(&sink, streamFlushEvery*64)
	cw := csv.NewWriter(bw)
	monthNet = map[string]int64{}
	_ = cw.Write(detailHead())
	for m := 1; m <= 12; m++ {
		for k := 1; k <= perMonth; k++ {
			id, at, acc, kind, c := detailAt(m, k)
			_ = cw.Write([]string{id, at, acc, kind, fmt.Sprint(c)}) // 写完即弃：不留行
			monthNet[fmt.Sprintf("2026-%02d", m)] += famSign[kind] * c
			if k%streamFlushEvery == 0 { // 每 250 行：csv 内部缓冲 → bw → 排空进 sink
				cw.Flush()
				if b := bw.Buffered(); b > maxBuf {
					maxBuf = b
				}
				_ = bw.Flush()
			}
		}
	}
	cw.Flush()
	_ = bw.Flush()
	return bom + sink.String(), 12 * perMonth, maxBuf, monthNet
}

// ---------- 导出任务：状态机 + 下载链接有效期（本机无 Postgres，DryRun 出真实 SQL） ----------
const minExportDays, maxExportDays = 1, 366 // 一整个平年 + 一天；超出就必须分批

// windowGuard 是导出窗的白名单校验（d27 的参数规则在任务侧再守一遍）。
// 非法窗必须 400 且当场给出合法形状，不许回落成 366 默默出一年。
func windowGuard(days int) (int, string) {
	if days >= minExportDays && days <= maxExportDays {
		return 0, ""
	}
	return 400, fmt.Sprintf("days=%d 非法：合法窗 %d..%d 天，请按账户或按月分批重导", days, minExportDays, maxExportDays)
}

type ExportTask struct {
	ID              string    `gorm:"column:id;primaryKey;type:varchar(36)"`
	FamilyID        string    `gorm:"column:family_id;type:uuid;not null"`
	ClientRequestID string    `gorm:"column:client_request_id;type:varchar(64);not null"`
	State           string    `gorm:"column:state;type:varchar(16);not null;default:pending"`
	RowCount        int64     `gorm:"column:row_count;type:bigint;not null;default:0"`
	FileBytes       int64     `gorm:"column:file_bytes;type:bigint;not null;default:0"`
	FinishedAt      time.Time `gorm:"column:finished_at;type:timestamptz"`

	// Days/Reason/ClaimedAt/Deleted 是进程内的运行态，不落这张表的列：
	// 落列会改掉第 5 节 DryRun 打出的 SELECT 列清单，而那一列清单是 d28 的对账对象。
	Days      int       `gorm:"-"`
	Reason    string    `gorm:"-"`
	ClaimedAt time.Time `gorm:"-"`
	Deleted   bool      `gorm:"-"`
}

func (ExportTask) TableName() string { return "finance_export_task" }

func (t *ExportTask) linkExpiry() time.Time { return t.FinishedAt.Add(24 * time.Hour) }
func (t *ExportTask) purgeAt() time.Time    { return t.FinishedAt.Add(7 * 24 * time.Hour) }

// tryClaim 是 `UPDATE ... WHERE id = ? AND state = 'pending'` 的内存版，返回影响行数。
func tryClaim(q []*ExportTask, id string, at time.Time) int {
	for _, t := range q {
		if t.ID != id {
			continue
		}
		if t.State != "pending" {
			return 0
		}
		t.State, t.ClaimedAt = "running", at
		return 1
	}
	return 0
}

// runTask 是 worker 跑任务这一跳：先过窗校验。非法窗把错误原样回显成 failed，不悄悄重试。
func runTask(t *ExportTask, at time.Time, rows, fileBytes int64) {
	if code, msg := windowGuard(t.Days); code != 0 {
		t.State, t.Reason, t.FinishedAt = "failed", fmt.Sprintf("%d %s", code, msg), at
		return
	}
	t.State, t.RowCount, t.FileBytes, t.FinishedAt = "succeeded", rows, fileBytes, at
}

// download 是下载判定这一跳的全部真相：状态、链接有效期、文件在不在，三者缺一不可。
func download(t *ExportTask, at time.Time) (bool, string) {
	switch {
	case t.Deleted:
		return false, "410 文件已不在，任务行只剩审计价值"
	case t.State == "pending" || t.State == "running":
		return false, "409 任务还没跑完（state=" + t.State + "），返回状态而不是半份文件"
	case t.State == "failed":
		return false, "404 这条任务没有文件可送，错误原文见 " + t.Reason
	case at.After(t.linkExpiry()):
		return false, "410 链接过期 → 重新导出走新 crid，任务记录保留"
	default:
		return true, "200 + X-Accel-Redirect：nginx 送文件，Go 不整读进内存"
	}
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable"}),
		&gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	if err != nil {
		panic(err)
	}
	return db
}
func claimSQL(db *gorm.DB, id string) string { // 领取任务：state 守卫让第二个 worker 空手而归
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&ExportTask{}).Where("id = ? AND state = ?", id, "pending").Update("state", "running")
	})
}
func findSQL(db *gorm.DB, crid string) string { // 幂等查询：命中已有任务就不新建
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Where("family_id = ? AND client_request_id = ? AND deleted_at IS NULL", fam, crid).Find(&[]ExportTask{})
	})
}

