	monthKeys, slots, writeAt, ttl           = []string{"2026-07", "2026-08", "2026-09", "2026-10", "2026-11", "2026-12", "2027-01"}, 7, 3, 3 // 缓存刻度：写入落在第 3 tick、TTL 3 tick；报表窗 [winFrom, winTo) 是绝对时刻
	unmet, pass, mine, nSoft, nB, bNet       = 0, []string{}, int(sum(ledger, func(r txn) int64 { return yesN[live(r)] })), int(sum(ledger, func(r txn) int64 { return yesN[r.soft] })), int(sum(ledger, func(r txn) int64 { return yesN[r.fam == famB] })), func(k Kind, from time.Time, l *time.Location) int64 {
		return sum(ledger, func(r txn) int64 { return netOf(r) * yesN[live(r) && bucketKey(k, r.at, l) == bucketKey(k, from, l)] })
	}
	gdb, brk, cns = must(gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gl.Default.LogMode(gl.Silent)})), strings.NewReplacer(" SELECT", "\n  SELECT", " FROM", "\n  FROM", " WHERE", "\n  WHERE", " GROUP BY", "\n  GROUP BY", " ORDER BY", "\n  ORDER BY"), []map[string]int{{}, {}, {}} // DryRun 只造 Postgres 方言原文、不连库；SQL 只在子句边界续行；cns 每策略一张计数表 → 三个 goroutine 各写各的、不用锁
