	famA0, famSet = map[string]string{"timezone": shName, "currency": "CNY", "default_account": "acc-bank", "period_start": "1", "report_cols": "date,account,category"}, map[string]map[string]string{famA: {"timezone": shName, "currency": "CNY", "default_account": "acc-bank", "period_start": "1", "report_cols": "date,account,category"}, famB: {"timezone": berName, "currency": "USD", "default_account": "acc-bank", "period_start": "1", "report_cols": "date,category"}}
	budOf, pairs  = map[string]int64{"month:2026-07": 2500000, "month:2026-08": 2300000, "month:2026-09": 2400000}, [][2]string{{"timezone", laName}, {"currency", "USD"}, {"default_account", "acc-cash"}, {"period_start", "7"}, {"report_cols", "date,category"}}
