func must[T any](v T, e error) T { // 出错就崩：时区取不到不许当 UTC，DryRun 建不出句柄不许当成功
	if e != nil {
		panic(e)
	}
	return v
}
func pi(p string) int                 { return map[string]int{p1: 0, p2: 1, p3: 2}[p] }
func u(y, m, d, hh, mm int) time.Time { return time.Date(y, time.Month(m), d, hh, mm, 0, 0, time.UTC) }
func rf(t time.Time) string           { return t.Format(time.RFC3339) }
func tail(s string) string            { return s[strings.LastIndex(s, "/")+1:] }
func abs64(v int64) int64             { return map[bool]int64{true: -v, false: v}[v < 0] }
func mny(c int64) string              { return fmt.Sprintf("%d.%02d", abs64(c)/100, abs64(c)%100) }
func sgn(c int64) string              { return map[bool]string{true: "-", false: ""}[c < 0] }
func money(c int64) string            { return sgn(c) + mny(c) }
func disp(c int64, cur string) string { return sgn(c) + symbol[cur] + mny(c) }                          // 唯一的展示层出口：只加符号，一分都不动
func fx(c int64, on bool) int64       { return map[bool]int64{true: c * rateBP / 10000, false: c}[on] } // on=true 就是那条换算崩法
func netOf(r txn) int64               { return famSign[r.typ] * r.cents }
func live(r txn) bool                 { return !r.soft && r.fam == famA }
func mo(r txn) string                 { return bucketKey(KMonth, r.at, sh) }
func mb(r txn) string                 { return bucketKey(KMonth, r.at, la) }
func moved(r txn) bool                { return live(r) && mo(r) != mb(r) }
func rd(pol, fam, v string) int       { return cns[pi(pol)][pol+"|"+fam+"|"+tail(v)] }     // 计数表按 tail(val) 存键，查时也要 tail(v)：否则全名查短名恒 0
func r1(pol, fam, v string) int       { return cns[pi(pol)]["#"+pol+"|"+fam+"|"+tail(v)] } // 现取计数表：某策略下某家把某值读到过几次 / 第一次读到是第几 tick

func bQ(p string) int64     { return budOf["quarter:"+p] }
func bCents(p string) int64 { return map[bool]int64{true: bQ(p), false: budOf["month:"+p]}[bQ(p) != 0] }
func bShow(p string) string {
	return map[bool]string{true: disp(bCents(p), famSet[famA]["currency"]), false: "未设该周期预算"}[bCents(p) != 0]
}
func ck(ok bool, n, e string) {
	pass = append(pass, fmt.Sprintf("  %s %-28s 证据：%s", mark[ok], n, e))
}

// ---- 边界三函数逐字沿用 d16：唯一区别是 loc 由调用方传入，而 loc == 这个家庭当前的 timezone 设置 ----
func bucketStart(k Kind, t time.Time, l *time.Location) time.Time { // 全项目只有这一份边界推导：前端不许再推一遍，服务端也不许另写一份
	d := time.Date(t.In(l).Year(), t.In(l).Month(), t.In(l).Day(), 0, 0, 0, 0, l)
	return map[Kind]time.Time{KDay: d, KWeek: d.AddDate(0, 0, -(int(d.Weekday())+6)%7), KMonth: time.Date(d.Year(), d.Month(), 1, 0, 0, 0, 0, l), KQuarter: time.Date(d.Year(), time.Month((int(d.Month())-1)/3*3+1), 1, 0, 0, 0, 0, l), KYear: time.Date(d.Year(), 1, 1, 0, 0, 0, 0, l)}[k]
}
func bucketEnd(k Kind, t time.Time, l *time.Location) time.Time { // 排他右端恒 == 下一桶的 start（半开窗 [start, end)）
	return bucketStart(k, t, l).AddDate(stepOf[k][0], stepOf[k][1], stepOf[k][2])
}
func bucketKey(k Kind, t time.Time, l *time.Location) string {
	s, th := bucketStart(k, t, l), bucketStart(k, t, l).AddDate(0, 0, 3) // ISO 周：星期四所在的年与年内日序定周号
	return map[Kind]string{KDay: s.Format("2006-01-02"), KWeek: fmt.Sprintf("%04d-W%02d", th.Year(), (th.YearDay()+6)/7), KMonth: s.Format("2006-01"), KQuarter: fmt.Sprintf("%04d-Q%d", s.Year(), (int(s.Month())-1)/3+1), KYear: s.Format("2006")}[k]
}
func bucketNet(k Kind, from time.Time, l *time.Location) int64 { return bNet(k, from, l) } // 名字留着：§2 的窗口总额走的是这一段，见上面 bNet 的定义
func agg(rows []txn, fam string, k Kind, from, to time.Time, l *time.Location) map[string]*bucket { // 全项目唯一的出桶 + 累加现场：换时区/换币种/换默认账户只换参数，不换这里
	out := map[string]*bucket{}
	for cur := bucketStart(k, from, l); cur.Before(to); cur = bucketEnd(k, cur, l) {
		out[bucketKey(k, cur, l)] = &bucket{cur, bucketEnd(k, cur, l), 0, 0} // 稠密枚举：空期也占一格，报表不许悄悄少一行（d17）
	}
	for _, r := range rows {
		if r.soft || r.fam != fam || r.at.Before(from) || !r.at.Before(to) {
			continue // deleted_at、family_id、半开窗：三个条件一个都不能少（d25）
		}
		b := bucketKey(k, r.at, l)
		out[b].net, out[b].n = out[b].net+netOf(r), out[b].n+1
	}
	return out
}

func each[T any](xs []T, f func(T) string) string { // 逐行出 stdout
	o := []string{}
	for _, x := range xs {
		o = append(o, f(x))
	}
	return strings.Join(o, "\n")
}
func sum[T any](xs []T, f func(T) int64) int64 {
	var s int64
	for _, x := range xs {
		s += f(x)
	}
	return s
}
func fanOut[X any](xs []X, f func(X) string) string { // 并发成行：一组一个 goroutine → WaitGroup 收集到按下标写入的切片 → 按整行文本（首列即稳定键）排序
	var wg sync.WaitGroup
	out := make([]string, len(xs))
	wg.Add(len(xs))
	for i, x := range xs {
		go func(i int, x X) { defer wg.Done(); out[i] = f(x) }(i, x) // 每个 goroutine 只写自己那个下标：不共享 map，也就不需要锁
	}
	wg.Wait()
	sort.Strings(out)
	return strings.Join(out, "\n")
}

func setTry(p [2]string) string { // 把一项设置改成另一个值 → 立刻重算两个季档的预算显示 → 再改回原始快照
	famSet[famA][p[0]] = p[1]
	o := fmt.Sprintf("    把 %-16s 改成 %-18q → 2026-Q3 = %s ｜ 2026-Q4 = %s ｜ 两个季档都仍未设 %s", p[0], p[1], bShow("2026-Q3"), bShow("2026-Q4"), mark[bCents("2026-Q3") == 0 && bCents("2026-Q4") == 0])
	unmet, famSet[famA][p[0]] = unmet+yes[bCents("2026-Q3") == 0 && bCents("2026-Q4") == 0], famA0[p[0]]
	return o
}

// polRun：tick = 设置版本推进的刻度。同一 tick 内两家庭的读等价于同一版本上的 MVCC 快照读，结果只由版本与
// 刻度决定、不由 goroutine 谁先跑决定 —— 这就是 run.sh 连跑两次输出字节一致的理由。
func polRun(pol string) string {
	z0, ver, cz, cv, ca, s, c, g := map[string]string{famA: shName, famB: berName}, map[string]int{famA: 7, famB: 3}, map[string]string{}, map[string]int{}, map[string]int{}, [2]string{}, cns[pi(pol)], "*"
	for slot := 1; slot <= slots; slot++ {
		z0[famA], ver[famA] = map[bool]string{true: laName, false: z0[famA]}[slot == writeAt], ver[famA]+yes[slot == writeAt] // 写入方：改值 + version+1（d30 乐观锁）
		delete(cz, map[bool]string{true: famA, false: "≠ 只等 TTL 不清槽"}[pol == p1]+map[bool]string{true: "", false: "≠ 未到写入 tick"}[slot == writeAt])
		for _, fam := range [2]string{famA, famB} {
			k := map[bool]string{true: fam, false: g}[pol != p3]                                             // ❌ 崩法：缓存 key 里没有 family_id，全家共用一个槽
			fresh := map[bool]bool{true: cv[k] == ver[fam], false: ca[k] > 0 && slot-ca[k] < ttl}[pol == p1] // ✅ 比设置版本 / ❌ 只等 TTL 到期
			val, hit := map[bool]string{true: cz[k], false: z0[fam]}[cz[k] != "" && fresh], cz[k] != "" && fresh
			t := pol + "|" + fam + "|" + tail(val)
			c[t], c["#"+t], c["Σ"] = c[t]+1, map[bool]int{true: c["#"+t], false: slot}[c["#"+t] > 0], c["Σ"]+1
			cz[k], cv[k], ca[k] = map[bool]string{true: cz[k], false: val}[hit], map[bool]int{true: cv[k], false: ver[fam]}[hit], map[bool]int{true: ca[k], false: slot}[hit]
			s[yes[fam == famB]] += fmt.Sprintf("%d:%s%s ", slot, tail(val), map[bool]string{true: "*", false: ""}[hit])
		}
	}
	return fmt.Sprintf("  %-26s A: %s\n  %-26s B: %s", pol, s[0], "", s[1])
}
func trendSQL(tz string) string { // timezone 只是这条聚合的一个绑参：换时区不改 SQL 文本，只换这一个参数
	q := gdb.Table(tbl).Select("to_char(date_trunc('month', occurred_at AT TIME ZONE ?), 'YYYY-MM') AS bucket_key, COALESCE(SUM(CASE WHEN type IN ('income','refund') THEN amount_cents ELSE -amount_cents END)::bigint, 0) AS net_cents, COUNT(*) AS txn_count", tz).Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?", famA, rf(winFrom), rf(winTo)).Group("bucket_key").Order("bucket_key").Find(&[]map[string]any{})
	return brk.Replace(fmt.Sprintf("%s -- 绑参：%v", q.Statement.SQL.String(), q.Statement.Vars)) // 绑参单独打一行：SELECT 里只留 ?，与 GORM 真发出去的 wire 形态一致
}

func setSQL() string { // 改设置的写入路径：乐观锁 version 进 WHERE（0 行受影响 = 409，d30），审计列同批写；只碰设置表
	return brk.Replace(gdb.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Table(setTbl).Where(qs, famA, "timezone", 7).Updates(map[string]any{"value": laName, "version": 8, "updated_by": "m-dad", "updated_at": fixedNow})
	}))
}
