// W48 d32：设置面的权限与越权 —— 三码分工：未登录 401 / 非本家庭 404 / 角色不足 403。
// 这一天在解决什么问题：① 生效的 family_id 只有一个来源 = 会话。query/body/path 里塞进来的 family_id
// 要么被忽略（与会话相同 = 冗余），要么直接被拒（与会话不同 = 想动别家 → 404）。
// ② 跨家庭读写一律 404、绝不 403：403 要先向攻击者确认「这行存在、你够得着但没资格」，本身就是泄露；
// 404 与「这行根本不存在」的响应体逐字节相同 → 无法枚举别人家庭里有哪些成员、哪些键。
// ③ 403 与 404 的分工要能当场演示：成员改本家庭的家庭级口径设置 = 403（够得着、没资格）；
// 成员改同家庭另一个成员的成员级设置 = 404（不是你的资源，不确认那个成员存在）；
// 监护人代写本家庭成员的显示类设置 = 200（这是唯一合法的「代写」通道，口径类不走它）。
// ④ 报表页返回什么：未登录 401、非本家庭 404、本家庭 200；金额仍是整数 *_cents，
// 「未设该周期预算」与权限层一个字符的关系都没有。
// 学员侧跑法：cd homecube/server && go run ./lab/s11/d32
package main

import (
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	gl "gorm.io/gorm/logger"
)

type sess struct { // 会话主体：fam == "" 就是未登录；role 只有 guardian/member 两档，来自令牌不可伪造
	id, fam, role string
}
type Row struct { // family_setting 一行：scope=member 时 member 定位到具体成员；family 级 member 恒空
	fam, scope, member, key, val string
	ver                          int
	del                          bool
}
type req struct { // 一次设置面请求；qFam = 客户端在 query/body 塞的 family_id，只用来证明「不认」
	verb           string // read | write | report
	s              sess
	qFam           string
	scope, member  string
	key, val, crid string
	ver            int
}
type txn struct { // 报表页要读的最小流水：金额一律整数 *_cents，权限层不碰数值
	fam, typ string
	cents    int64
	del      bool
}

const (
	famA, famB, ghost = "fam-A", "fam-B", "u-ghost" // ghost = 哪个家庭都不存在的成员键
	setTbl            = "finance_family_setting"
	cal, disp         = "caliber", "display" // 口径类只能家庭级；显示类才可被监护人代写
)

// notFound 是全项目唯一的 404 响应体：不带资源是否存在、不带家庭是否存在、不 echo 任何入参。
// 三个不同来源（跨家庭写 / 别人家的成员键 / 根本不存在）都返回这一个常量，所以「响应体去重 == 1 种」
// 这条断言不是在写死结论，而是在当场核对 handle 的返回。
const notFound = `404 {"error":"not_found"}`

var (
	fixedNow   = time.Date(2026, 12, 1, 9, 0, 0, 0, time.UTC)
	mark       = map[bool]string{true: "✅", false: "❌"}
	yes        = map[bool]int{true: 1, false: 0}
	sNo        = sess{}
	sMom       = sess{"u-mom", famA, "guardian"}
	sDad       = sess{"u-dad", famA, "guardian"}
	sKid       = sess{"u-kid", famA, "member"}
	sBob       = sess{"u-bob", famB, "guardian"}
	famMembers = map[string][]string{famA: {"u-mom", "u-dad", "u-kid"}, famB: {"u-bob", "u-ann"}}
	dict       = map[string]string{"timezone": cal, "currency": cal, "default_account": cal, "period_start": cal, "report_cols": disp, "compact_view": disp}
	legal      = map[string]string{"timezone": "Asia/Shanghai|America/Los_Angeles|Europe/Berlin", "currency": "CNY|USD|EUR", "default_account": "acc-bank|acc-cash|acc-salary", "period_start": "1|15", "report_cols": "period,net_cents|period,net_cents,cum_cents", "compact_view": "true|false"}
	sysDefault = map[string]string{"timezone": "UTC", "currency": "USD", "default_account": "acc-cash", "period_start": "1", "report_cols": "period,net_cents", "compact_view": "false"}
	set        = []Row{
		{famA, "family", "", "timezone", "Asia/Shanghai", 8, false},
		{famA, "family", "", "currency", "CNY", 5, false},
		{famA, "family", "", "default_account", "acc-bank", 1, false},
		{famA, "family", "", "period_start", "1", 2, false},
		{famA, "member", "u-mom", "report_cols", "period,net_cents", 1, false},
		{famA, "member", "u-kid", "compact_view", "true", 2, false},
		{famB, "family", "", "currency", "EUR", 4, false}, // 别家的行：本机没有任何入口能写它
		{famB, "member", "u-bob", "report_cols", "period,net_cents,cum_cents", 3, false},
	}
	led = []txn{{famA, "income", 860000, false}, {famA, "expense", 230000, false}, {famA, "expense", 300000, true}, {famB, "expense", 999000, false}, {famB, "income", 777000, false}}
	bud = map[string]int64{"month:2026-12": 2500000} // 只有 2026-12 月档设过预算；2026-Q4 从未设
	sym = map[string]string{"CNY": "¥", "USD": "$", "EUR": "€"}
	// DryRun：本机无 PostgreSQL，只生成真 Postgres 方言、不连库不执行；SQL 证明 family_id 恒取自会话
	gdb, brk = must(gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gl.Default.LogMode(gl.Silent)})),
		strings.NewReplacer(" SELECT", "\n  SELECT", " FROM", "\n  FROM", " WHERE", "\n  WHERE")
	aud       []string              // setting_audit 渲染行：谁/何时/旧/新；只有真实写才追加
	idem      = map[string]string{} // UNIQUE(family_id, client_request_id) 的内存等价物
	pass      []string              // 收口断言现场
	distinct4 []string              // 各来源的 404 响应体，收口时核对「去重只剩 1 种」
)

func must[T any](v T, e error) T { // 建不出 DryRun 句柄不许当成功
	if e != nil {
		panic(e)
	}
	return v
}
func dash(s string) string       { return map[bool]string{true: "-", false: s}[s == ""] }
func hdr(s string)               { fmt.Printf("\n===== %s =====\n", s) }
func inSet(v, shape string) bool { return strings.Contains("|"+shape+"|", "|"+v+"|") }
func abs64(v int64) int64        { return map[bool]int64{true: -v, false: v}[v < 0] }
func money(c int64) string       { return fmt.Sprintf("%d.%02d", abs64(c)/100, abs64(c)%100) }
func ck(ok bool, n, e string) {
	pass = append(pass, fmt.Sprintf("  %s %-28s 证据：%s", mark[ok], n, e))
}
func cod(r req) int { c, _ := handle(r); return c } // 只取状态码：读与拒绝路径无副作用，可安全复算
func keysOf(m map[string]string) string { // 输出用稳定序，与 map 迭代顺序无关
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return strings.Join(ks, "、")
}
func rowVal(fam, scope, member, key string) string { return find(fam, scope, member, key).val }
func famMember(i int) string {
	return []string{"u-bob", "u-ann", ghost, "u-ann"}[i%4] // 前两个是 fam-B 成员，掺一个根本不存在的人
}
func keysOfSlice(m map[string]bool) []string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

func find(fam, scope, member, key string) *Row { // UNIQUE(family_id,scope,member_id,key)：只在会话家庭内找
	for i := range set {
		if set[i].fam == fam && set[i].scope == scope && set[i].member == member && set[i].key == key && !set[i].del {
			return &set[i]
		}
	}
	return nil
}
func valOf(fam, scope, member, key string) string {
	if r := find(fam, scope, member, key); r != nil {
		return fmt.Sprintf("%s（v%d）", r.val, r.ver)
	}
	return "未设 → 读侧回落到系统默认 " + sysDefault[key] + "（回落只发生在读取合并，写入永远 400 不回落）"
}
func effCur(fam string) string { // 报表页的展示符号取家庭级 currency；参数永远是会话家庭
	if r := find(fam, "family", "", "currency"); r != nil {
		return r.val
	}
	return sysDefault["currency"]
}
func netCents(fam string) (int64, int) { // 服务端唯一的聚合口径：family_id 恒进、软删不进；金额全程整数
	n, c := int64(0), 0
	for _, t := range led {
		if t.fam == fam && !t.del {
			n, c = n+map[bool]int64{true: t.cents, false: -t.cents}[t.typ == "income" || t.typ == "refund"], c+1
		}
	}
	return n, c
}

// ---- 权限层的唯一入口 ----
// 检查顺序（顺序即语义，注释里点名每一步为什么在前）：
//  1. 无会话 → 401（连「你要动谁」都还不知道，谈不上授权）；
//  2. 客户端显式声明的家庭 ≠ 会话家庭 → 404（越权：想动别家；响应与「不存在」逐字节相同）；
//  3. 参数形状 → 400 给合法形状（未知 key / 口径类落成员级 / 值非法 / 缺 crid），绝不静默回落；
//  4. 授权：家庭级写只有监护人可（成员 → 403，够得着但没资格）；成员级只能本人或本家监护人代写，
//     改别人的成员键 → 404（与「不存在」同体，不确认那个成员在不在）；
//  5. 幂等 → 命中直接返回首次结果；6. 乐观锁 → 版本不符 409；7. 落库 + 审计。
func handle(r req) (int, string) {
	if r.s.fam == "" {
		return 401, `401 {"error":"unauthenticated"} —— 会话里没有 family_id：读、写、报表一律 401，不是 403（403 得先确认你是谁）`
	}
	if r.qFam != "" && r.qFam != r.s.fam {
		return 404, notFound // query/body 塞的 family_id 与会话不同 = 越权；不 echo 入参，不确认 fam-B 存在
	}
	fam := r.s.fam // 生效家庭恒等于会话家庭：下面所有查询只用这个变量
	if r.verb == "report" {
		n, c := netCents(fam)
		return 200, fmt.Sprintf(`200 {"family_id":"%s","txn_count":%d,"net_cents":%d,"display":"%s","budget_2026-Q4":"%s"}`, fam, c, n, sym[effCur(fam)]+money(n), budShow(fam, "2026-Q4"))
	}
	if r.verb == "read" {
		if r.scope == "member" && !readable(r.s, fam, r.member) {
			return 404, notFound // 不是本人、也不是本家监护人要读的成员级键：当作不存在
		}
		return 200, fmt.Sprintf("200 family=%s（取自会话）scope=%-6s member=%-6s %s = %s", fam, dash(r.scope), dash(r.member), r.key, valOf(fam, r.scope, r.member, r.key))
	}
	// 写侧
	if dict[r.key] == "" {
		return 400, "400 未知 key：合法 key 只有 " + keysOf(dict) + "（写侧未知 key 不写、不读、不回落）"
	}
	if r.scope == "member" && dict[r.key] == cal {
		return 400, "400 口径类 " + r.key + " 不允许成员级：合法形状 scope=family、member 留空（d29 的合并优先级）"
	}
	if !inSet(r.val, legal[r.key]) {
		return 400, "400 " + r.key + " 值非法 → 合法形状 " + legal[r.key] + "；禁止回落 " + sysDefault[r.key]
	}
	if r.crid == "" {
		return 400, "400 写接口必须带 client_request_id：幂等键 UNIQUE(family_id, client_request_id)，不带就把幂等交给运气（d30）"
	}
	if r.scope == "family" {
		if r.s.role != "guardian" {
			return 403, "403 角色不足：已登录、就在本家庭、这行你也看得见，但成员无权改家庭级口径 → 403（区别于 404：这里没有任何「不存在」）"
		}
	} else if !writable(r.s, fam, r.member) {
		return 404, notFound // 改别人的成员设置：不确认那个成员存不存在
	}
	if v := idem[fam+"|"+r.crid]; v != "" {
		return 200, "200 命中幂等（crid=" + r.crid + "）→ 直接返回首次结果 value=" + v + "；库里不写第二行、审计不记第二条"
	}
	mk := map[bool]string{true: r.member, false: ""}[r.scope == "member"]
	if row := find(fam, r.scope, mk, r.key); row != nil && row.ver != r.ver {
		return 409, fmt.Sprintf("409 版本冲突：你基于 v%d，库里已是 v%d（与 S10 d24、d30 同构，响应带双方版本）", r.ver, row.ver)
	}
	old := "（该 scope 首次建行）"
	if row := find(fam, r.scope, mk, r.key); row != nil {
		old = row.val
		row.val, row.ver = r.val, row.ver+1
	} else {
		set = append(set, Row{fam, r.scope, mk, r.key, r.val, 1, false})
	}
	idem[fam+"|"+r.crid] = r.val
	aud = append(aud, fmt.Sprintf("    au-%02d family=%-5s who=%-5s %-6s member=%-6s %-16s %s → %s v%d when=%s crid=%s", len(aud)+1, fam, r.s.id, r.scope, dash(mk), r.key, old, r.val, find(fam, r.scope, mk, r.key).ver, fixedNow.Format("2006-01-02 15:04:05"), r.crid))
	return 200, fmt.Sprintf("200 真实写 1 行：family=%s（会话）%s.%s → %s；审计记 who/when/old/new", fam, map[bool]string{true: "member:" + mk, false: "family"}[r.scope == "member"], r.key, r.val)
}
func readable(s sess, fam, member string) bool { // 成员级读的可见性：本人，或本家庭监护人
	return inFam(fam, member) && (s.id == member || s.role == "guardian")
}
func writable(s sess, fam, member string) bool { // 代写的唯一合法通道：本家庭监护人；成员只能写自己
	return inFam(fam, member) && (s.id == member || s.role == "guardian")
}
func inFam(fam, member string) bool { // 只按会话家庭的成员名册认人；别家成员在本家 = 不存在
	for _, m := range famMembers[fam] {
		if m == member {
			return true
		}
	}
	return false
}
func budShow(fam, p string) string { // 「未设该周期预算」与权限层无关：不许折算、不许拿月档顶上
	if b := bud["quarter:"+p]; b != 0 {
		return sym[effCur(fam)] + money(b)
	}
	if b := bud["month:"+p]; b != 0 {
		return sym[effCur(fam)] + money(b)
	}
	return "未设该周期预算"
}

func readSQL(r req) string { // 每条读取 SQL 都带 family_id = 会话家庭；qFam 根本不进这条语句
	scope, member := "family", ""
	if r.scope == "member" {
		scope, member = "member", r.member
	}
	q := gdb.Table(setTbl).Select("key, value, version").
		Where("family_id = ? AND deleted_at IS NULL AND scope = ? AND member_id = ? AND key = ?", r.s.fam, scope, member, r.key).
		Find(&[]map[string]any{})
	return brk.Replace(q.Statement.SQL.String() + fmt.Sprintf(" -- 绑参：%v", q.Statement.Vars))
}
func writeSQL(r req) string { // 写侧：乐观锁 version 进 WHERE，family_id 进 WHERE —— 0 行受影响 = 409
	mk := map[bool]string{true: r.member, false: ""}[r.scope == "member"]
	return brk.Replace(gdb.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Table(setTbl).Where("family_id = ? AND scope = ? AND member_id = ? AND key = ? AND version = ?", r.s.fam, r.scope, mk, r.key, r.ver).
			Updates(map[string]any{"value": r.val, "version": r.ver + 1, "updated_by": r.s.id, "updated_at": fixedNow})
	}))
}

func fanOut[X any](xs []X, f func(X) string) string { // 并发成行：每个 goroutine 只写自己那个下标，收集后按整行文本排序
	var wg sync.WaitGroup
	out := make([]string, len(xs))
	wg.Add(len(xs))
	for i, x := range xs {
		go func(i int, x X) { defer wg.Done(); out[i] = f(x) }(i, x)
	}
	wg.Wait()
	sort.Strings(out)
	return strings.Join(out, "\n")
}

func dumpSet(title string) int { // 逐行摊开设置表并返回 fam-B 行数；写段全串行，顺序天然确定
	nB := 0
	fmt.Printf("  %s（family_setting %d 行 ｜ setting_audit %d 行）\n", title, len(set), len(aud))
	for _, r := range set {
		nB += yes[r.fam == famB]
		fmt.Printf("    %s scope=%-6s family=%-5s member=%-6s %-16s = %-22s v%d\n", map[bool]string{true: "·", false: "×"}[!r.del], r.scope, r.fam, dash(r.member), r.key, r.val, r.ver)
	}
	fmt.Println(strings.Join(aud, "\n"))
	return nB
}

func main() {
	hdr("1. 权限层的世界：会话只认 fam-A（监护人 u-mom/u-dad、成员 u-kid）；fam-B 存在但本机没有跨族入口")
	fmt.Printf("  会话：sNo=%+v（未登录） sMom=%+v sKid=%+v sBob=%+v\n  名册：famA=%v famB=%v\n  字典（%d 条）：口径类 %s 只能家庭级；显示类 %s 才可被监护人代写\n", sNo, sMom, sKid, sBob, famMembers[famA], famMembers[famB], len(dict), keysOf(map[string]string{"currency": cal, "default_account": cal, "period_start": cal, "timezone": cal}), keysOf(map[string]string{"compact_view": disp, "report_cols": disp}))
	dumpSet("种子表（· = 活跃、× = 墓碑；本程序种子里无墓碑行，删除路径在 d30）")
	rq := req{verb: "read", s: sMom, qFam: famB, scope: "member", member: "u-kid", key: "compact_view"} // 会话 fam-A、query 偏要塞 fam-B
	rs, ws := readSQL(rq), writeSQL(req{verb: "write", s: sMom, scope: "family", key: "currency", val: "USD", crid: "req-1", ver: 5})
	fmt.Printf("  -- DryRun 读取（本机无 PostgreSQL：只生成真 Postgres 方言、未连库未执行；query 塞的 %s 没进这条语句）\n%s\n  -- DryRun 写入（乐观锁 version 进 WHERE）\n%s\n", famB, rs, ws)
	ck(strings.Contains(rs, "family_id") && strings.Contains(rs, famA) && !strings.Contains(rs, famB) && strings.Contains(ws, "version") && strings.Contains(ws, famA), "读/写 SQL 都带会话 family_id", fmt.Sprintf("读侧 SQL %d 字符：绑参 family_id = %s、query 塞的 %s 一次都没进；写侧 ToSQL 已把入参内联，WHERE 同时含 version 条件与 family_id = %s", len(rs), famA, famB, famA))
	hdr("2. 读取侧：未登录 401 / 本家庭 200 / 非本家庭 404")
	for _, q := range []req{
		{verb: "read", s: sNo, scope: "family", key: "timezone"},
		{verb: "read", s: sMom, scope: "family", key: "timezone"},
		{verb: "read", s: sMom, scope: "member", member: "u-kid", key: "compact_view"},
		{verb: "read", s: sKid, scope: "member", member: "u-mom", key: "report_cols"},
		{verb: "read", s: sMom, scope: "member", member: ghost, key: "compact_view"},
		{verb: "read", s: sMom, scope: "member", member: "u-bob", key: "report_cols", qFam: famB},
	} {
		c, d := handle(q)
		fmt.Printf("  %s %-6s fam=%-6s 读 %-6s %-6s/%-14s → %d ｜ %s\n", map[bool]string{true: "✅", false: "·"}[c != 200], q.verb, map[bool]string{true: "（无会话）", false: q.s.fam}[q.s.fam == ""], dash(q.scope), dash(q.member), q.key, c, d)
		if c == 404 {
			distinct4 = append(distinct4, d)
		}
	}
	h1, k1, g1 := cod(req{verb: "read", s: sNo}), cod(req{verb: "read", s: sKid, scope: "member", member: "u-mom", key: "report_cols"}), cod(req{verb: "read", s: sMom, scope: "member", member: "u-bob", key: "report_cols"})
	ck(k1 == 404 && h1 == 401 && g1 == 404, "三码分工：401/404/404 不混用", fmt.Sprintf("未登录 → %d；成员读别人的成员键 → %d（不是 403：不确认那个键对这个成员可见）；本家会话点名读别家成员 → %d（与上一行同款，不确认 u-bob 存在）", h1, k1, g1))
	hdr("3. 写入侧：跨家庭一律 404 不是 403；family_id 只从会话取，query 塞了也不认")
	vb := find(famB, "family", "", "currency").ver
	for _, q := range []req{
		{verb: "write", s: sNo, scope: "family", key: "currency", val: "USD", crid: "req-x-0", ver: 5},
		{verb: "write", s: sMom, scope: "family", key: "currency", val: "USD", crid: "req-x-1", ver: 5, qFam: famB},
		{verb: "write", s: sMom, scope: "family", key: "currency", val: "CHF", crid: "req-x-2", ver: 5, qFam: famB},
	} {
		c, d := handle(q)
		fmt.Printf("  %s fam=%-5s（会话）query 塞 %-5s PUT %s=%-4s → %d ｜ %s\n", map[bool]string{true: "·", false: "✅"}[c == 404], q.s.fam, dash(q.qFam), q.key, q.val, c, d)
		if c == 404 {
			distinct4 = append(distinct4, d)
		}
