// parseKey：d17 那道门的实现——形状不对或 canonical 往返不等就是 error；没有一条分支回落默认档或当前期。
func parseKey(k Kind, s string) (time.Time, error) {
	if _, ok := legalWin[k]; !ok {
		return time.Time{}, fmt.Errorf("kind=%q 未知：只有 month / quarter / year 三档，没有「默认档」可回落", string(k))
	}
	if k == KQuarter && (len(s) != 7 || s[4:6] != "-Q" || s[6] < '1' || s[6] > '4') {
		return time.Time{}, fmt.Errorf("window=%q 非法：%s 档形如 %s；不猜窗、不回落当前期", s, k, shape[k])
	}
	st := time.Time{}
	if k == KQuarter {
		st = day0(atoi4(s[:4]), int(s[6]-'0'-1)*3+1, 1)
	} else if t, e := time.ParseInLocation(map[Kind]string{KMonth: "2006-01", KYear: "2006"}[k], s, famLoc); e != nil {
		return time.Time{}, fmt.Errorf("window=%q 非法：%s 档形如 %s；不猜窗、不回落当前期", s, k, shape[k])
	} else {
		st = t
	}
	if got := bucketKey(k, st); got != s {
		return time.Time{}, fmt.Errorf("window=%q 不是规范桶键：这一期真实的 %s 键是 %q；不猜窗、不回落当前期", s, k, got)
	}
	return st, nil
}
func handle(k Kind, s string) (int, string) { // 严格版：解析失败 = 400，信息里必须给合法形状
	st, err := parseKey(k, s)
	if err != nil {
		return 400, err.Error()
	}
	return 200, fmt.Sprintf("窗 [%s, %s) 稠密出桶 %d 个", at(st), at(bucketEnd(k, st)), len(bucketKeys(k, st, bucketEnd(k, st))))
}
func fallback(k Kind, s string) string { // 反面对照：「解析失败就换当前期」那种写法会做什么（本程序无此分支）
	if _, e := parseKey(k, s); e == nil {
		return "—"
	}
	if _, ok := legalWin[k]; !ok {
		return "200 + 未知档按空窗出 0 个桶"
	}
	return fmt.Sprintf("200 + 静默换成当前期 %q", bucketKey(k, fixedNow))
}

