func aggAt(fam, k string) (net, spend int64, cnt int) { // 桶内累加唯一现场：与下面 aggSQL 那段 WHERE 同语义
	for _, t := range ledger {
		if t.fam == fam && !t.del && bucketKey(KMonth, t.at) == k {
			net, spend, cnt = net+famSign[t.kind]*t.cents, spend+spendSign[t.kind]*t.cents, cnt+1
		}
	}
	return
}
func k2time(k string) time.Time { t, _ := parseKey(KMonth, k); return t }
func rollTo(to Kind, from []string, vals []int64) map[string]int64 {
	out := map[string]int64{}
	for i, k := range from {
		out[bucketKey(to, k2time(k))] += vals[i]
	}
	return out
} // 低阶桶 → 高阶桶只认桶 start（d15）
func prefix(row []int64, start int64) []int64 {
	out, run := make([]int64, len(row)), start
	for i, n := range row {
		run += n
		out[i] = run
	}
	return out
}

type Filter struct {
	fam          string
	k            Kind
	period       string
	limit        int
	noDel        bool
	curAt, curID string
} // 一个 Filter 生成同一段 WHERE：查询侧分页、导出侧全量
func (f Filter) win() (time.Time, time.Time) {
	st, e := parseKey(f.k, f.period)
	if e != nil {
		panic(e)
	}
	return st, bucketEnd(f.k, st)
} // handler 层早把它打成 400
func sel(rows []Txn, f Filter) []Txn {
	st, en := f.win()
	out := []Txn{}
	for _, t := range rows {
		if t.fam != f.fam || (!f.noDel && t.del) || t.at.Before(st) || !t.at.Before(en) {
			continue
		} // family_id 恒进、软删不进、右开
		if f.curID != "" {
			c, _ := time.Parse(time.RFC3339Nano, f.curAt)
			if !(t.at.Before(c) || (t.at.Equal(c) && t.id < f.curID)) {
				continue
			}
		} // 严格小于游标行：同秒靠 id 分全序
		out = append(out, t)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].at.Equal(out[j].at) {
			return out[i].id > out[j].id
		}
		return out[i].at.After(out[j].at)
	})
	if f.limit > 0 && len(out) > f.limit {
		out = out[:f.limit]
	}
	return out
}
func fieldsOf(t Txn) map[string]string {
	return map[string]string{"txn_id": t.id, "family_id": t.fam, "occurred_at": t.at.Format(time.RFC3339Nano), "occurred_at_home_tz": at(t.at), "type": t.kind, "amount_cents": fmt.Sprint(t.cents), "category_id": t.cat, "category_name": catName[t.cat], "has_receipt": fmt.Sprint(t.rec), "reversal_of": t.revOf}
}
func idSet(rs []Txn) map[string]bool {
	m := map[string]bool{}
	for _, t := range rs {
		m[t.id] = true
	}
	return m
}
func sumCents(rs []Txn) (v int64) {
	for _, t := range rs {
		v += t.cents
	}
	return
}
func extraIDs(a []Txn, b map[string]bool) string {
	o := []string{}
	for _, t := range a {
		if !b[t.id] {
			o = append(o, t.id)
		}
	}
	sort.Strings(o)
	return strings.Join(o, " ")
}
func inList(s string, l []string) bool {
	for _, x := range l {
		if x == s {
			return true
		}
	}
	return false
}
func requestCol(c string) (int, string) {
