type Bucket struct {
	Period   string `json:"period"`
	NetCents int64  `json:"net_cents"`
}
type Payload struct {
	OpeningCents int64    `json:"opening_cents"`
	Buckets      []Bucket `json:"buckets"`
} // 前端只拿得到这份：一个 cum_cents 都没有
func frontendCum(p Payload) []int64 {
	run, out := p.OpeningCents, []int64{}
	for _, b := range p.Buckets {
		run += b.NetCents
		out = append(out, run)
	}
	return out
} // 逐字等价于前端会写的那三行
func frontBad(p Payload) (ks []string, nv, out []int64) {
	run := p.OpeningCents
	for _, b := range p.Buckets {
		if b.NetCents == 0 {
			continue
		}
		run += b.NetCents
		ks, nv, out = append(ks, b.Period), append(nv, b.NetCents), append(out, run)
	}
	return
} // ❌ 把 net_cents==0 的格子当「没有这一期」滤掉
func cumDiff(keys []string, nets, srv, cli []int64, tag string, show bool) (bad int, mx int64) {
	if show {
		fmt.Printf("  %-9s %-11s %-15s %-15s %-9s %s\n", "period", "net_cents", "A 服务端 cum", "B "+tag, "diff(分)", "判定")
	}
	for i, k := range keys {
		if i >= len(cli) {
			bad++
			continue
		}
		d := cli[i] - srv[i]
		bad += yes[d != 0]
		if a := abs(d); a > mx {
			mx = a
		}
		if show {
			fmt.Printf("  %-9s %-11d %-15s %-15s %-9d %s\n", k, nets[i], money(srv[i]), money(cli[i]), d, mark[d == 0])
		}
	}
	return
}

type ev struct {
	topic, fam, src, crid, code string
	next                        time.Time
}
type noteRow struct {
	fam, kind, dedup string
	read             bool
}
type dueRow struct {
	sys, sid, kind, fam string
	ri                  int
	next                time.Time
}
type rule struct {
	Code, Fam, kind, cat string
	cents                int64
	next                 time.Time
	active               bool
	fires                int
}

var subs = map[string][]func(ev) int{}
var count, delivered, genTxn = map[string]int{}, map[string]int{}, map[string]bool{}
var notes []noteRow
var dues []dueRow
var rules = []rule{{"rent-house", famA, "expense", "cat-house", 180000, day0(2026, 12, 5).Add(9 * time.Hour), true, 0}, {"tuition-learn", famA, "expense", "cat-learn", 260000, day0(2026, 12, 5).Add(9 * time.Hour), true, 0}, {"pet-vet", famA, "expense", "cat-shop", 30000, day0(2026, 12, 20).Add(9 * time.Hour), false, 0}} // 第三条已暂停：只撤注，不进中心
var directFire, bizTimers, timers, owner int
var sched bool

func sub(t string, f func(ev) int) { subs[t] = append(subs[t], f) }
func emit(e ev) int {
	if owner == 0 {
		directFire++
	}
	count[e.topic]++
	delivered[e.src]++
	n := 0
	for _, f := range subs[e.topic] {
		n += f(e)
	}
	return n
}                  // 只有走 pub* 才算「唯一来源」
func pub(e ev) int { owner++; defer func() { owner-- }(); return emit(e) }
func pubBudget(fam, period string) int {
	return pub(ev{"finance.budget.exceeded", fam, fam + "|finance.budget.exceeded|" + period, "fin-" + fam + "-" + period, "", clock})
}
func pubDue(r rule, revoke bool) int {
	t := r.Code + ".due.registered"
	if revoke {
		t = r.Code + ".due.revoked"
	}
	return pub(ev{t, r.Fam, "finance|" + r.Code + "|recurring_rule", "due-" + t, r.Code, r.next})
}
func pubReminder(fam, crid string) int {
	return pub(ev{"finance.recurring.reminder", fam, "finance|" + crid + "|reminder", crid, "", clock})
}
func note(e ev, kind string) int {
	if !famSet[e.fam].Alert {
		return 0
	}
	for _, x := range notes {
		if x.dedup == e.src {
			return 0
		}
	}
	notes = append(notes, noteRow{e.fam, kind, e.src, false})
	return 1
} // 设置关 → 不落库；同 dedup → no-op（等价 ON CONFLICT DO NOTHING）
func unread(fam string) int {
	n := 0
	for _, x := range notes {
		if x.fam == fam && !x.read {
			n++
		}
	}
	return n
} // 全项目唯一的未读数来源：通知表里 read_at IS NULL 的行数
func countNotes(kind string) int {
	n := 0
	for _, x := range notes {
		if x.kind == kind {
			n++
		}
	}
	return n
}
func markRead(fam string) int {
	for i := range notes {
		if notes[i].fam == fam {
			notes[i].read = true
		}
	}
	return unread(fam)
}
func rIdx(code string) int {
	for i, r := range rules {
		if r.Code == code {
			return i
		}
	}
	return -1
}
func dueAdd(e ev) int {
	for _, d := range dues {
		if d.sid == e.src {
			return 0
		}
	}
	dues = append(dues, dueRow{"finance", e.src, "recurring_rule", e.fam, rIdx(e.code), e.next})
	timers++
	return 1
} // 幂等键 (source_system, source_id, kind)
func dueDel(e ev) int {
	for i, d := range dues {
		if d.sid == e.src {
			dues = append(dues[:i], dues[i+1:]...)
			timers--
			return 1
		}
	}
	return 0
}
func setClock(t time.Time) {
	if owner == 0 && !sched {
		bizTimers++
	}
	clock = t
} // 只有到期中心推时钟；业务面自己推一次就记一次违规
func schedulerTick(t time.Time) int {
	sched = true
	setClock(t)
	n := tickDue()
	sched = false
	return n
}
func tickDue() (f int) { // 扫 next_at <= clock：生成流水走 client_request_id 幂等，再把 next_at 推到下一期
	for i := range dues {
		if dues[i].next.After(clock) {
			continue
		}
		ri, crid := dues[i].ri, ""
		crid = fmt.Sprintf("rec-%s@%s", rules[ri].Code, dues[i].next.Format("2006-01-02"))
		if !genTxn[crid] {
			genTxn[crid] = true
			ledger = append(ledger, Txn{"R-" + crid, rules[ri].Fam, rules[ri].kind, rules[ri].cat, "周期记账到点自动生成", rules[ri].cents, dues[i].next, false, false, ""})
			f += pubReminder(rules[ri].Fam, crid)
			rules[ri].fires++
		}
		dues[i].next = dues[i].next.AddDate(0, 1, 0)
	}
	return
}
func budgetRow(k string, sp int64) (string, int) { // 响应体与页面渲染同一份数据：库里无行 → not_set +「未设该周期预算」
	bc, has := budgetRows[famA+"|"+k]
	var cents any
	state := "not_set"
	if has {
		cents, state = bc, "set"
	}
	usage, render := "—", "未设该周期预算"
	if has {
		usage, render = fmt.Sprintf("%d%%", sp*100/bc), map[bool]string{true: fmt.Sprintf("超支 %s 元", money(sp-bc)), false: fmt.Sprintf("预算内 %s 元", money(bc-sp))}[sp > bc]
	}
	return fmt.Sprintf("  %-10s %-11s %-18s %-9s %-7s %-18s %s\n", k, money(sp), map[bool]string{true: money(bc), false: "（库里无预算行）"}[has], state, usage, render, mark[has]), yes[!has && cents != nil] // 后者＝折算值漏进响应体的行数
}

// ---------- 本机无 PostgreSQL：GORM DryRun 生成真实 Postgres 语句（DisableAutomaticPing + 固定 NowFunc），只出文本不落库 ----------
type Notify struct{ ID, FamilyID, Kind, DedupKey, ClientRequestID string }

func (Notify) TableName() string { return "homeos_notification" }
func dryDB() *gorm.DB {
	db, e := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	if e != nil {
		panic(e)
	}
	return db
}
func aggSQL(db *gorm.DB, fam string, from, to time.Time) string {
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Table("finance_transaction").Select("to_char(occurred_at AT TIME ZONE ?, 'YYYY-MM') AS bucket_key, SUM(amount_cents) AS net_cents, COUNT(*) AS txn_count").Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND occurred_at < ?", fam, from.Format(time.RFC3339Nano), to.Format(time.RFC3339Nano)).Group("bucket_key").Order("bucket_key").Find(&[]map[string]any{})
	})
}
func noteSQL(db *gorm.DB) string {
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Table("homeos_notification").Select("family_id, dedup_key, client_request_id, created_at").Where("family_id = ? AND dedup_key = ?", famA, famA+"|finance.budget.exceeded|2026-07").Find(&[]map[string]any{})
	})
} // (family_id, dedup_key) 唯一

